"""Static-site generator for the real brokenmeta.gg production site.

Reads the exact same pipeline output the Claude Artifact prototype uses
(data/output/*.json) and renders real, crawlable, per-page-SEO static HTML
into site_build/dist/ -- one page per comp, one per champion, plus list
pages, sitemap.xml and robots.txt. No fabricated content: every number here
traces back to the same real Riot Match-V1 data as the Artifact version.

Run from anywhere:  py site_build/build_site.py
Output:              site_build/dist/  (upload this folder's CONTENTS to
                      Hostinger's public_html/)
"""
from __future__ import annotations

import hashlib
import json
import re
import shutil
import subprocess
import sys
from collections import Counter, defaultdict
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone
from pathlib import Path

import requests
from jinja2 import Environment, FileSystemLoader
from markupsafe import Markup

ROOT = Path(__file__).resolve().parent
PROJECT = ROOT.parent
sys.path.insert(0, str(PROJECT / "src"))
from tft_tracker.champion_images import (  # noqa: E402
    build_augment_data, build_champion_image_map, build_family_docs, build_full_item_catalog, build_item_image_map,
    build_locale_champion_text_map, build_locale_item_text_map, build_locale_trait_name_map,
    build_team_planner_codes, build_trait_data, classify_item_offense,
)
from tft_tracker import config as tft_config  # noqa: E402 -- MIN_SAMPLE_FOR_TIER, shared with the rank filter's client-side re-tiering (see rank_filter_data below)
from tft_tracker.tierlist import TIER_BUCKETS, SHRINKAGE_PRIOR_GAMES  # noqa: E402 -- same reason

OUT = PROJECT / "data" / "output"
DIST = ROOT / "dist"
# Persistent, git-tracked (unlike data/output/*.json, which is gitignored and
# gets fully overwritten by every refresh) -- see build_hors_meta_comps() for
# why this exists: a comp that doesn't clear MIN_PLAY_COUNT in one refresh's
# sample isn't necessarily a dead comp, just an unlucky sample, and shouldn't
# silently 404 an already-published/indexed URL.
COMP_ARCHIVE_PATH = PROJECT / "data" / "comp_archive.json"
SET_MUTATOR = "TFTSet18"
# Single source of truth for the human-facing set name used in SEO-critical
# spots (titles, on-page kickers, intro copy): "TFT" is what players actually
# type into Google (confirmed via Google Trends: "tft" outweighs "comp tft"
# ~15:1 in France), so this is deliberately the abbreviation, not "Teamfight
# Tactics Set 18". Same string in FR and EN -- real players use it unchanged
# in both languages. Bump this (and SET_MUTATOR) together when Set 19 ships.
SET_LABEL = "TFT Set 18"
BASE_URL = "https://brokenmeta.gg/"

# PWA service worker, served from DIST root so its scope covers the whole
# site (FR root + /en/) with one registration. Deliberately two different
# strategies per request type: navigations go network-first (a stats site
# whose whole value is fresh data must never serve yesterday's tier list
# just because it's cached -- the cache here is purely an offline
# fallback), while static assets (css/img/fonts) go stale-while-revalidate
# since those rarely change and don't need to block on the network.
SERVICE_WORKER_JS = """// BrokenMeta.gg service worker -- offline fallback + faster repeat visits.
// Regenerated by site_build/build_site.py; do not edit dist/sw.js by hand.
const CACHE = 'brokenmeta-v1';
const APP_SHELL = ['/', '/assets/css/style.css', '/favicon.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(APP_SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return; // leave fonts CDN / analytics alone

  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req)
        .then((res) => { caches.open(CACHE).then((cache) => cache.put(req, res.clone())); return res; })
        .catch(() => caches.match(req).then((cached) => cached || caches.match('/')))
    );
    return;
  }

  event.respondWith(
    caches.match(req).then((cached) => {
      const fresh = fetch(req)
        .then((res) => { caches.open(CACHE).then((cache) => cache.put(req, res.clone())); return res; })
        .catch(() => cached);
      return cached || fresh;
    })
  );
});
"""

# Was 10 (matching the Artifact's export_data.py), same as everywhere real
# TFT trackers set a low floor -- but with the raw match cache now spanning
# 20k+ real ranked games instead of ~4-5k, a 10-game comp can cross that bar
# on pure variance (TFT placement has high game-to-game swing). Raised to
# 100 on 2026-09-06 after checking the actual distribution: ~537 comps
# qualify at 10 vs ~158 at 100, and every comp at 100+ games has a real
# statistical base instead of a lucky handful of games. The Artifact
# (export_data.py) still uses 10 -- deliberately diverged, not kept in sync,
# since it doesn't have this site's real match volume to support a higher bar.
MIN_PLAY_COUNT = 100
MAX_AVG_PLACEMENT = 6.00
MIN_CORE_BOARD_SIZE = 7

TIER_VAR = {"S": "var(--red)", "A": "var(--gold)", "B": "var(--teal)", "C": "var(--gray)", "?": "var(--gray)",
            "HM": "var(--text-faint)"}

# Progressive enhancement only -- every comp is already in the static HTML
# (crawlable, works with JS off); Région/Rang are real separate pages, but
# Type (Reroll/Fast/Slow) and search don't need their own data slice, just
# combined show/hide among rows already rendered on the current page.
# Ported from the Artifact's matchesSearch()/render() filter chain, with
# each row's search haystack precomputed server-side into data-search
# (see build_row_vm's "search_blob") instead of scraping DOM text.
#
# Two different page shapes use this: list_page.html (a single flat #rows
# list, plus the Type chips) and overview.html (the homepage/scope preview,
# grouped into one [data-tier-group] block per tier, no Type chips there).
# Selecting every ".comp-row" on the page (not scoped to #rows) covers
# both; group visibility is handled separately so an emptied-out preview
# group (e.g. "Tier S" has zero matches) disappears header and all, not
# just its rows. The two empty-state messages ("no comp matches this
# filter" vs "...this search") come from window.BM_I18N_EMPTY_* set by
# each template's own <script>, so this one shared file needs no
# per-language copy, and works whether or not BM_I18N_EMPTY_FILTER is
# defined at all (overview.html only ever needs the search one, since it
# has no Type filter to produce a filter-only empty state).
LIST_FILTERS_JS = """
(function () {
  var rows = Array.prototype.slice.call(document.querySelectorAll('.comp-row'));
  if (!rows.length) return;
  var groups = Array.prototype.slice.call(document.querySelectorAll('[data-tier-group]'));
  var bar = document.getElementById('typeFilterBar');
  var searchInput = document.getElementById('compSearch');
  var emptyState = document.getElementById('emptyState');
  var activeType = 'ALL';

  // Homepage only (see macros.html's comp_summary_row): a row past the
  // top-15-per-tier default view ships its unit/item board as a JSON blob
  // instead of real <img> markup -- real icon markup for ~90% of the
  // comps most visitors never scroll to was most of the homepage's DOM
  // weight (SEO/perf audit, 2026-09-16). Built for real the first time
  // this row is actually about to be shown (search match or a rank-filter
  // recombination puts it back in view), then never touched again.
  var STAR_SVG_UNIT = '<svg viewBox="0 0 24 24"><path d="M12 2.5l2.97 6.28 6.93.7-5.13 4.75 1.4 6.87L12 17.9l-6.17 3.2 1.4-6.87-5.13-4.75 6.93-.7z"/></svg>';
  function hydrateRow(row) {
    var el = row.querySelector('.units-row[data-units-lazy]');
    if (!el) return;
    var units;
    try { units = JSON.parse(el.dataset.unitsLazy); } catch (e) { units = null; }
    el.removeAttribute('data-units-lazy');
    if (!units) return;
    var root = window.BM_ROOT || '';
    el.innerHTML = units.map(function (u) {
      var corners = u.is_top ? '<span class="unit-corner tl"></span><span class="unit-corner tr"></span><span class="unit-corner bl"></span><span class="unit-corner br"></span>' : '';
      var stars = u.three_star ? '<span class="star-row">' + STAR_SVG_UNIT + STAR_SVG_UNIT + STAR_SVG_UNIT + '</span>' : '';
      var itemsHtml = (u.shown_items || []).map(function (item) {
        return '<img class="item-icon" src="' + root + 'assets/items/' + item.slug + '.png" alt="' + item.name + '" title="' + item.name + '" loading="lazy">';
      }).join('');
      return '<div class="unit-cell"><div class="unit-icon-wrap">' + corners
        + '<img class="unit-icon champ-link-icon" src="' + root + 'assets/champions/' + u.slug + '.png" alt="' + u.champion + '" loading="lazy" style="border-color:var(--cost-' + (u.cost || 1) + ')" data-champ-slug="' + u.slug + '" data-champ-href="' + root + 'champions/' + u.slug + '/">'
        + stars + '</div><div class="unit-items">' + itemsHtml + '</div></div>';
    }).join('');
  }

  function applyFilters() {
    var q = (searchInput ? searchInput.value.trim().toLowerCase() : '');
    var visible = 0;
    rows.forEach(function (row) {
      var typeOk = activeType === 'ALL' || row.dataset.playstyleCat === activeType;
      var searchOk = !q || (row.dataset.search || '').indexOf(q) !== -1;
      // rankHidden is owned by assets/js/rank-filter.js (homepage only) --
      // it's how the 15-per-tier preview cap AND the rank checkbox filter
      // both hide rows, so a comp-row's real visibility is normally the AND
      // of all three, computed in this one place. EXCEPT while actively
      // searching: a real bug report caught this -- typing an exact comp
      // name (e.g. "greenfather tristana", ranked #80 of 95 in its tier,
      // so outside the top-15 preview) matched searchOk fine but still
      // never appeared, because the preview cap's rankHidden=true silently
      // won the AND. A text search is an explicit "find this specific
      // comp" intent, so it should surface any real match regardless of
      // the preview cap -- bypass rankHidden entirely whenever there's a
      // query, instead of only defeating it for the (rare) case of a
      // comp disqualified by an actively-selected rank bracket.
      var rankOk = q ? true : row.dataset.rankHidden !== 'true';
      var show = typeOk && searchOk && rankOk;
      if (show) hydrateRow(row);
      row.style.display = show ? '' : 'none';
      if (show) visible++;
    });
    groups.forEach(function (group) {
      var groupVisible = group.querySelectorAll('.comp-row').length
        && Array.prototype.some.call(group.querySelectorAll('.comp-row'), function (r) { return r.style.display !== 'none'; });
      group.style.display = groupVisible ? '' : 'none';
    });
    if (emptyState) {
      emptyState.hidden = visible !== 0;
      if (visible === 0) {
        emptyState.textContent = q
          ? (window.BM_I18N_EMPTY_SEARCH || '').replace('__Q__', searchInput.value.trim())
          : (window.BM_I18N_EMPTY_FILTER || '');
      }
    }
  }

  if (bar) {
    bar.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-filter-type]');
      if (!btn) return;
      [].forEach.call(bar.querySelectorAll('[data-filter-type]'), function (b) { b.dataset.active = String(b === btn); });
      activeType = btn.dataset.filterType;
      applyFilters();
    });
  }
  if (searchInput) searchInput.addEventListener('input', applyFilters);
  window.BM_applyListFilters = applyFilters;
})();
"""

# Search (+ optional class filter chips) over a League glossary icon grid
# (champions or items) -- deliberately its own small script rather than
# reusing list-filters.js: that one is hardcoded to .comp-row's own
# dataset shape (data-playstyle-cat/data-search) and TFT's tier-group
# preview cap, neither of which apply here. Scoped by container id so it
# can never touch the TFT glossary's own .glossary-icon-grid pages
# (shared CSS class, deliberately not shared behavior).
LOL_GLOSSARY_FILTER_JS = """
(function () {
  var grid = document.getElementById('lolGlossaryGrid');
  if (!grid) return;
  var items = Array.prototype.slice.call(grid.querySelectorAll('.glossary-icon-item'));
  var searchInput = document.getElementById('lolGlossarySearch');
  var filterBar = document.getElementById('lolClassFilterBar');
  var emptyState = document.getElementById('lolGlossaryEmpty');
  var activeClass = 'ALL';

  function apply() {
    var q = (searchInput ? searchInput.value.trim().toLowerCase() : '');
    var visible = 0;
    items.forEach(function (el) {
      var classOk = activeClass === 'ALL' || (el.dataset.classes || '').indexOf(activeClass) !== -1;
      var searchOk = !q || (el.dataset.search || '').indexOf(q) !== -1;
      var show = classOk && searchOk;
      el.style.display = show ? '' : 'none';
      if (show) visible++;
    });
    if (emptyState) emptyState.hidden = visible !== 0;
  }
  if (filterBar) {
    filterBar.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-filter-class]');
      if (!btn) return;
      [].forEach.call(filterBar.querySelectorAll('[data-filter-class]'), function (b) { b.dataset.active = String(b === btn); });
      activeClass = btn.dataset.filterClass;
      apply();
    });
  }
  if (searchInput) searchInput.addEventListener('input', apply);
})();
"""

# Homepage-only: lets a visitor check any combination of rank brackets
# (not just click one at a time like the region/rank chips) and see the
# tier list recombine live -- see build_site.py's rank_filter_data comment
# (the math this ports from src/tft_tracker/tierlist.py) and macros.html's
# rank_filter_dropdown(). Composes with list-filters.js via the shared
# `rankHidden` dataset flag + window.BM_applyListFilters(), never touches
# board art/icons/planner code (those stay whatever the combined "all
# ranks" data already baked into the card -- only tier + the three pills
# change).
RANK_FILTER_JS = """
(function () {
  var dropdown = document.getElementById('rankFilterDropdown');
  if (!dropdown) return;
  var summaryEl = document.getElementById('rankFilterSummary');
  var applyBtn = document.getElementById('rankFilterApply');
  var checks = Array.prototype.slice.call(dropdown.querySelectorAll('.rank-option-check'));
  var rows = Array.prototype.slice.call(document.querySelectorAll('.comp-row[data-key]'));
  if (!rows.length) return;
  var groups = {};
  Array.prototype.slice.call(document.querySelectorAll('[data-tier-group]')).forEach(function (g) {
    groups[g.dataset.tierGroup] = g.querySelector('.tier-rows');
  });
  var seeFullLinks = Array.prototype.slice.call(document.querySelectorAll('.see-full-tier-link'));
  var summaryChip = dropdown.querySelector('summary');
  var I18N = window.BM_RANK_FILTER_I18N || {};

  // Snapshot the server-rendered ("all ranks", full real dataset) truth --
  // restored verbatim whenever every bracket ends up checked again, so
  // re-checking everything never leaves the page showing the smaller
  // live-collected per-bracket sample instead of the site's real numbers.
  var original = {};
  rows.forEach(function (row) {
    var pills = row.querySelectorAll('.p-value');
    original[row.dataset.key] = {
      tier: row.dataset.tier,
      rankHidden: row.dataset.previewHidden === 'true',
      placementText: pills[0] ? pills[0].textContent : '',
      top4Text: pills[1] ? pills[1].textContent : '',
      contestText: pills[2] ? pills[2].textContent : '',
      contestLevel: pills[2] ? pills[2].getAttribute('data-level') : '',
    };
    row.dataset.rankHidden = original[row.dataset.key].rankHidden ? 'true' : 'false';
  });
  if (window.BM_applyListFilters) window.BM_applyListFilters();

  var data = null;
  fetch((window.BM_ROOT || '') + 'assets/data/rank-filter.json').then(function (r) { return r.json(); }).then(function (d) { data = d; }).catch(function () {});

  function updateSummary(selected) {
    if (!summaryEl) return;
    if (selected.length === checks.length) { summaryEl.textContent = I18N.allLabel || ''; return; }
    if (selected.length === 1) {
      var opt = dropdown.querySelector('.rank-option-check[value="' + selected[0] + '"]');
      var nameEl = opt && opt.closest('.rank-option').querySelector('.rank-option-name');
      summaryEl.textContent = nameEl ? nameEl.textContent : selected[0];
      return;
    }
    summaryEl.textContent = (I18N.nSelectedTpl || '__N__').replace('__N__', String(selected.length));
  }

  function reappend(tierOf) {
    ['S', 'A', 'B', 'C'].forEach(function (tierName) {
      var rowsEl = groups[tierName];
      if (!rowsEl) return;
      rows.filter(function (row) { return tierOf(row) === tierName; })
          .forEach(function (row) { rowsEl.appendChild(row); });
    });
  }

  function resetToDefault() {
    rows.forEach(function (row) {
      var o = original[row.dataset.key];
      if (!o) return;
      row.dataset.tier = o.tier;
      row.dataset.rankHidden = o.rankHidden ? 'true' : 'false';
      var badge = row.querySelector('.tier-badge');
      if (badge) badge.textContent = o.tier;
      var pills = row.querySelectorAll('.p-value');
      if (pills[0]) pills[0].textContent = o.placementText;
      if (pills[1]) pills[1].textContent = o.top4Text;
      if (pills[2]) { pills[2].textContent = o.contestText; pills[2].setAttribute('data-level', o.contestLevel || 'Low'); }
    });
    reappend(function (row) { return original[row.dataset.key] ? original[row.dataset.key].tier : null; });
    seeFullLinks.forEach(function (a) { a.style.display = ''; });
    if (summaryChip) summaryChip.dataset.active = 'false';
    updateSummary(checks.map(function (c) { return c.value; }));
    if (window.BM_applyListFilters) window.BM_applyListFilters();
  }

  function recompute(selectedKeys) {
    if (!data) return;
    var selectedSet = {};
    selectedKeys.forEach(function (k) { selectedSet[k] = true; });

    // Sum play_count, weight-average the three rates -- correct because
    // each bracket is a disjoint slice of the same real matches (a match
    // is played at exactly one rank), same reasoning as tierlist.py
    // computing everything from one flat match list.
    var combined = {};
    Object.keys(data.comps).forEach(function (key) {
      var perBracket = data.comps[key];
      var playCount = 0, placementSum = 0, top4Sum = 0, winSum = 0;
      selectedKeys.forEach(function (b) {
        var v = perBracket[b];
        if (!v) return;
        playCount += v[0];
        placementSum += v[1] * v[0];
        top4Sum += v[2] * v[0];
        winSum += v[3] * v[0];
      });
      if (playCount > 0) {
        combined[key] = { playCount: playCount, avgPlacement: placementSum / playCount, top4Rate: top4Sum / playCount, winRate: winSum / playCount };
      }
    });

    // Same "does it get a real page" gate as build_site.py's
    // filter_quality() (board-size/all-5-cost are structural and already
    // guaranteed -- every key here already has a real /compo/ page).
    var quality = Object.keys(combined).filter(function (key) {
      var c = combined[key];
      return c.playCount >= data.min_play_count && c.avgPlacement <= data.max_avg_placement;
    });
    // Same S/A/B/C assignment as tierlist.py's build_tier_list(): rank by
    // (-top4Rate, avgPlacement) among comps with enough sample, bucket by
    // cumulative fraction.
    var ranked = quality.filter(function (key) { return combined[key].playCount >= data.min_sample_for_tier; });
    ranked.sort(function (a, b) {
      var ca = combined[a], cb = combined[b];
      return cb.top4Rate - ca.top4Rate || ca.avgPlacement - cb.avgPlacement;
    });
    var tierOf = {};
    var n = ranked.length, cursor = 0;
    data.tier_buckets.forEach(function (bucket) {
      var tierName = bucket[0], end = tierName === 'C' ? n : Math.min(n, Math.round(n * bucket[1]));
      for (var i = cursor; i < Math.max(end, cursor); i++) tierOf[ranked[i]] = tierName;
      cursor = Math.max(end, cursor);
    });

    // Contestation pill: same play-rate-percentile idea as tierlist.py,
    // over this filtered scope's own ranked comps (the broader pre-
    // quality-filter pool Python uses isn't shipped to the client) --
    // a reasonable approximation for a display-only pill, not the tier.
    var totalParticipants = 0;
    data.brackets.forEach(function (b) { if (selectedSet[b.key]) totalParticipants += b.total_participants; });
    var playRates = ranked.map(function (key) { return totalParticipants ? combined[key].playCount / totalParticipants : 0; }).sort(function (a, b) { return a - b; });
    function percentileOf(rate) {
      if (!playRates.length) return 0;
      var idx = 0;
      while (idx < playRates.length && playRates[idx] <= rate) idx++;
      return (idx / playRates.length) * 100;
    }
    function levelOf(p) { return p >= 66 ? 'High' : (p >= 33 ? 'Medium' : 'Low'); }

    rows.forEach(function (row) {
      var key = row.dataset.key, tier = tierOf[key];
      if (!tier) { row.dataset.rankHidden = 'true'; return; }
      row.dataset.rankHidden = 'false';
      row.dataset.tier = tier;
      var badge = row.querySelector('.tier-badge');
      if (badge) badge.textContent = tier;
      var c = combined[key];
      var pills = row.querySelectorAll('.p-value');
      if (pills[0]) pills[0].textContent = c.avgPlacement.toFixed(2);
      if (pills[1]) pills[1].textContent = Math.round(c.top4Rate * 100) + '%';
      if (pills[2]) {
        var p = percentileOf(totalParticipants ? c.playCount / totalParticipants : 0);
        pills[2].textContent = String(Math.round(p));
        pills[2].setAttribute('data-level', levelOf(p));
      }
    });
    reappend(function (row) { return tierOf[row.dataset.key] || null; });
    // Within each now-settled group, order by the recombined placement --
    // reappending in this sorted order both re-sorts and re-parents.
    ['S', 'A', 'B', 'C'].forEach(function (tierName) {
      var rowsEl = groups[tierName];
      if (!rowsEl) return;
      rows.filter(function (row) { return tierOf[row.dataset.key] === tierName; })
          .sort(function (a, b) { return combined[a.dataset.key].avgPlacement - combined[b.dataset.key].avgPlacement; })
          .forEach(function (row) { rowsEl.appendChild(row); });
    });
    seeFullLinks.forEach(function (a) { a.style.display = 'none'; });
    if (summaryChip) summaryChip.dataset.active = 'true';
    updateSummary(selectedKeys);
    if (window.BM_applyListFilters) window.BM_applyListFilters();
  }

  if (applyBtn) {
    applyBtn.addEventListener('click', function () {
      var selected = checks.filter(function (c) { return c.checked; }).map(function (c) { return c.value; });
      if (!selected.length) { if (summaryEl) summaryEl.textContent = I18N.noneLabel || ''; return; }
      if (selected.length === checks.length) resetToDefault();
      else recompute(selected);
      if (window.gtag) gtag('event', 'rank_filter_apply', {rank_count: selected.length, ranks: selected.join(',')});
      dropdown.removeAttribute('open');
    });
  }
})();
"""
# /contres/ page: search any comp, see who counters it and what it counters,
# site-wide -- the same "Counters" section every comp page already has
# (matchups_by_comp in main(), unrelated to this file-scope block), just
# searchable instead of scoped to one comp. Ships as one static JSON
# (matchup-finder.json, see main()) plus the already-shipped comp-index.json
# (MetaScope's worker autocomplete data, reused as-is here for the search
# box) instead of a page per comp -- hundreds of comps, most matchup
# pairs shared, so one client-side lookup beats hundreds of near-duplicate
# static pages. Renders using the exact same .fiche-matchup-row/-list
# classes as a comp page's own Counters section, so the two look identical.
COUNTER_FINDER_JS = """
(function () {
  var searchInput = document.getElementById('counterSearch');
  if (!searchInput) return;
  var resultsEl = document.getElementById('counterSearchResults');
  var outputEl = document.getElementById('counterOutput');
  var emptyEl = document.getElementById('counterEmpty');
  var selectedNameEl = document.getElementById('counterSelectedName');
  var forListEl = document.getElementById('counterForList');
  var againstListEl = document.getElementById('counterAgainstList');
  var root = window.BM_ROOT || '';
  var compIndex = null, matchupData = null;

  Promise.all([
    fetch(root + 'assets/data/comp-index.json').then(function (r) { return r.json(); }),
    fetch(root + 'assets/data/matchup-finder.json').then(function (r) { return r.json(); }),
  ]).then(function (res) {
    compIndex = res[0];
    matchupData = res[1];
  }).catch(function () {});

  function renderResults(query) {
    resultsEl.innerHTML = '';
    if (!query || !compIndex || !matchupData) { resultsEl.hidden = true; return; }
    var q = query.toLowerCase();
    var matches = [];
    for (var key in compIndex) {
      if (!matchupData[key]) continue; // only comps with real matchup data are searchable
      if (compIndex[key].display_label.toLowerCase().indexOf(q) !== -1) {
        matches.push(key);
        if (matches.length >= 8) break;
      }
    }
    if (!matches.length) { resultsEl.hidden = true; return; }
    matches.forEach(function (key) {
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'counter-result-item';
      btn.textContent = compIndex[key].display_label;
      btn.addEventListener('click', function () { selectComp(key); });
      resultsEl.appendChild(btn);
    });
    resultsEl.hidden = false;
  }

  function matchupRow(m) {
    var side = m.aheadPct >= 50 ? 'ahead' : 'behind';
    var row = document.createElement('div');
    row.className = 'fiche-matchup-row';
    row.dataset.side = side;
    var nameHtml = m.oppSlug
      ? '<a href="' + root + 'compo/' + m.oppSlug + '/" style="color:inherit">' + m.oppLabel + '</a>'
      : m.oppLabel;
    row.innerHTML =
      '<span class="m-name">' + nameHtml + '</span>' +
      '<span class="m-encounters nums">' + m.encounters + '</span>' +
      '<span class="matchup-bar-wrap"><span class="matchup-bar" style="width:' + m.aheadPct + '%"></span></span>' +
      '<span class="m-pct nums">' + m.aheadPct + '%</span>';
    return row;
  }

  function selectComp(key) {
    searchInput.value = compIndex[key].display_label;
    resultsEl.hidden = true;
    resultsEl.innerHTML = '';
    var rows = matchupData[key] || [];
    var against = rows.filter(function (m) { return m.aheadPct < 50; })
                       .sort(function (a, b) { return a.aheadPct - b.aheadPct; });
    var forUs = rows.filter(function (m) { return m.aheadPct >= 50; })
                     .sort(function (a, b) { return b.aheadPct - a.aheadPct; });
    againstListEl.innerHTML = '';
    forListEl.innerHTML = '';
    against.forEach(function (m) { againstListEl.appendChild(matchupRow(m)); });
    forUs.forEach(function (m) { forListEl.appendChild(matchupRow(m)); });
    if (selectedNameEl) selectedNameEl.textContent = compIndex[key].display_label;
    outputEl.hidden = false;
    emptyEl.hidden = true;
    if (window.gtag) gtag('event', 'counter_finder_search', {comp_key: key});
  }

  searchInput.addEventListener('input', function () {
    outputEl.hidden = true;
    renderResults(searchInput.value.trim());
  });
  document.addEventListener('click', function (e) {
    if (!e.target.closest('.counter-search-wrap')) resultsEl.hidden = true;
  });
})();
"""
# Header search (base.html's .site-search-wrap, every page site-wide) --
# one flat index (site-search.json / site-search_fr.json, see main())
# covering every champion, item, and published comp, searched client-side
# the same way list-filters.js does a comp-row's data-search: plain
# substring match, no server round-trip. Loaded lazily (only once the
# panel is actually opened) since it's fetched on every single page load
# otherwise -- most visits never touch it.
SITE_SEARCH_JS = """
(function () {
  var toggle = document.getElementById('siteSearchToggle');
  var panel = document.getElementById('siteSearchPanel');
  var input = document.getElementById('siteSearchInput');
  var resultsEl = document.getElementById('siteSearchResults');
  if (!toggle || !panel || !input || !resultsEl) return;
  var root = window.BM_ROOT || '';
  var lang = document.documentElement.lang === 'fr' ? 'fr' : 'en';
  var TYPE_LABELS = {
    fr: {champion: 'Champion', item: 'Objet', comp: 'Compo'},
    en: {champion: 'Champion', item: 'Item', comp: 'Comp'},
  }[lang];
  var EMPTY_TEXT = lang === 'fr' ? 'Aucun r\\u00e9sultat.' : 'No results.';
  var index = null, indexPromise = null;

  function loadIndex() {
    if (indexPromise) return indexPromise;
    var file = lang === 'fr' ? 'site-search_fr.json' : 'site-search.json';
    indexPromise = fetch(root + 'assets/data/' + file).then(function (r) { return r.json(); })
      .then(function (d) { index = d; return d; });
    return indexPromise;
  }

  function iconSrc(entry) {
    if (entry.type === 'champion') return root + 'assets/champions/' + entry.slug + '.png';
    if (entry.type === 'item') return root + 'assets/items/' + entry.slug + '.png';
    return null;
  }

  function renderResults(q) {
    if (!q || !index) { resultsEl.innerHTML = ''; return; }
    var needle = q.toLowerCase();
    var matches = index.filter(function (e) { return e.name.toLowerCase().indexOf(needle) !== -1; }).slice(0, 12);
    resultsEl.innerHTML = '';
    if (!matches.length) {
      var empty = document.createElement('div');
      empty.className = 'site-search-empty';
      empty.textContent = EMPTY_TEXT;
      resultsEl.appendChild(empty);
      return;
    }
    matches.forEach(function (entry) {
      var a = document.createElement('a');
      a.className = 'site-search-result-item';
      a.href = root + entry.href;
      var icon = iconSrc(entry);
      a.innerHTML =
        (icon ? '<img class="site-search-result-icon" src="' + icon + '" alt="" loading="lazy">'
              : '<span class="site-search-result-icon"></span>') +
        '<span class="site-search-result-type">' + TYPE_LABELS[entry.type] + '</span>' +
        '<span class="site-search-result-name">' + entry.name + '</span>';
      resultsEl.appendChild(a);
    });
  }

  function openPanel() {
    panel.hidden = false;
    toggle.setAttribute('aria-expanded', 'true');
    loadIndex().then(function () { renderResults(input.value.trim()); });
    setTimeout(function () { input.focus(); }, 0);
  }
  function closePanel() {
    panel.hidden = true;
    toggle.setAttribute('aria-expanded', 'false');
    input.value = '';
    resultsEl.innerHTML = '';
  }

  toggle.addEventListener('click', function (e) {
    e.stopPropagation();
    if (panel.hidden) openPanel(); else closePanel();
  });
  input.addEventListener('input', function () { renderResults(input.value.trim()); });
  document.addEventListener('click', function (e) {
    if (!panel.hidden && !e.target.closest('.site-search-wrap')) closePanel();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !panel.hidden) closePanel();
  });
})();
"""
STAR_SVG = '<svg viewBox="0 0 24 24"><path d="M12 2.5l2.97 6.28 6.93.7-5.13 4.75 1.4 6.87L12 17.9l-6.17 3.2 1.4-6.87-5.13-4.75 6.93-.7z"/></svg>'
COPY_SVG = ('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" '
            'stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2"></rect>'
            '<path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>')

# Progressive enhancement, same pattern as TYPE_FILTER_JS -- every comp's
# planner_code is already baked into the button's data-code attribute at
# build time (no client-side lookup table needed, unlike the Artifact).
COPY_COMP_JS = """
(function () {
  var CHECK_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>';
  async function copyToClipboard(text) {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return;
    }
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
  }
  document.querySelectorAll('.copy-comp-btn').forEach(function (btn) {
    var originalHTML = btn.innerHTML;
    var originalTitle = btn.title;
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      copyToClipboard(btn.dataset.code).then(function () {
        btn.dataset.copied = 'true';
        btn.innerHTML = CHECK_SVG;
        btn.title = btn.dataset.copiedTitle;
        if (window.gtag) gtag('event', 'copy_comp_code');
      }, function () {
        btn.title = btn.dataset.failedTitle;
      });
      setTimeout(function () {
        btn.dataset.copied = 'false';
        btn.innerHTML = originalHTML;
        btn.title = originalTitle;
      }, 2200);
    });
  });
})();
"""

# Client-side-only "saved comps" -- no account system on this site, so
# favorites live in the visitor's own browser (localStorage) and nowhere
# else. Wires every server-rendered .fav-btn (comp rows + fiche header,
# see macros.html's favorite_button()) for add/remove + persisted state,
# and, when the current page is /favoris/ (detected by the #favoritesList
# container macros.html doesn't emit anywhere else), renders the saved
# list itself since that page carries no server-side data of its own.
FAVORITES_JS = """
(function () {
  var KEY = 'bm_favorites';
  var RECENT_KEY = 'bm_recently_viewed';
  var RECENT_MAX = 12;
  var STAR_SVG = '<svg viewBox="0 0 24 24"><path d="M12 2.5l2.97 6.28 6.93.7-5.13 4.75 1.4 6.87L12 17.9l-6.17 3.2 1.4-6.87-5.13-4.75 6.93-.7z"/></svg>';

  function load() {
    try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { return []; }
  }
  function save(list) {
    try { localStorage.setItem(KEY, JSON.stringify(list)); } catch (e) {}
  }
  function loadRecent() {
    try { return JSON.parse(localStorage.getItem(RECENT_KEY)) || []; } catch (e) { return []; }
  }
  function saveRecent(list) {
    try { localStorage.setItem(RECENT_KEY, JSON.stringify(list)); } catch (e) {}
  }
  function isSaved(list, key) {
    return list.some(function (f) { return f.key === key; });
  }
  function toggle(btn) {
    var list = load();
    var key = btn.dataset.favKey;
    var idx = list.findIndex(function (f) { return f.key === key; });
    if (idx === -1) {
      list.push({
        key: key, slug: btn.dataset.favSlug, label: btn.dataset.favLabel,
        tier: btn.dataset.favTier, carrySlug: btn.dataset.favCarrySlug || null,
      });
      if (window.gtag) gtag('event', 'favorite_add');
    } else {
      list.splice(idx, 1);
    }
    save(list);
    return idx === -1; // now saved
  }
  function applyState(btn, saved) {
    btn.setAttribute('aria-pressed', saved ? 'true' : 'false');
    var addTitle = btn.dataset.addTitle, removeTitle = btn.dataset.removeTitle;
    if (addTitle && removeTitle) btn.title = saved ? removeTitle : addTitle;
  }

  // Re-reads localStorage and re-applies every button's pressed state --
  // not just run once at load, because a plain "read once at script start"
  // goes stale the moment a visitor un-favorites a comp on /favoris/ then
  // hits the browser's Back button: bfcache restores the tier-list page's
  // DOM exactly as it was (including that comp's stale aria-pressed=true)
  // WITHOUT re-running this script, so the star never got a chance to
  // notice the localStorage change made on the other page.
  function syncButtonStates() {
    var favorites = load();
    document.querySelectorAll('.fav-btn[data-fav-key]').forEach(function (btn) {
      applyState(btn, isSaved(favorites, btn.dataset.favKey));
    });
  }
  syncButtonStates();
  // fires on the normal first load too (persisted: false, a harmless
  // no-op re-sync) and, critically, on a bfcache restore (persisted: true).
  window.addEventListener('pageshow', function (e) { if (e.persisted) syncButtonStates(); });

  // Passive "Vus récemment" tracking: every real /compo/<slug>/ visit
  // records itself (see comp.html's window.BM_CURRENT_COMP), no ★ click
  // needed. De-duped by moving an already-seen comp back to the front
  // instead of listing it twice; capped so the list stays a quick
  // "what was I just looking at", not an unbounded history dump.
  if (window.BM_CURRENT_COMP && window.BM_CURRENT_COMP.key) {
    var recent = loadRecent().filter(function (f) { return f.key !== window.BM_CURRENT_COMP.key; });
    recent.unshift(window.BM_CURRENT_COMP);
    saveRecent(recent.slice(0, RECENT_MAX));
  }

  document.querySelectorAll('.fav-btn[data-fav-key]').forEach(function (btn) {
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      var nowSaved = toggle(btn);
      applyState(btn, nowSaved);
      // A remove click on the favorites page itself should drop that row
      // immediately rather than wait for a reload.
      if (!nowSaved) {
        var row = btn.closest('.fav-row');
        if (row) { row.remove(); maybeShowEmptyState(); }
      }
    });
  });

  var list = document.getElementById('favoritesList');
  if (!list) return;

  var root = window.BM_ROOT || '';
  var emptyText = list.dataset.emptyText || '';
  var addTitle = list.dataset.addTitle || '';
  var removeTitle = list.dataset.removeTitle || '';

  function maybeShowEmptyState() {
    if (!list.querySelector('.fav-row')) {
      list.innerHTML = '<p class="favorites-empty">' + emptyText + '</p>';
    }
  }

  function renderRow(f) {
    var a = document.createElement('a');
    a.className = 'comp-row fav-row';
    a.setAttribute('data-tier', f.tier || '');
    a.href = root + 'compo/' + f.slug + '/';
    var carryImg = f.carrySlug
      ? '<img class="carry-portrait" src="' + root + 'assets/champions/' + f.carrySlug + '.png" alt="" loading="lazy">'
      : '';
    a.innerHTML =
      '<span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span>' +
      '<div class="tier-badge">' + (f.tier || '') + '</div>' +
      '<div class="row-body"><div class="row-top"><div class="row-name-block">' + carryImg +
      '<div class="row-name">' + f.label + '</div></div></div></div>' +
      '<button type="button" class="fav-btn" data-fav-key="' + f.key + '" data-add-title="' + addTitle + '" ' +
      'data-remove-title="' + removeTitle + '" title="' + removeTitle + '" aria-label="' + removeTitle + '" aria-pressed="true">' + STAR_SVG + '</button>';
    var removeBtn = a.querySelector('.fav-btn');
    removeBtn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      toggle(removeBtn);
      a.remove();
      maybeShowEmptyState();
    });
    list.appendChild(a);
  }

  var favorites = load();
  if (!favorites.length) {
    maybeShowEmptyState();
  } else {
    favorites.forEach(renderRow);
  }

  // "Vus récemment" -- same page, separate container, separate storage key.
  // Each row gets its own ★ (reusing toggle()/applyState() as-is) so a
  // comp you just glanced at can be favorited straight from here too,
  // without hunting it back down on a list page.
  var recentList = document.getElementById('recentlyViewedList');
  var clearBtn = document.getElementById('recentlyViewedClear');
  if (!recentList) return;

  var recentEmptyText = recentList.dataset.emptyText || '';

  function maybeShowRecentEmptyState() {
    if (!recentList.querySelector('.recent-row')) {
      recentList.innerHTML = '<p class="favorites-empty">' + recentEmptyText + '</p>';
      if (clearBtn) clearBtn.hidden = true;
    }
  }

  function renderRecentRow(f) {
    var a = document.createElement('a');
    a.className = 'comp-row recent-row';
    a.setAttribute('data-tier', f.tier || '');
    a.href = root + 'compo/' + f.slug + '/';
    var carryImg = f.carrySlug
      ? '<img class="carry-portrait" src="' + root + 'assets/champions/' + f.carrySlug + '.png" alt="" loading="lazy">'
      : '';
    var isFav = isSaved(load(), f.key);
    a.innerHTML =
      '<span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span>' +
      '<div class="tier-badge">' + (f.tier || '') + '</div>' +
      '<div class="row-body"><div class="row-top"><div class="row-name-block">' + carryImg +
      '<div class="row-name">' + f.label + '</div></div></div></div>' +
      '<button type="button" class="fav-btn" data-fav-key="' + f.key + '" data-fav-slug="' + f.slug + '" data-fav-label="' + f.label +
      '" data-fav-tier="' + (f.tier || '') + '" data-fav-carry-slug="' + (f.carrySlug || '') + '" data-add-title="' + addTitle +
      '" data-remove-title="' + removeTitle + '" title="' + (isFav ? removeTitle : addTitle) + '" aria-pressed="' + (isFav ? 'true' : 'false') + '">' + STAR_SVG + '</button>';
    var favBtn = a.querySelector('.fav-btn');
    favBtn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      applyState(favBtn, toggle(favBtn));
    });
    recentList.appendChild(a);
  }

  var recent = loadRecent();
  if (!recent.length) {
    maybeShowRecentEmptyState();
  } else {
    if (clearBtn) clearBtn.hidden = false;
    recent.forEach(renderRecentRow);
  }
  if (clearBtn) {
    clearBtn.addEventListener('click', function () {
      saveRecent([]);
      recentList.innerHTML = '';
      maybeShowRecentEmptyState();
    });
  }

  // League profiles favorited/recently searched -- separate localStorage
  // keys from the comp favorites above (see LEAGUE_JS), only ever rendered
  // here on /favoris/ (this script loads on every page, but these two
  // containers only exist on that one).
  var lolFavList = document.getElementById('leagueFavoritesList');
  var lolRecentList = document.getElementById('leagueRecentList');
  if (!lolFavList && !lolRecentList) return;

  function loadLol(key) {
    try { return JSON.parse(localStorage.getItem(key)) || []; } catch (e) { return []; }
  }
  function saveLol(key, list) {
    try { localStorage.setItem(key, JSON.stringify(list)); } catch (e) {}
  }
  function lolProfileHref(f) {
    return root + 'league/?riotId=' + encodeURIComponent(f.riotId) + '&region=' + encodeURIComponent(f.region);
  }
  function renderLolRow(container, f, isFav) {
    var a = document.createElement('a');
    a.className = 'comp-row fav-row';
    a.href = lolProfileHref(f);
    var parts = f.riotId.split('#');
    a.innerHTML =
      '<div class="duo-partner-row" style="padding:14px 16px;align-items:center">'
      + '<div class="duo-partner-info"><div class="duo-partner-name">' + parts[0] + (parts[1] ? ' <span class="tag">#' + parts[1] + '</span>' : '') + '</div>'
      + '<div class="duo-partner-meta">' + f.region + '</div></div>'
      + '<button type="button" class="fav-btn inline" data-fav-key="' + f.key + '" aria-pressed="true">' + STAR_SVG + '</button></div>';
    var btn = a.querySelector('.fav-btn');
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      var key = isFav ? LOL_FAV_KEY : LOL_RECENT_KEY;
      saveLol(key, loadLol(key).filter(function (x) { return x.key !== f.key; }));
      a.remove();
      maybeShowLolEmptyState();
    });
    (isFav ? lolFavList : lolRecentList).appendChild(a);
  }
  function maybeShowLolEmptyState() {
    if (lolFavList && !lolFavList.querySelector('.fav-row')) {
      lolFavList.innerHTML = '<p class="favorites-empty">' + (lolFavList.dataset.emptyText || '') + '</p>';
    }
    if (lolRecentList && !lolRecentList.querySelector('.fav-row')) {
      lolRecentList.innerHTML = '<p class="favorites-empty">' + (lolRecentList.dataset.emptyText || '') + '</p>';
      if (lolRecentClear) lolRecentClear.hidden = true;
    }
  }
  var LOL_FAV_KEY = 'bm_lol_favorites';
  var LOL_RECENT_KEY = 'bm_lol_recent';
  var lolRecentClear = document.getElementById('leagueRecentClear');
  var lolFavorites = loadLol(LOL_FAV_KEY);
  var lolRecent = loadLol(LOL_RECENT_KEY);
  if (lolFavList) lolFavorites.forEach(function (f) { renderLolRow(lolFavList, f, true); });
  if (lolRecentList) lolRecent.forEach(function (f) { renderLolRow(lolRecentList, f, false); });
  maybeShowLolEmptyState();
  if (lolRecentClear) {
    lolRecentClear.hidden = !lolRecent.length;
    lolRecentClear.addEventListener('click', function () {
      saveLol(LOL_RECENT_KEY, []);
      lolRecentList.innerHTML = '';
      maybeShowLolEmptyState();
    });
  }
})();
"""

# /discord/ page: subscribe/unsubscribe a visitor's own Discord webhook
# with discord-notify-worker (see that directory) -- both actions hit the
# same endpoint shape, just /subscribe vs /unsubscribe, picked by which
# button was clicked (the form has two submit buttons, not one).
DISCORD_NOTIFY_JS = """
(function () {
  var API = window.BM_DISCORD_API;
  var I = window.BM_I18N_DISCORD || {};
  var form = document.getElementById('discordForm');
  var input = document.getElementById('discordWebhookUrl');
  var statusEl = document.getElementById('discordStatus');
  if (!form || !API) return;

  function setStatus(text, isError) {
    if (!text) { statusEl.hidden = true; statusEl.textContent = ''; return; }
    statusEl.hidden = false;
    statusEl.textContent = text;
    statusEl.dataset.error = isError ? 'true' : 'false';
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var action = (e.submitter && e.submitter.dataset.action) || 'subscribe';
    var webhookUrl = input.value.trim();
    var buttons = form.querySelectorAll('button');
    buttons.forEach(function (b) { b.disabled = true; });
    setStatus('', false);

    fetch(API + '/' + action, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ webhookUrl: webhookUrl }),
    })
      .then(function (res) { return res.json().then(function (data) { return { ok: res.ok, data: data }; }); })
      .then(function (r) {
        if (r.ok) {
          setStatus(action === 'subscribe' ? I.successSubscribed : I.successUnsubscribed, false);
          if (window.gtag) gtag('event', 'discord_' + action);
          form.reset();
        } else {
          setStatus((r.data && r.data.error) || I.errorGeneric, true);
        }
      })
      .catch(function () { setStatus(I.errorGeneric, true); })
      .finally(function () { buttons.forEach(function (b) { b.disabled = false; }); });
  });
})();
"""

# Progressive enhancement, ported from the Artifact's wireChampionIcons():
# any ".champ-link-icon" (unit portraits, item-combo headers, board-variant
# icons, ...) shows a real stat tooltip on hover and jumps to that
# champion's page on click. Unlike the Artifact (one big embedded data
# object), stats are fetched once from assets/data/champions.json -- see
# main()'s champion_tooltip_data write-out -- and the click target is
# baked into each icon's own data-champ-href at build time, so this file
# needs no per-page templating. FR/EN labels are embedded directly here
# (not routed through the Jinja `t()` system) since this one static file
# is shared, unchanged, across every language's pages.
#
# Event DELEGATION on `document` (not per-icon listeners) on purpose: every
# other page's icons exist at load time, but MetaScope (see metascope.js)
# renders its whole profile/analysis view from a live API response AFTER
# this script has already run -- delegation means those icons get the same
# hover/click behavior for free, no re-init call needed from that script.
CHAMP_ICON_JS = """
(function () {
  var LABELS = {
    fr: {playrate: 'Popularité', avgplacement: 'Placement moyen', avgstar: 'Étoile moyenne',
         items: function (s) { return 'Objets fréquents : ' + s; }},
    en: {playrate: 'Play rate', avgplacement: 'Avg placement', avgstar: 'Avg star',
         items: function (s) { return 'Common items: ' + s; }}
  };
  var L = LABELS[document.documentElement.lang === 'en' ? 'en' : 'fr'];
  var tooltip = document.getElementById('tooltip');
  var champData = null;
  var champFile = document.documentElement.lang === 'fr' ? 'champions_fr.json' : 'champions.json';
  fetch((window.BM_ROOT || '') + 'assets/data/' + champFile).then(function (r) { return r.json(); }).then(function (d) { champData = d; }).catch(function () {});

  function showTooltip(icon, e) {
    if (!champData || !tooltip) return;
    var d = champData[icon.dataset.champSlug];
    if (!d) return;
    var traitsHtml = (d.traits || []).map(function (t) {
      return '<span class="tt-trait-chip"><img src="' + (window.BM_ROOT || '') + 'assets/traits/' + t.slug + '.png" alt="">' + t.name + '</span>';
    }).join('');
    tooltip.innerHTML = '<div class="tt-name">' + d.name + '</div>'
      + (traitsHtml ? '<div class="tt-traits">' + traitsHtml + '</div>' : '')
      + '<div class="tt-row"><span>' + L.playrate + '</span><b class="nums">' + d.pick_rate_pct + '</b></div>'
      + '<div class="tt-row"><span>' + L.avgplacement + '</span><b class="nums">' + d.avg_placement.toFixed(2) + '</b></div>'
      + '<div class="tt-row"><span>' + L.avgstar + '</span><b class="nums">' + d.avg_star_level.toFixed(1) + '\\u2605</b></div>'
      + (d.top_items && d.top_items.length ? '<div class="tt-items">' + L.items(d.top_items.join(', ')) + '</div>' : '');
    tooltip.dataset.visible = 'true';
    moveTooltip(e);
  }
  function moveTooltip(e) {
    if (!tooltip) return;
    var pad = 14, x = e.clientX + pad, y = e.clientY + pad;
    if (x + 190 > window.innerWidth) x = e.clientX - 190 - pad;
    if (y + 130 > window.innerHeight) y = e.clientY - 130 - pad;
    tooltip.style.left = x + 'px';
    tooltip.style.top = y + 'px';
  }
  function hideTooltip() { if (tooltip) tooltip.dataset.visible = 'false'; }

  document.addEventListener('mouseover', function (e) {
    var icon = e.target.closest('.champ-link-icon');
    if (icon) showTooltip(icon, e);
  });
  document.addEventListener('mousemove', function (e) {
    if (e.target.closest('.champ-link-icon')) moveTooltip(e);
  });
  document.addEventListener('mouseout', function (e) {
    if (e.target.closest('.champ-link-icon')) hideTooltip();
  });
  document.addEventListener('click', function (e) {
    var icon = e.target.closest('.champ-link-icon');
    if (!icon) return;
    e.preventDefault();
    e.stopPropagation();
    var href = icon.dataset.champHref;
    if (href) location.href = href;
  });
})();
"""

# Same tooltip mechanism as CHAMP_ICON_JS above (shared #tooltip div, one
# lazy-fetched static JSON), for the Glossary's item icon grid: hovering an
# item shows its real crafting components (the ".item-icon"/".item-icon-sm"
# used everywhere else on the site already have a native `title` tooltip for
# this, deliberately not reused here so this one richer version -- icons,
# not just names -- doesn't fight the plain-text one on the exact same class).
GLOSSARY_ITEM_JS = """
(function () {
  var tooltip = document.getElementById('tooltip');
  var itemData = null;
  var itemFile = document.documentElement.lang === 'fr' ? 'glossary-items_fr.json' : 'glossary-items.json';
  fetch((window.BM_ROOT || '') + 'assets/data/' + itemFile).then(function (r) { return r.json(); }).then(function (d) { itemData = d; }).catch(function () {});

  function showTooltip(icon, e) {
    if (!itemData || !tooltip) return;
    var d = itemData[icon.dataset.itemSlug];
    if (!d) return;
    var compHtml = (d.composition || []).map(function (c) {
      return '<span class="tt-trait-chip"><img src="' + (window.BM_ROOT || '') + 'assets/items/' + c.slug + '.png" alt="">' + c.name + '</span>';
    }).join('');
    tooltip.innerHTML = '<div class="tt-name">' + d.name + '</div>'
      + (compHtml ? '<div class="tt-traits">' + compHtml + '</div>' : '');
    tooltip.dataset.visible = 'true';
    moveTooltip(e);
  }
  function moveTooltip(e) {
    if (!tooltip) return;
    var pad = 14, x = e.clientX + pad, y = e.clientY + pad;
    if (x + 190 > window.innerWidth) x = e.clientX - 190 - pad;
    if (y + 130 > window.innerHeight) y = e.clientY - 130 - pad;
    tooltip.style.left = x + 'px';
    tooltip.style.top = y + 'px';
  }
  function hideTooltip() { if (tooltip) tooltip.dataset.visible = 'false'; }

  document.addEventListener('mouseover', function (e) {
    var icon = e.target.closest('.item-tt-icon');
    if (icon) showTooltip(icon, e);
  });
  document.addEventListener('mousemove', function (e) {
    if (e.target.closest('.item-tt-icon')) moveTooltip(e);
  });
  document.addEventListener('mouseout', function (e) {
    if (e.target.closest('.item-tt-icon')) hideTooltip();
  });
})();
"""

# Gameplan tabs on a comp fiche (see build_comp_vm's "gameplan" field, itself
# precomputed offline by compute_gameplans.py) -- delegated on document like
# CHAMP_ICON_JS above, one static block per page, no re-init needed. Panels
# default to only the first one visible (server-rendered, see comp.html) so
# there's a sane no-JS fallback: the tabs just don't switch, first step
# still reads fine on its own.
GAMEPLAN_TABS_JS = """
(function () {
  document.addEventListener('click', function (e) {
    var btn = e.target.closest('.gameplan-tab-btn');
    if (!btn) return;
    var block = btn.closest('.gameplan-block');
    if (!block) return;
    var idx = btn.dataset.gameplanTab;
    block.querySelectorAll('.gameplan-tab-btn').forEach(function (b) {
      var active = b.dataset.gameplanTab === idx;
      b.dataset.active = String(active);
      b.setAttribute('aria-selected', String(active));
    });
    block.querySelectorAll('.gameplan-tab-panel').forEach(function (p) {
      p.hidden = p.dataset.gameplanPanel !== idx;
    });
  });
})();
"""

# The one page on the whole site that renders itself: a Riot ID typed by any
# visitor can't be pre-built at deploy time, so this fetches from
# metascope-worker (see metascope-worker/, a separate Cloudflare Worker --
# the only live backend BrokenMeta.gg has) and builds the same markup/CSS
# classes the static player.html/game_analysis.html templates already use,
# by hand, in JS. Two "screens" (profile, then one game's analysis) toggled
# in place, with the URL kept in sync via history.pushState so a result is
# still linkable/shareable and survives a refresh or the back button.
METASCOPE_JS = """
(function () {
  var API = window.BM_METASCOPE_API;
  var ROOT = window.BM_ROOT || '';
  var I = window.BM_I18N_MS || {};
  var form = document.getElementById('metascopeForm');
  var riotIdInput = document.getElementById('metascopeRiotId');
  var regionSelect = document.getElementById('metascopeRegion');
  var statusEl = document.getElementById('metascopeStatus');
  var results = document.getElementById('metascopeResults');
  if (!form || !API) return;

  var currentProfile = null; // cached so "back" from an analysis doesn't refetch

  function el(tag, className, html) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (html !== undefined) e.innerHTML = html;
    return e;
  }
  function champIcon(slug, alt, cls, style) {
    if (!slug) return '';
    return '<img class="champ-link-icon' + (cls ? ' ' + cls : '') + '" src="' + ROOT + 'assets/champions/' + slug + '.png" alt="' + alt + '" loading="lazy"'
      + (style ? ' style="' + style + '"' : '') + ' data-champ-slug="' + slug + '" data-champ-href="' + ROOT + 'champions/' + slug + '/">';
  }
  function pill(label, value) {
    return '<div class="pill"><div class="p-label">' + label + '</div><div class="p-value nums">' + value + '</div></div>';
  }
  function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }
  function initials(riotId) { var name = (riotId || '').split('#')[0].trim(); return (name.slice(0, 2) || '?').toUpperCase(); }

  function setStatus(text, isError) {
    if (!text) { statusEl.hidden = true; statusEl.textContent = ''; return; }
    statusEl.hidden = false;
    statusEl.textContent = text;
    statusEl.dataset.error = isError ? 'true' : 'false';
  }

  function setUrl(params) {
    var qs = new URLSearchParams(params).toString();
    var url = location.pathname + (qs ? '?' + qs : '');
    history.pushState(params, '', url);
  }

  async function fetchJson(url) {
    var res = await fetch(url);
    var data = await res.json().catch(function () { return {}; });
    if (!res.ok) throw new Error(data.error || ('HTTP ' + res.status));
    return data;
  }

  function renderProfile(data) {
    currentProfile = data;
    var total = (data.wins || 0) + (data.losses || 0);
    var wr = total ? Math.round((data.wins / total) * 100) + '%' : null;

    var header = el('div', 'player-header',
      '<div class="player-avatar">' + esc(initials(data.riotId)) + '</div>'
      + '<div><div class="player-name-row"><span class="player-name">' + esc(data.riotId) + '</span>'
      + (data.tier ? '<span class="lb-tier-tag" data-tier="' + data.tier + '">' + data.tier + '</span>' : '')
      + (data.hotStreak ? '<span class="lb-hot" title="' + esc(I.hotStreakTitle) + '">\\ud83d\\udd25</span>' : '')
      + '</div><div class="player-meta">' + esc(data.region) + '</div></div>'
      + '<div class="player-stats pill-row">'
      + pill('LP', data.leaguePoints != null ? data.leaguePoints : '—')
      + pill(I.recordLabel, total ? (data.wins + 'W / ' + data.losses + 'L') : '—')
      + pill(I.winrateLabel, wr || I.winrateUnavailable)
      + '</div>');

    var statsBox = el('div', 'metascope-box',
      '<div class="metascope-box-title">' + esc(I.statsTitle) + '</div>'
      + '<div class="metascope-stat-row"><span>LP</span><b class="nums">' + (data.leaguePoints != null ? data.leaguePoints : '—') + '</b></div>'
      + (data.avgPlacement != null ? '<div class="metascope-stat-row"><span>' + esc(I.placementLabel) + '</span><b class="nums">' + data.avgPlacement.toFixed(2) + '</b></div>' : ''));

    var habitsInner = '<div class="metascope-box-title">' + esc(I.habitsTitle) + '</div>';
    if (data.isRerollLover) habitsInner += '<div class="metascope-habit-badge">\\ud83c\\udfb2 ' + esc(I.rerollLover) + '</div>';
    if (data.topPlayed && data.topPlayed.length) {
      habitsInner += '<div class="metascope-top-played-label">' + esc(I.topPlayed) + '</div>';
      data.topPlayed.forEach(function (tp) {
        habitsInner += '<div class="metascope-top-played-row">' + champIcon(tp.carrySlug, tp.label)
          + (tp.compSlug ? '<a class="metascope-top-played-name" href="' + ROOT + 'compo/' + tp.compSlug + '/">' + esc(tp.label) + '</a>'
                          : '<span class="metascope-top-played-name">' + esc(tp.label) + '</span>')
          + '<span class="metascope-top-played-count nums">\\u00d7' + tp.count + '</span></div>';
      });
    } else if (!data.isRerollLover) {
      habitsInner += '<div class="matchup-empty">' + esc(I.noHabits) + '</div>';
    }
    var habitsBox = el('div', 'metascope-box', habitsInner);

    var sidebar = el('div', 'metascope-sidebar');
    sidebar.appendChild(statsBox);
    sidebar.appendChild(habitsBox);

    var gamesHtml = '';
    (data.recentGames || []).forEach(function (g) {
      gamesHtml += '<div class="profile-comp-row" style="cursor:default">'
        + '<span class="lb-square ' + (g.placement <= 4 ? 'win' : 'loss') + '">' + g.placement + '</span>'
        + champIcon(g.carrySlug, g.carry, null, 'width:26px;height:26px;object-fit:cover;border:1px solid var(--border-bright)')
        + (g.compSlug ? '<a class="profile-comp-name" href="' + ROOT + 'compo/' + g.compSlug + '/">' + esc(g.compLabel) + '</a>'
                       : '<span class="profile-comp-name">' + esc(g.compLabel) + '</span>')
        + '<a class="metascope-analyze-link" href="javascript:;" data-match-id="' + g.matchId + '">' + esc(I.analyzeButton) + ' \\u2192</a>'
        + '</div>';
    });
    var main = el('div', 'metascope-main',
      '<h2 class="fiche-section-title" style="margin-top:0">' + esc(I.last10GamesTitle) + '</h2>'
      + (data.recentGames && data.recentGames.length ? '<p class="metascope-hint">' + esc(I.analyzeHint) + '</p>' : '')
      + '<div class="profile-comp-list">' + (gamesHtml || '<div class="matchup-empty">' + esc(I.noRecentGames) + '</div>') + '</div>');

    var layout = el('div', 'metascope-layout');
    layout.appendChild(sidebar);
    layout.appendChild(main);

    results.innerHTML = '';
    results.appendChild(header);
    results.appendChild(layout);

    main.querySelectorAll('[data-match-id]').forEach(function (btn) {
      btn.addEventListener('click', function () { runAnalyze(btn.dataset.matchId); });
    });
  }

  function renderAnalysis(data) {
    var insightsHtml = (data.insights || []).map(function (ins) {
      var icon = ins.type === 'good' ? '\\u2713' : ins.type === 'warning' ? '\\u26a0' : '\\u2139';
      return '<div class="metascope-insight-row" data-type="' + ins.type + '">'
        + '<span class="metascope-insight-icon">' + icon + '</span>'
        + '<div><span class="metascope-insight-category">' + esc(ins.category) + '</span>'
        + '<span class="metascope-insight-text">' + esc(ins.text) + '</span></div></div>';
    }).join('');

    var unitsHtml = (data.units || []).map(function (u) {
      var itemsHtml = (u.items || []).map(function (it) {
        return '<img class="item-icon" src="' + ROOT + 'assets/items/' + it.slug + '.png" alt="' + esc(it.name) + '" title="' + esc(it.name) + '" loading="lazy">';
      }).join('');
      var stars = u.star >= 3 ? '\\u2605\\u2605\\u2605' : u.star === 2 ? '\\u2605\\u2605' : '';
      return '<div class="unit-cell"><div class="unit-icon-wrap">'
        + champIcon(u.slug, u.champion, 'unit-icon', 'border-color:var(--cost-' + (u.cost || 1) + ')')
        + (stars ? '<span class="star-row">' + stars + '</span>' : '')
        + '</div><div class="unit-items">' + itemsHtml + '</div></div>';
    }).join('');

    var lobbyHtml = '<div class="profile-comp-row" style="cursor:default;background:transparent;border-color:transparent">'
      + '<span class="lb-square" style="background:transparent;border:none;color:var(--text-faint)">\\u2014</span>'
      + champIcon(data.carrySlug, data.carry, null, 'width:26px;height:26px;object-fit:cover;border:1px solid var(--cyan)')
      + '<span class="profile-comp-name"><b>' + esc(currentProfile ? currentProfile.riotId : '') + '</b> \\u2014 ' + esc(data.compLabel) + '</span>'
      + '<span class="lb-square ' + (data.placement <= 4 ? 'win' : 'loss') + '">' + data.placement + '</span></div>';
    (data.lobby || []).forEach(function (l) {
      lobbyHtml += '<div class="profile-comp-row" style="cursor:default" data-counter="' + (l.isCounter ? 'true' : 'false') + '">'
        + '<span class="lb-square ' + (l.placement <= 4 ? 'win' : 'loss') + '">' + l.placement + '</span>'
        + champIcon(l.carrySlug, l.carry, null, 'width:26px;height:26px;object-fit:cover;border:1px solid var(--border-bright)')
        + (l.compSlug ? '<a class="profile-comp-name" href="' + ROOT + 'compo/' + l.compSlug + '/">' + esc(l.riotId) + ' \\u2014 ' + esc(l.compLabel) + '</a>'
                       : '<span class="profile-comp-name">' + esc(l.riotId) + ' \\u2014 ' + esc(l.compLabel) + '</span>')
        + (l.isCounter ? '<span class="metascope-counter-tag">' + esc(I.counterTag) + '</span>' : '')
        + '</div>';
    });

    var container = el('div', '',
      '<a class="back-link" href="javascript:;" id="msBackLink">' + esc(I.backButton) + '</a>'
      + '<div class="fiche-header">' + champIcon(data.carrySlug, data.carry, 'champ-fiche-icon')
      + '<div><h1 class="fiche-title">' + (data.compSlug ? '<a href="' + ROOT + 'compo/' + data.compSlug + '/" style="color:inherit">' + esc(data.compLabel) + '</a>' : esc(data.compLabel)) + '</h1></div>'
      + '<div class="fiche-stats pill-row">' + pill(I.placementLabel, data.placement)
      + (data.level ? pill(I.levelLabel, data.level) : '') + (data.goldLeft != null ? pill(I.goldLeftLabel, data.goldLeft) : '') + '</div></div>'
      + (unitsHtml ? '<h2 class="fiche-section-title">' + esc(I.yourBoardTitle) + '</h2><div class="fiche-board-wrap"><div class="fiche-board">' + unitsHtml + '</div></div>' : '')
      + '<h2 class="fiche-section-title">' + esc(I.insightsTitle) + '</h2>'
      + (I.lang === 'en' ? '<div class="metascope-lang-note">' + esc(I.insightsFrOnly) + '</div>' : '')
      + (insightsHtml ? '<div class="metascope-insight-list">' + insightsHtml + '</div>' : '<div class="matchup-empty">' + esc(I.noInsights) + '</div>')
      + '<h2 class="fiche-section-title">' + esc(I.lobbyTitle) + '</h2>'
      + (data.lobby && data.lobby.length ? '<div class="profile-comp-list">' + lobbyHtml + '</div>' : '<div class="matchup-empty">' + esc(I.noLobby) + '</div>'));

    results.innerHTML = '';
    results.appendChild(container);
    document.getElementById('msBackLink').addEventListener('click', function () {
      setUrl({ riotId: currentProfile.riotId, region: currentProfile.region });
      if (currentProfile) renderProfile(currentProfile);
    });
    window.scrollTo(0, 0);
  }

  function skeletonProfileHtml() {
    var rows = '';
    for (var i = 0; i < 6; i++) {
      rows += '<div class="skel-row"><span class="skel" style="width:30px;height:30px"></span><span class="skel" style="flex:1;height:12px"></span><span class="skel" style="width:70px;height:12px"></span></div>';
    }
    return '<div class="skel-stack" aria-hidden="true"><span class="skel" style="width:260px;max-width:100%;height:40px"></span>' + rows + '</div>';
  }

  async function runProfile(riotId, region) {
    setStatus(I.loading, false);
    results.innerHTML = skeletonProfileHtml();
    try {
      var data = await fetchJson(API + '/profile?riotId=' + encodeURIComponent(riotId) + '&region=' + encodeURIComponent(region));
      setStatus(null);
      results.innerHTML = '';
      setUrl({ riotId: riotId, region: region });
      renderProfile(data);
      if (window.gtag) gtag('event', 'metascope_lookup', {region: region, success: true});
    } catch (e) {
      results.innerHTML = '';
      setStatus(e.message || String(e), true);
      if (window.gtag) gtag('event', 'metascope_lookup', {region: region, success: false});
    }
  }

  async function runAnalyze(matchId) {
    if (!currentProfile) return;
    setStatus(I.loading, false);
    try {
      var data = await fetchJson(API + '/analyze?region=' + encodeURIComponent(currentProfile.region) + '&matchId=' + encodeURIComponent(matchId) + '&puuid=' + encodeURIComponent(currentProfile.puuid));
      setStatus(null);
      setUrl({ riotId: currentProfile.riotId, region: currentProfile.region, match: matchId });
      renderAnalysis(data);
    } catch (e) {
      setStatus(e.message || String(e), true);
    }
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var riotId = riotIdInput.value.trim();
    var region = regionSelect.value;
    if (riotId) runProfile(riotId, region);
  });

  window.addEventListener('popstate', function (e) {
    var p = new URLSearchParams(location.search);
    var riotId = p.get('riotId');
    if (!riotId) { results.innerHTML = ''; setStatus(null); return; }
    riotIdInput.value = riotId;
    regionSelect.value = p.get('region') || 'EUW';
    runProfile(riotId, regionSelect.value).then(function () {
      var matchId = p.get('match');
      if (matchId) runAnalyze(matchId);
    });
  });

  // Auto-run on load if the URL already carries a lookup (shared link, or a
  // refresh/back-navigation onto a result).
  var initial = new URLSearchParams(location.search);
  var initialRiotId = initial.get('riotId');
  if (initialRiotId) {
    riotIdInput.value = initialRiotId;
    regionSelect.value = initial.get('region') || 'EUW';
    runProfile(initialRiotId, regionSelect.value).then(function () {
      var matchId = initial.get('match');
      if (matchId) runAnalyze(matchId);
    });
  }
})();
"""


# League of Legends profile lookup -- same real-backend pattern as
# METASCOPE_JS above (fetch a Worker, render real data, nothing client-side
# is invented), pointed at lol-worker instead of metascope-worker. Only the
# in-game comms panel stays illustrative on purpose: Riot doesn't expose
# per-game pings/chat at all, at any endpoint. LP progress is real -- see
# recordLpSnapshot in lol-worker/src/index.ts: since Match-V5 only ever
# gives the CURRENT LP, not a history, every real lookup appends one real
# point to that player's own history in KV instead.
LEAGUE_JS = """
(function () {
  // Straight port of the BrokenMeta League concept Artifact's rendering
  // (same HTML structure/CSS classes as league_profile's <style>, see
  // build_site.py), but every function here reads from the REAL worker
  // payload instead of a seeded mock generator -- no MATCH_HISTORY, no
  // fabricated duo data. Only the comms section stays illustrative (see
  // devSectionsHtml): Riot's API exposes no ping/chat data at any endpoint.
  var API = window.BM_LEAGUE_API;
  var I = window.BM_I18N_LEAGUE || {};
  var form = document.getElementById('leagueForm');
  var riotIdInput = document.getElementById('leagueRiotId');
  var regionSelect = document.getElementById('leagueRegion');
  var statusEl = document.getElementById('leagueStatus');
  var results = document.getElementById('leagueResults');
  if (!form || !API) return;

  // Favorited League profiles + recently searched ones -- same localStorage
  // pattern as FAVORITES_JS (TFT comps), separate keys so the two never mix,
  // rendered back out on /favoris/ by FAVORITES_JS itself.
  var LOL_FAV_KEY = 'bm_lol_favorites';
  var LOL_RECENT_KEY = 'bm_lol_recent';
  var LOL_RECENT_MAX = 8;
  var STAR_SVG = '<svg viewBox="0 0 24 24"><path d="M12 2.5l2.97 6.28 6.93.7-5.13 4.75 1.4 6.87L12 17.9l-6.17 3.2 1.4-6.87-5.13-4.75 6.93-.7z"/></svg>';

  function lolFavKey(riotId, region) { return region + '|' + riotId; }
  function loadLolFavorites() {
    try { return JSON.parse(localStorage.getItem(LOL_FAV_KEY)) || []; } catch (e) { return []; }
  }
  function saveLolFavorites(list) {
    try { localStorage.setItem(LOL_FAV_KEY, JSON.stringify(list)); } catch (e) {}
  }
  function isLolFavorite(riotId, region) {
    return loadLolFavorites().some(function (f) { return f.key === lolFavKey(riotId, region); });
  }
  function toggleLolFavorite(riotId, region) {
    var list = loadLolFavorites();
    var key = lolFavKey(riotId, region);
    var idx = list.findIndex(function (f) { return f.key === key; });
    if (idx === -1) {
      list.unshift({ key: key, riotId: riotId, region: region });
      if (window.gtag) gtag('event', 'favorite_add', { kind: 'league_profile' });
    } else {
      list.splice(idx, 1);
    }
    saveLolFavorites(list);
    return idx === -1; // now saved
  }
  function recordLolRecentSearch(riotId, region) {
    try {
      var key = lolFavKey(riotId, region);
      var list = JSON.parse(localStorage.getItem(LOL_RECENT_KEY)) || [];
      list = list.filter(function (f) { return f.key !== key; });
      list.unshift({ key: key, riotId: riotId, region: region });
      localStorage.setItem(LOL_RECENT_KEY, JSON.stringify(list.slice(0, LOL_RECENT_MAX)));
    } catch (e) {}
  }

  var ROLE_ICON = {
    top: '<path opacity="0.5" fill="#785a28" fill-rule="evenodd" d="M21,14H14v7h7V14Zm5-3V26L11.014,26l-4,4H30V7.016Z"/><polygon fill="#c8aa6e" points="4 4 4.003 28.045 9 23 9 9 23 9 28.045 4.003 4 4"/>',
    jungle: '<path fill="#c8aa6e" fill-rule="evenodd" d="M25,3c-2.128,3.3-5.147,6.851-6.966,11.469A42.373,42.373,0,0,1,20,20a27.7,27.7,0,0,1,1-3C21,12.023,22.856,8.277,25,3ZM13,20c-1.488-4.487-4.76-6.966-9-9,3.868,3.136,4.422,7.52,5,12l3.743,3.312C14.215,27.917,16.527,30.451,17,31c4.555-9.445-3.366-20.8-8-28C11.67,9.573,13.717,13.342,13,20Zm8,5a15.271,15.271,0,0,1,0,2l4-4c0.578-4.48,1.132-8.864,5-12C24.712,13.537,22.134,18.854,21,25Z"/>',
    mid: '<path opacity="0.5" fill="#785a28" fill-rule="evenodd" d="M30,12.968l-4.008,4L26,26H17l-4,4H30ZM16.979,8L21,4H4V20.977L8,17,8,8h8.981Z"/><polygon fill="#c8aa6e" points="25 4 4 25 4 30 9 30 30 9 30 4 25 4"/>',
    adc: '<path opacity="0.5" fill="#785a28" fill-rule="evenodd" d="M13,20h7V13H13v7ZM4,4V26.984l3.955-4L8,8,22.986,8l4-4H4Z"/><polygon fill="#c8aa6e" points="29.997 5.955 25 11 25 25 11 25 5.955 29.997 30 30 29.997 5.955"/>',
    support: '<path fill="#c8aa6e" fill-rule="evenodd" d="M26,13c3.535,0,8-4,8-4H23l-3,3,2,7,5-2-3-4h2ZM22,5L20.827,3H13.062L12,5l5,6Zm-5,9-1-1L13,28l4,3,4-3L18,13ZM11,9H0s4.465,4,8,4h2L7,17l5,2,2-7Z"/>',
  };
  var ROLE_LABEL = { top: 'Top', jungle: 'Jungle', mid: 'Mid', adc: 'ADC', support: 'Support' };
  var QUEUE_LABEL = { solo: I.queueSolo, flex: I.queueFlex, aram: I.queueAram };
  // Toutes les files existantes ne sont pas listées (URF, Nexus Blitz,
  // événements temporaires...) -- fallback générique plutôt que de
  // deviner un libellé pour une file absente de cette table.
  var QUEUE_ID_LABEL = { 400: I.queueNormalDraft, 420: I.queueSolo, 430: I.queueNormalBlind, 440: I.queueFlex, 450: I.queueAram, 700: I.queueClash };
  function liveGameQueueLabel(id) { return QUEUE_ID_LABEL[id] || I.queueCustom; }

  // Bandeau "en partie" -- Spectator-V5, vérifié à chaque recherche de
  // profil (voir index.ts). Même style de ligne que le scoreboard d'une
  // partie terminée (.scoreboard-row/-team) : équipe du joueur cherché
  // d'abord, classée "ally" même si Riot lui a attribué teamId 200 cette
  // partie-ci (le bleu/rouge alterne, ce qui compte c'est "son équipe").
  function buildLiveGameHtml(lg) {
    var selfP = lg.participants.filter(function (p) { return p.isSelf; })[0];
    var selfTeam = selfP ? selfP.teamId : 100;
    var otherP = lg.participants.filter(function (p) { return p.teamId !== selfTeam; })[0];
    var enemyTeam = otherP ? otherP.teamId : (selfTeam === 100 ? 200 : 100);
    var mins = Math.floor(lg.gameLengthSeconds / 60), secs = lg.gameLengthSeconds % 60;
    function teamRows(list) {
      return list.map(function (p) {
        var spellsHtml = p.spells.map(function (s) {
          return s.iconUrl ? '<img class="spell-icon league-icon-fallback" style="width:18px;height:18px" src="' + s.iconUrl + '" alt="" title="' + esc(s.name) + '" loading="lazy">' : '';
        }).join('');
        var runeHtml = p.runes.keystoneIconUrl ? '<img class="rune-icon small league-icon-fallback" src="' + p.runes.keystoneIconUrl + '" alt="" title="' + esc(p.runes.keystoneName) + '" loading="lazy">' : '';
        return '<div class="scoreboard-row' + (p.isSelf ? ' is-self' : '') + '">'
          + '<span class="champ-portrait">' + (p.championName ? champPortraitInner(p.championName) : '?') + '</span>'
          + '<span class="scoreboard-name">' + (p.isSelf ? esc(p.riotId || '') + ' ' + I.you : esc(p.riotId || '?')) + (p.bot ? ' <span class="profile-section-note">' + I.bot + '</span>' : '') + '</span>'
          + '<span class="scoreboard-items" style="gap:2px">' + spellsHtml + runeHtml + '</span>'
          + '</div>';
      }).join('');
    }
    function bansHtml(teamId) {
      var bans = (lg.bannedChampions || []).filter(function (b) { return b.teamId === teamId && b.championName; });
      if (!bans.length) return '<span class="live-game-bans-empty">' + I.noBans + '</span>';
      return bans.map(function (b) {
        return '<span class="champ-portrait live-game-ban"><span class="champ-portrait">' + champPortraitInner(b.championName) + '</span></span>';
      }).join('');
    }
    var hasBans = (lg.bannedChampions || []).some(function (b) { return b.championName; });
    return '<div class="live-game-header"><span class="live-dot"></span>' + esc(I.liveGameLabel) + ' — ' + esc(liveGameQueueLabel(lg.gameQueueConfigId)) + ' — ' + mins + ':' + (secs < 10 ? '0' : '') + secs + '</div>'
      + '<div class="scoreboard-grid">'
      + '<div class="scoreboard-team ally">' + teamRows(lg.participants.filter(function (p) { return p.teamId === selfTeam; })) + '</div>'
      + '<div class="scoreboard-team enemy">' + teamRows(lg.participants.filter(function (p) { return p.teamId !== selfTeam; })) + '</div>'
      + '</div>'
      + (hasBans ? '<div class="live-game-bans"><span class="live-game-bans-label">' + esc(I.bannedChampionsTitle) + '</span>'
        + '<div class="live-game-bans-row">' + bansHtml(selfTeam) + '</div>'
        + '<div class="live-game-bans-row">' + bansHtml(enemyTeam) + '</div>'
        + '</div>' : '');
  }

  function roleIcon(role, cls) { return '<svg class="' + (cls || 'champ-role-icon') + '" viewBox="0 0 34 34" xmlns="http://www.w3.org/2000/svg">' + (ROLE_ICON[role] || '') + '</svg>'; }
  function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }
  function initials(name) { return (name || '?').replace(/[^A-Za-z]/g, '').slice(0, 2).toUpperCase() || '?'; }
  function tierLabel(tier) { return tier ? tier.charAt(0) + tier.slice(1).toLowerCase() : ''; }

  // Real LP-over-time chart (see recordLpSnapshot in lol-worker/src/index.ts)
  // -- each point is a REAL rank recorded on a real lookup, no fabricated
  // history. A promotion resets the raw leaguePoints counter back near 0
  // even though it's a real gain, so points are scored on a continuous
  // tier+division ladder (100 "LP" per division, matching the real
  // promotion threshold) instead of plotting raw leaguePoints, which would
  // otherwise draw a promotion as a misleading drop.
  var LP_TIER_ORDER = ['IRON', 'BRONZE', 'SILVER', 'GOLD', 'PLATINUM', 'EMERALD', 'DIAMOND', 'MASTER', 'GRANDMASTER', 'CHALLENGER'];
  var LP_DIV_ORDER = { IV: 0, III: 1, II: 2, I: 3 };
  function lpScore(p) {
    var tierIdx = LP_TIER_ORDER.indexOf((p.tier || '').toUpperCase());
    if (tierIdx < 0) tierIdx = 0;
    return tierIdx * 400 + (LP_DIV_ORDER[p.rank] || 0) * 100 + (p.leaguePoints || 0);
  }
  // Serialises a Bklit chart payload (see charts-ui/src/embed.tsx) into an
  // HTML attribute value; the markup around it stays as the fallback.
  function bmAttr(payload) { return JSON.stringify(payload).replace(/&/g, '&amp;').replace(/"/g, '&quot;'); }
  function buildRealLpChartSvg(points) {
    var w = 740, h = 170, padX = 10, padTop = 14, padBottom = 14;
    var scores = points.map(lpScore);
    var min = Math.min.apply(null, scores), max = Math.max.apply(null, scores);
    var range = (max - min) || 1;
    var n = points.length;
    var coords = scores.map(function (s, i) {
      var x = padX + (n === 1 ? 0 : (i / (n - 1)) * (w - 2 * padX));
      var y = h - padBottom - ((s - min) / range) * (h - padTop - padBottom);
      return [x, y];
    });
    var lineStr = coords.map(function (c) { return c[0].toFixed(1) + ',' + c[1].toFixed(1); }).join(' ');
    var last = coords[coords.length - 1];
    var svg = '<svg viewBox="0 0 740 170" class="lp-chart-svg"><line x1="8" y1="' + (h - padBottom) + '" x2="732" y2="' + (h - padBottom) + '" class="lp-chart-zero"/>'
      + '<polygon points="' + lineStr + ' ' + last[0].toFixed(1) + ',156 ' + coords[0][0].toFixed(1) + ',156" class="lp-chart-area"/>'
      + '<polyline points="' + lineStr + '" class="lp-chart-line" pathLength="1"/><circle cx="' + last[0].toFixed(1) + '" cy="' + last[1].toFixed(1) + '" r="4.5" class="lp-chart-dot"/></svg>';
    // Bklit AreaChart island (assets/js/bm-charts.js, loaded on demand below)
    // replaces this SVG once ready; the SVG stays as the no-JS / load-failure fallback.
    var payload = {
      aspectRatio: '3.4 / 1',
      series: [{ key: 'lp', label: 'LP', color: 'var(--magenta)' }],
      data: points.map(function (p, i) {
        var tier = (p.tier || '').charAt(0) + (p.tier || '').slice(1).toLowerCase();
        return { date: p.ts, lp: scores[i], tip: tier + ' ' + (p.rank || '') + ' - ' + (p.leaguePoints || 0) + ' LP' };
      })
    };
    return '<div class="bm-chart-mount" data-bm-chart="' + bmAttr(payload) + '">' + svg + '</div>';
  }

  // Loads the Bklit chart bundle once, on the first profile that has an LP
  // curve, then mounts every pending [data-bm-chart]. A MutationObserver
  // covers tab switches / re-renders, which rebuild this markup from scratch.
  var bmChartsState = 0;
  function hydrateBmCharts() {
    if (!document.querySelector('[data-bm-chart]:not([data-bm-mounted])')) return;
    if (window.bmCharts && window.bmCharts.mountAll) { window.bmCharts.mountAll(); return; }
    if (bmChartsState) return;
    bmChartsState = 1;
    var sc = document.createElement('script');
    sc.src = (window.BM_ROOT || '/') + 'assets/js/bm-charts.js?v=__BM_CHARTS_V__';
    sc.async = true;
    document.head.appendChild(sc);
  }
  new MutationObserver(hydrateBmCharts).observe(document.body, { childList: true, subtree: true });

  // Portraits de champion réels (Data Dragon, clé = championName renvoyé
  // tel quel par Match-V5 -- garanti identique à la clé ddragon par Riot,
  // aucune table de correspondance à maintenir). Version résolue une fois
  // au chargement plutôt que codée en dur, pour ne pas se périmer à
  // chaque patch.
  var ddragonVersion = null;
  var ddragonReady = fetch('https://ddragon.leagueoflegends.com/api/versions.json')
    .then(function (r) { return r.json(); })
    .then(function (v) { ddragonVersion = v[0]; })
    .catch(function () {});
  function champPortraitInner(championName) {
    if (ddragonVersion) {
      return '<img class="league-icon-fallback" src="https://ddragon.leagueoflegends.com/cdn/' + ddragonVersion + '/img/champion/' + encodeURIComponent(championName) + '.png" alt="' + esc(championName) + '" loading="lazy">';
    }
    return esc(initials(championName));
  }

  // Glossaire des objets (nom réel, description courte, prix) -- source
  // Data Dragon, la même que pour ddragonVersion ci-dessus, en FR ou EN
  // selon la langue de la page. Alimente uniquement l'infobulle au survol
  // d'une icône d'objet (voir wireItemTooltip) ; les icônes elles-mêmes
  // viennent toujours de itemIconMap côté worker (CommunityDragon), ce
  // fichier ne sert qu'à retrouver le nom/texte à partir de l'id Riot.
  var lolItemGlossary = null;
  ddragonReady.then(function () {
    if (!ddragonVersion) return;
    var locale = document.documentElement.lang === 'fr' ? 'fr_FR' : 'en_US';
    return fetch('https://ddragon.leagueoflegends.com/cdn/' + ddragonVersion + '/data/' + locale + '/item.json')
      .then(function (r) { return r.json(); })
      .then(function (d) {
        lolItemGlossary = {};
        Object.keys(d.data || {}).forEach(function (id) {
          var it = d.data[id];
          lolItemGlossary[id] = { name: it.name, plaintext: it.plaintext || '', price: it.gold ? it.gold.total : null };
        });
      });
  }).catch(function () {});

  function el(tag, className, html) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (html !== undefined) e.innerHTML = html;
    return e;
  }
  function setStatus(text, isError) {
    if (!text) { statusEl.hidden = true; statusEl.textContent = ''; return; }
    statusEl.hidden = false;
    statusEl.textContent = text;
    statusEl.dataset.error = isError ? 'true' : 'false';
  }
  function setUrl(params) {
    var qs = new URLSearchParams(params).toString();
    history.pushState(params, '', location.pathname + (qs ? '?' + qs : ''));
  }
  async function fetchJson(url) {
    var res = await fetch(url);
    var data = await res.json().catch(function () { return {}; });
    if (!res.ok) {
      var err = new Error(data.error || ('HTTP ' + res.status));
      err.rateLimited = !!data.rateLimited || res.status === 429;
      err.retryAfter = data.retryAfter;
      throw err;
    }
    return data;
  }
  function bindIconFallback(container) {
    container.querySelectorAll('.league-icon-fallback').forEach(function (img) {
      img.addEventListener('error', function () { img.style.visibility = 'hidden'; });
    });
  }

  // Infobulle au survol d'une icône d'objet -- même mécanisme (#tooltip
  // partagé, classes .tt-*) que CHAMP_ICON_JS/GLOSSARY_ITEM_JS pour la
  // partie TFT du site. Délégation sur `document` : les lignes de partie
  // sont réinjectées via innerHTML à chaque rendu (renderProfile,
  // renderQueue...), pas la peine de re-brancher un listener par icône.
  var lolTooltip = document.getElementById('tooltip');
  function showItemTooltip(icon, e) {
    if (!lolItemGlossary || !lolTooltip) return;
    var d = lolItemGlossary[icon.dataset.itemId];
    if (!d) return;
    lolTooltip.innerHTML = '<div class="tt-name">' + esc(d.name) + '</div>'
      + (d.price ? '<div class="tt-row"><span>Prix</span><b class="nums">' + d.price + '</b></div>' : '')
      + (d.plaintext ? '<div class="tt-items">' + esc(d.plaintext) + '</div>' : '');
    lolTooltip.dataset.visible = 'true';
    moveItemTooltip(e);
  }
  function moveItemTooltip(e) {
    if (!lolTooltip) return;
    var pad = 14, x = e.clientX + pad, y = e.clientY + pad;
    if (x + 190 > window.innerWidth) x = e.clientX - 190 - pad;
    if (y + 130 > window.innerHeight) y = e.clientY - 130 - pad;
    lolTooltip.style.left = x + 'px';
    lolTooltip.style.top = y + 'px';
  }
  function hideItemTooltip() { if (lolTooltip) lolTooltip.dataset.visible = 'false'; }
  document.addEventListener('mouseover', function (e) {
    var icon = e.target.closest('.item-slot[data-item-id]');
    if (icon) showItemTooltip(icon, e);
  });
  document.addEventListener('mousemove', function (e) {
    if (e.target.closest('.item-slot[data-item-id]')) moveItemTooltip(e);
  });
  document.addEventListener('mouseout', function (e) {
    if (e.target.closest('.item-slot[data-item-id]')) hideItemTooltip();
  });
  function timeAgo(ts) {
    var mins = Math.round((Date.now() - ts) / 60000);
    if (mins < 60) return mins + ' ' + I.minAbbr;
    var hours = Math.round(mins / 60);
    if (hours < 24) return hours + ' ' + I.hourAbbr;
    return Math.round(hours / 24) + ' ' + I.dayAbbr;
  }
  // Anneau de winrate -- rayon 27 (circonférence ~169.65), même tracé que
  // l'artefact mais avec le pourcentage RÉEL du joueur, pas une valeur
  // figée dans le markup.
  function rankRingSvg(pct, good) {
    var c = 169.65;
    var offset = Math.round((c * (1 - pct / 100)) * 10) / 10;
    return '<svg viewBox="0 0 64 64" class="rank-ring">'
      + '<circle cx="32" cy="32" r="27" fill="none" stroke="var(--border-bright)" stroke-width="6"/>'
      + '<circle cx="32" cy="32" r="27" fill="none" stroke="var(--' + (good ? 'good' : 'warn') + ')" stroke-width="6" stroke-linecap="round" stroke-dasharray="' + c + '" stroke-dashoffset="' + offset + '" transform="rotate(-90 32 32)"/>'
      + '</svg>';
  }

  var currentData = null;
  var currentQueue = 'solo';
  var currentTab = 'history';

  function buildLoadoutHtml(m) {
    var itemsHtml = m.items.map(function (it) {
      return it.iconUrl ? '<img class="item-slot league-icon-fallback" src="' + it.iconUrl + '" data-item-id="' + it.id + '" alt="" loading="lazy">' : '<span class="item-slot"></span>';
    }).join('');
    var spellsHtml = m.spells.map(function (s) {
      return s.iconUrl ? '<img class="spell-icon league-icon-fallback" src="' + s.iconUrl + '" alt="" title="' + esc(s.name) + '" loading="lazy">' : '';
    }).join('');
    var runesHtml = (m.runes.keystoneIconUrl ? '<img class="rune-icon league-icon-fallback" src="' + m.runes.keystoneIconUrl + '" alt="" title="' + esc(m.runes.keystoneName) + '" loading="lazy">' : '')
      + (m.runes.secondaryStyleIconUrl ? '<img class="rune-icon small league-icon-fallback" src="' + m.runes.secondaryStyleIconUrl + '" alt="" title="' + esc(m.runes.secondaryStyleName) + '" loading="lazy">' : '');
    return '<div class="match-loadout">'
      + '<div class="spell-col">' + spellsHtml + '</div>'
      + '<div class="spell-col">' + runesHtml + '</div>'
      + '<div class="match-loadout-items">' + itemsHtml + '</div>'
      + '</div>';
  }

  function matchRowHtml(m, idx) {
    var kdaRatio = ((m.kills + m.assists) / Math.max(1, m.deaths)).toFixed(1);
    var csPerMin = (m.cs / m.durationMin).toFixed(1);
    return '<div class="match-row-wrap">'
      + '<div class="match-row ' + (m.win ? 'win' : 'loss') + '">'
      + '<div class="match-result">' + (m.win ? I.win : I.loss) + '</div>'
      + '<div class="match-champ-block">' + roleIcon(m.role, 'champ-role-icon')
      + '<span class="champ-portrait-wrap"><span class="champ-portrait">' + champPortraitInner(m.champion) + '</span>'
      + (m.runes.keystoneIconUrl ? '<img class="champ-rune-badge league-icon-fallback" src="' + m.runes.keystoneIconUrl + '" alt="" title="' + esc(m.runes.keystoneName) + '" loading="lazy">' : '') + '</span>'
      + '<div><div class="match-champ-name">' + esc(m.champion) + '</div><div class="match-queue">' + QUEUE_LABEL[currentQueue] + '</div></div></div>'
      + buildLoadoutHtml(m)
      + '<div class="match-kda"><div class="match-kda-v mono">' + m.kills + '/' + m.deaths + '/' + m.assists + '</div><div class="match-kda-ratio">' + kdaRatio + ' KDA</div></div>'
      + '<div class="match-cs"><div class="mono">' + m.cs + ' CS</div><div class="match-cs-l">' + csPerMin + '/min</div></div>'
      + (m.dmgPerMin != null ? '<div class="match-cs match-dpm"><div class="mono">' + fmtInt(m.dmgPerMin) + '</div><div class="match-cs-l">' + esc(I.dpmLabel) + '</div></div>' : '')
      + '<div class="match-meta">' + m.durationMin.toFixed(0) + ' min<br>' + timeAgo(m.startedAt) + '</div>'
      + '<button type="button" class="match-expand-btn" id="matchExpandBtn' + idx + '" aria-expanded="false" aria-label="' + esc(I.viewMatchAria) + '">'
      + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg></button>'
      + '</div>'
      + '<div class="match-detail" id="matchDetail' + idx + '" hidden></div>'
      + '</div>';
  }

  function renderScoreboardTeam(players, label, sideClass, durationMin) {
    return '<div class="scoreboard-team ' + sideClass + '"><div class="scoreboard-team-label">' + label + '</div>'
      + players.map(function (p) {
        var kdaText = p.isSelf ? '' : '<span class="scoreboard-kda mono">' + p.kills + '/' + p.deaths + '/' + p.assists + '</span>';
        var itemsHtml = p.items.map(function (it) {
          return it.iconUrl ? '<img class="item-slot league-icon-fallback" src="' + it.iconUrl + '" data-item-id="' + it.id + '" alt="" loading="lazy">' : '<span class="item-slot"></span>';
        }).join('');
        return '<div class="scoreboard-row' + (p.isSelf ? ' is-self' : '') + '">'
          + roleIcon(p.role, 'champ-role-icon') + '<span class="champ-portrait">' + champPortraitInner(p.champion) + '</span>'
          + '<span class="scoreboard-name">' + (p.isSelf ? esc(p.champion) + ' ' + I.you : esc(p.name)) + '</span>'
          + kdaText
          + '<span class="scoreboard-cs mono">' + p.cs + ' CS</span>'
          + (p.dmg != null && durationMin ? '<span class="scoreboard-cs scoreboard-dpm mono">' + fmtInt(p.dmg / durationMin) + ' ' + esc(I.dpmLabel) + '</span>' : '')
          + '<span class="scoreboard-gold mono">' + (p.gold / 1000).toFixed(1) + 'k</span>'
          + '<span class="scoreboard-items">' + itemsHtml + '</span>'
          + '</div>';
      }).join('') + '</div>';
  }

  // Badges de perf + classement dans la partie -- calculés sur le K/D/A
  // RÉEL du joueur et comparés aux 9 AUTRES vrais scores du scoreboard
  // (pas de simulation). Pas de ligne "elo moyen" ici : Riot n'expose pas
  // le rang des autres joueurs d'une partie, contrairement au mockup.
  function buildMatchSummary(m) {
    var badges = [];
    if (m.deaths === 0) badges.push(I.badgeDeathless);
    if (m.kills >= 7) badges.push(I.badgeTripleKill);
    else if (m.kills >= 5) badges.push(I.badgeDoubleKill);
    if (m.assists >= 10) badges.push(I.badgeGoodSupport);

    function score(p) { return p.kills * 2 + p.assists - p.deaths * 1.5; }
    var mySelf = m.scoreboard.filter(function (p) { return p.isSelf; })[0];
    var ranked = m.scoreboard.slice().sort(function (a, b) { return score(b) - score(a); });
    var rank = ranked.indexOf(mySelf) + 1;
    var medal = rank <= 3 ? I.medalGold : rank <= 6 ? I.medalSilver : I.medalBronze;
    badges.unshift(medal + ' ' + rank + '/10');

    var badgesHtml = badges.map(function (b, i) {
      return '<span class="perf-badge' + (i === 0 ? ' medal' : '') + '">' + b + '</span>';
    }).join('');
    return '<div class="match-summary-strip"><div class="summary-badges">' + badgesHtml + '</div></div>';
  }

  function toggleMatchDetail(idx, m) {
    var detail = document.getElementById('matchDetail' + idx);
    var willOpen = detail.hidden;
    detail.hidden = !willOpen;
    document.getElementById('matchExpandBtn' + idx).setAttribute('aria-expanded', willOpen ? 'true' : 'false');
    if (willOpen && !detail.dataset.built) {
      var allies = m.scoreboard.filter(function (p) { return p.team === 'ally'; });
      var enemies = m.scoreboard.filter(function (p) { return p.team === 'enemy'; });
      detail.innerHTML = buildMatchSummary(m) + '<div class="scoreboard-grid">'
        + renderScoreboardTeam(allies, I.allies, 'ally', m.durationMin)
        + renderScoreboardTeam(enemies, I.enemies, 'enemy', m.durationMin)
        + '</div>';
      detail.dataset.built = '1';
      bindIconFallback(detail);
    }
  }

  function renderMatchList(matches) {
    var list = document.getElementById('matchHistoryList');
    if (!matches.length) { list.innerHTML = '<div class="matchup-empty">' + esc(I.noRecentMatches) + '</div>'; return; }
    list.innerHTML = matches.map(matchRowHtml).join('');
    bindIconFallback(list);
    matches.forEach(function (m, idx) {
      document.getElementById('matchExpandBtn' + idx).addEventListener('click', function () { toggleMatchDetail(idx, m); });
    });
  }

  function champKda(c) { return c.kda.toFixed(1); }

  function renderChampionsTable(champions) {
    var wrap = document.getElementById('championsTableWrap');
    if (!champions.length) { wrap.innerHTML = '<div class="matchup-empty" style="padding:16px">' + esc(I.noChampionsPlayed) + '</div>'; return; }
    var hasDpm = champions.some(function (c) { return c.dpm != null; });
    var rows = champions.map(function (c) {
      return '<tr><td><div class="champ-cell"><span class="champ-portrait">' + champPortraitInner(c.champ) + '</span>' + esc(c.champ) + '</div></td>'
        + '<td class="num mono">' + c.games + '</td>'
        + '<td class="num"><span class="' + (c.wr >= 50 ? 'good' : 'warn') + '">' + c.wr + '%</span></td>'
        + '<td class="num mono">' + c.avgKills.toFixed(1) + ' / ' + c.avgDeaths.toFixed(1) + ' / ' + c.avgAssists.toFixed(1) + '</td>'
        + '<td class="num mono">' + champKda(c) + '</td>'
        + (hasDpm ? '<td class="num mono">' + (c.dpm != null ? fmtInt(c.dpm) : '-') + '</td>' : '') + '</tr>';
    }).join('');
    wrap.innerHTML = '<div class="champions-table-scroll"><table class="champions-table"><thead><tr><th>' + esc(I.thChampion) + '</th><th class="num">' + esc(I.thGames) + '</th><th class="num">' + esc(I.thWinrate) + '</th><th class="num">' + esc(I.thAvgKda) + '</th><th class="num">' + esc(I.thRatio) + '</th>' + (hasDpm ? '<th class="num">' + esc(I.thDpm) + '</th>' : '') + '</tr></thead><tbody>' + rows + '</tbody></table></div>';
    bindIconFallback(wrap);
  }

  // LP progress is now real (see recordLpSnapshot in lol-worker/src/
  // index.ts): every lookup appends one real point to that player's own
  // history in KV, so the chart grows as real visits happen. Comms stays a
  // clearly-labeled illustrative example below -- Riot's API doesn't
  // expose pings or chat messages at any endpoint, so there's no real data
  // to fall back to there at all.
  function lpSectionHtml() {
    var lpQueue = currentQueue === 'flex' ? 'flex' : 'solo';
    var points = (currentData.lpHistory && currentData.lpHistory[lpQueue]) || [];
    var queueLabel = lpQueue === 'flex' ? I.queueFlex : I.queueSolo;
    var inner;
    if (points.length >= 2) {
      inner = '<p class="profile-section-note" style="display:block;margin-bottom:10px">' + esc(I.lpRealNote).replace('{queue}', queueLabel).replace('{n}', points.length) + '</p>'
        + buildRealLpChartSvg(points);
    } else {
      var badge = '<div class="league-dev-badge"><span class="dot"></span>' + esc(points.length === 1 ? I.lpTrackingBadge : I.devBadge) + '</div>';
      inner = badge + '<p class="profile-section-note" style="display:block;margin-bottom:10px">' + esc(points.length === 1 ? I.lpOnePointNote : I.lpProgressNote) + '</p>';
    }
    return '<div class="stats-section"><div class="lp-chart-card">'
      + '<div class="stats-block-title" style="margin-bottom:8px">' + esc(I.lpProgressTitle) + '</div>' + inner + '</div></div>';
  }

  function fmtInt(n) {
    var s = String(Math.round(n)), out = '';
    for (var i = s.length; i > 0; i -= 3) out = s.slice(Math.max(0, i - 3), i) + (out ? String.fromCharCode(160) + out : '');
    return out;
  }
  // Measured rank averages (worker: rankExpected). Set at the start of each
  // stats-tab render; null when unranked / not sampled / ARAM.
  var currentRankMetrics = null, currentRankInfo = null;
  function cmpSub(you, key, mode) {
    var m = currentRankMetrics;
    if (!m || m[key] == null || !(m[key] > 0)) return '';
    var pct = ((you - m[key]) / m[key]) * 100;
    var tone = mode === 'neutral' ? 'dim' : ((mode === 'low' ? pct <= 0 : pct >= 0) ? 'good' : 'warn');
    return '<span class="' + tone + '">' + (pct >= 0 ? '+' : '') + Math.round(pct) + '%</span> ' + esc(I.kpiVsRank);
  }
  function joinSub(a, b) { return [a, b].filter(Boolean).join(' &middot; '); }
  function rankNoteHtml() {
    var r = currentRankInfo;
    if (!r) return '';
    var txt = r.approximate
      ? I.rankNoteApprox.replace('{tier}', tierLabel(r.tier)).replace('{used}', tierLabel(r.comparedTo))
      : I.rankNote.replace('{tier}', tierLabel(r.tier)).replace('{n}', fmtInt(r.sample));
    return '<p class="profile-section-note" style="display:block;margin:0 0 10px">' + esc(txt) + '</p>';
  }
  function kpiTile(label, value, sub, tone) {
    return '<div class="kpi-tile"><div class="kpi-label">' + esc(label) + '</div>'
      + '<div class="kpi-value mono' + (tone ? ' ' + tone : '') + '">' + value + '</div>'
      + (sub ? '<div class="kpi-sub">' + sub + '</div>' : '') + '</div>';
  }
  function kpiSection(title, note, tiles) {
    return '<div class="stats-section"><div class="stats-block-title">' + esc(title)
      + (note ? ' <span class="profile-section-note">' + esc(note) + '</span>' : '') + '</div>'
      + '<div class="kpi-grid">' + tiles.join('') + '</div></div>';
  }

  // Real pings (Match-V5 exposes every ping type; only chat text is missing).
  function realCommsHtml(q) {
    var pg = q && q.pings;
    if (!pg || !q.matches.length || !(pg.perGame > 0)) return null;
    var types = Object.keys(pg.byType).filter(function (k) { return pg.byType[k] > 0; })
      .sort(function (a, b) { return pg.byType[b] - pg.byType[a]; }).slice(0, 8);
    var top = pg.byType[types[0]] || 1;
    var rows = types.map(function (k) {
      return '<div class="comms-ping-row"><span class="comms-ping-label">' + esc((I.pingLabels && I.pingLabels[k]) || k) + '</span>'
        + '<div class="comms-ping-bar-track"><div class="comms-ping-bar-fill" style="width:' + Math.round((pg.byType[k] / top) * 100) + '%"></div></div>'
        + '<span class="comms-ping-value mono">' + pg.byType[k].toFixed(1) + '</span></div>';
    }).join('');
    return '<div class="stats-section"><div class="lp-chart-card">'
      + '<div class="stats-block-title" style="margin-bottom:8px">' + esc(I.commsRealTitle) + '</div>'
      + '<p class="profile-section-note" style="display:block;margin-bottom:10px">' + esc(I.commsRealNote).replace('{n}', q.matches.length) + '</p>'
      + '<div class="stats-comms-grid"><div class="stats-comms-msg"><div class="stats-comms-msg-value mono">' + pg.perGame.toFixed(1) + '</div>'
      + '<div class="stats-comms-msg-label">' + esc(I.pingsPerGame) + '</div>'
      + (cmpSub(pg.perGame, 'pingsPerGame', 'neutral') ? '<div class="stats-comms-msg-label" style="margin-top:4px">' + cmpSub(pg.perGame, 'pingsPerGame', 'neutral') + '</div>' : '')
      + '</div><div class="comms-ping-list">' + rows + '</div></div></div></div>';
  }

  function combatSectionHtml(q) {
    var c = q.combat;
    if (!c || !q.matches.length) return '';
    var per = '<span class="dim">' + esc(I.perGameUnit) + '</span>';
    return kpiSection(I.combatTitle, I.perGameNote, [
      kpiTile(I.kpiDpm, fmtInt(c.dpm), cmpSub(c.dpm, 'dpm', 'high'), 'accent'),
      kpiTile(I.kpiDmgTaken, fmtInt(c.damageTakenPerMin), cmpSub(c.damageTakenPerMin, 'damageTakenPerMin', 'neutral')),
      kpiTile(I.kpiMitigated, fmtInt(c.mitigatedPerMin), cmpSub(c.mitigatedPerMin, 'mitigatedPerMin', 'neutral')),
      kpiTile(I.kpiCc, c.ccTime.toFixed(0) + ' s', joinSub(per, cmpSub(c.ccTime, 'ccTime', 'high'))),
      kpiTile(I.kpiDead, c.deadPct.toFixed(1) + '%', cmpSub(c.deadPct, 'deadPct', 'low')),
      kpiTile(I.kpiHeal, fmtInt(c.healPerMin), cmpSub(c.healPerMin, 'healPerMin', 'neutral'))
    ]);
  }

  function visionSectionHtml(q) {
    if (currentQueue === 'aram' || !q.vision || !q.objectives || !q.matches.length) return '';
    var v = q.vision, o = q.objectives, per = '<span class="dim">' + esc(I.perGameUnit) + '</span>';
    return kpiSection(I.visionTitle, I.perGameNote, [
      kpiTile(I.kpiVisionMin, v.scorePerMin.toFixed(1), cmpSub(v.scorePerMin, 'visionPerMin', 'high'), 'accent'),
      kpiTile(I.kpiWardsPlaced, v.wardsPlaced.toFixed(1), joinSub(per, cmpSub(v.wardsPlaced, 'wardsPlaced', 'high'))),
      kpiTile(I.kpiWardsKilled, v.wardsKilled.toFixed(1), joinSub(per, cmpSub(v.wardsKilled, 'wardsKilled', 'high'))),
      kpiTile(I.kpiControlWards, v.controlWards.toFixed(1), joinSub(per, cmpSub(v.controlWards, 'controlWards', 'high'))),
      kpiTile(I.kpiTurrets, o.turrets.toFixed(1), joinSub(per, cmpSub(o.turrets, 'turrets', 'high'))),
      kpiTile(I.kpiPlates, o.plates.toFixed(1), joinSub(per, cmpSub(o.plates, 'plates', 'high'))),
      kpiTile(I.kpiDragons, o.dragons.toFixed(1), joinSub(per, cmpSub(o.dragons, 'dragons', 'high'))),
      kpiTile(I.kpiBarons, o.barons.toFixed(1), joinSub(per, cmpSub(o.barons, 'barons', 'high'))),
      kpiTile(I.kpiHeralds, o.heralds.toFixed(1), joinSub(per, cmpSub(o.heralds, 'heralds', 'high'))),
      kpiTile(I.kpiObjDmg, fmtInt(o.objDamagePerMin), cmpSub(o.objDamagePerMin, 'objDmgPerMin', 'high'))
    ]);
  }

  function recordsSectionHtml(q) {
    var r = q.records, f = q.form;
    if (!r || !q.matches.length) return '';
    var tiles = [];
    if (r.bestKda) tiles.push(kpiTile(I.kpiBestKda, r.bestKda.kills + '/' + r.bestKda.deaths + '/' + r.bestKda.assists, esc(r.bestKda.champion) + ' &middot; ' + r.bestKda.kda.toFixed(1) + ' KDA', r.bestKda.win ? 'good' : ''));
    if (r.mostKills) tiles.push(kpiTile(I.kpiMostKills, r.mostKills.kills, esc(r.mostKills.champion)));
    if (r.bestDpm) tiles.push(kpiTile(I.kpiBestDpm, fmtInt(r.bestDpm.dpm), esc(r.bestDpm.champion), 'accent'));
    tiles.push(kpiTile(I.kpiPentas, r.pentas, r.quadras + ' ' + esc(I.quadrasLabel)));
    tiles.push(kpiTile(I.kpiSpree, r.longestSpree));
    tiles.push(kpiTile(I.kpiFirstBlood, r.firstBloodPct + '%'));
    tiles.push(kpiTile(I.kpiSoloKills, r.soloKills));
    if (f) {
      tiles.push(kpiTile(f.streak.type === 'win' ? I.kpiStreakWin : I.kpiStreakLoss, f.streak.length, null, f.streak.type === 'win' ? 'good' : 'warn'));
      if (f.afterLoss) tiles.push(kpiTile(I.kpiAfterLoss, f.afterLoss.wr + '%', f.afterLoss.games + ' ' + esc(I.gamesUnitShort), f.afterLoss.wr >= 50 ? 'good' : 'warn'));
    }
    var bucketLabel = { short: I.kpiShort, mid: I.kpiMid, long: I.kpiLong };
    (q.durationStats || []).forEach(function (b) {
      tiles.push(kpiTile(bucketLabel[b.bucket], b.wr + '%', b.games + ' ' + esc(I.gamesUnitShort), b.wr >= 50 ? 'good' : 'warn'));
    });
    return kpiSection(I.recordsTitle, null, tiles);
  }

  function masterySectionHtml() {
    var list = currentData && currentData.mastery;
    if (!list || !list.length) return '';
    var top = list[0].points || 1;
    var rows = list.map(function (m) {
      return '<div class="mastery-row"><span class="champ-portrait">' + champPortraitInner(m.champ) + '</span>'
        + '<span class="mastery-name">' + esc(m.champ) + '</span>'
        + '<span class="mastery-level mono">' + esc(I.masteryLevel) + ' ' + m.level + '</span>'
        + '<div class="mastery-bar-track"><div class="mastery-bar-fill" style="width:' + Math.round((m.points / top) * 100) + '%"></div></div>'
        + '<span class="mastery-pts mono">' + fmtInt(m.points) + ' ' + esc(I.masteryPts) + '</span></div>';
    }).join('');
    return '<div class="stats-section"><div class="stats-block-title">' + esc(I.masteryTitle) + '</div><div class="mastery-list">' + rows + '</div></div>';
  }

  function devSectionsHtml() {
    var badge = '<div class="league-dev-badge"><span class="dot"></span>' + esc(I.devBadge) + '</div>';
    var perGame = I.lang === 'fr' ? ' / partie' : ' / game';
    var realComms = realCommsHtml(currentData.queues[currentQueue]);
    if (realComms) return lpSectionHtml() + realComms;
    return lpSectionHtml()
      + '<div class="stats-section"><div class="lp-chart-card">' + badge
      + '<div class="stats-block-title" style="margin-bottom:8px">' + esc(I.commsTitle) + '</div>'
      + '<p class="profile-section-note" style="display:block;margin-bottom:10px">' + esc(I.commsNote) + '</p>'
      + '<div class="stats-comms-grid"><div class="stats-comms-msg"><div class="stats-comms-msg-value mono">6.4</div><div class="stats-comms-msg-label">' + esc(I.messagesPerGame) + '</div></div>'
      + '<div class="comms-ping-list">'
      + '<div class="comms-ping-row"><span class="comms-ping-label">' + esc(I.pingOnMyWay) + '</span><div class="comms-ping-bar-track"><div class="comms-ping-bar-fill" style="width:70%"></div></div><span class="comms-ping-value mono">2.1' + perGame + '</span></div>'
      + '<div class="comms-ping-row"><span class="comms-ping-label">' + esc(I.pingMissing) + '</span><div class="comms-ping-bar-track"><div class="comms-ping-bar-fill" style="width:60%"></div></div><span class="comms-ping-value mono">1.8' + perGame + '</span></div>'
      + '<div class="comms-ping-row"><span class="comms-ping-label">' + esc(I.pingDanger) + '</span><div class="comms-ping-bar-track"><div class="comms-ping-bar-fill" style="width:40%"></div></div><span class="comms-ping-value mono">1.2' + perGame + '</span></div>'
      + '</div></div></div></div>';
  }

  function renderStatsTab(q, rankAverages) {
    var wrap = document.getElementById('statsTabWrap');
    var topChamps = q.champions.filter(function (c) { return c.games >= 2; }).slice().sort(function (a, b) { return b.kda - a.kda; }).slice(0, 3);
    var topChampsHtml = topChamps.length ? topChamps.map(function (c, i) {
      return '<div class="stats-top-champ-card"><span class="stats-top-champ-rank">#' + (i + 1) + '</span>'
        + '<span class="champ-portrait">' + champPortraitInner(c.champ) + '</span>'
        + '<div class="stats-top-champ-info"><div class="stats-top-champ-name">' + esc(c.champ) + '</div>'
        + '<div class="stats-top-champ-sub">' + c.games + ' parties &middot; <span class="' + (c.wr >= 50 ? 'good' : 'warn') + '">' + c.wr + '% WR</span></div></div>'
        + '<div class="stats-top-champ-kda mono">' + c.kda.toFixed(1) + ' <span>KDA</span></div></div>';
    }).join('') : '<div class="matchup-empty">' + esc(I.notEnoughSameChamp) + '</div>';

    var maxRoleGames = Math.max.apply(null, q.roleStats.map(function (r) { return r.games; })) || 1;
    var roleHtml = q.roleStats.length ? q.roleStats.map(function (r) {
      var pct = Math.round((r.games / maxRoleGames) * 100);
      return '<div class="role-stat-row"><div class="role-stat-role">' + roleIcon(r.role) + (ROLE_LABEL[r.role] || r.role) + '</div>'
        + '<div class="role-stat-bar-track"><div class="role-stat-bar-fill" style="width:' + pct + '%"></div></div>'
        + '<div class="role-stat-games mono">' + r.games + ' ' + esc(I.partiesUnit) + '</div>'
        + '<div class="role-stat-wr ' + (r.wr >= 50 ? 'good' : 'warn') + '">' + r.wr + '%</div></div>';
    }).join('') : '<div class="matchup-empty">' + esc(I.noMatchesInQueue) + '</div>';

    function compareCard(label, you, rankAvg, unit, decimals) {
      var scale = Math.max(you, rankAvg) * 1.15 || 1;
      var diff = you - rankAvg;
      return '<div class="stats-compare-card"><div class="stats-compare-label">' + label + '</div>'
        + '<div class="stats-compare-row"><span class="stats-compare-name">' + esc(I.youLabel) + '</span><div class="stats-compare-track"><div class="stats-compare-fill you" style="width:' + Math.round((you / scale) * 100) + '%"></div></div><span class="stats-compare-value mono">' + you.toFixed(decimals) + unit + '</span></div>'
        + '<div class="stats-compare-row"><span class="stats-compare-name">' + esc(I.rankAvgLabel) + '</span><div class="stats-compare-track"><div class="stats-compare-fill rank" style="width:' + Math.round((rankAvg / scale) * 100) + '%"></div></div><span class="stats-compare-value mono">' + rankAvg.toFixed(decimals) + unit + '</span></div>'
        + '<div class="stats-compare-diff ' + (diff >= 0 ? 'good' : 'warn') + '">' + (diff >= 0 ? '+' : '') + diff.toFixed(decimals) + unit + ' ' + esc(I.vsAvg) + '</div></div>';
    }
    var sa = q.statsAvg;
    var rx = q.rankExpected ? q.rankExpected.metrics : null;
    var ra = rx ? { csPerMin: rx.csPerMin, goldPerMin: rx.goldPerMin, dmgPerMin: rx.dpm, killParticipation: rx.killParticipation } : rankAverages;
    currentRankInfo = q.rankExpected || null;
    currentRankMetrics = rx;
    var compareHtml = !q.matches.length ? '<div class="matchup-empty">' + esc(I.notEnoughToCompare) + '</div>'
      : !ra ? '<div class="matchup-empty">' + esc(I.noRankData) + '</div>'
      : [
      compareCard(I.csPerMin, sa.csPerMin, ra.csPerMin, '', 1),
      compareCard(I.goldPerMin, sa.goldPerMin, ra.goldPerMin, '', 0),
      compareCard(I.dmgPerMin, sa.dmgPerMin, ra.dmgPerMin, '', 0),
      compareCard(I.killParticipation, sa.killParticipation, ra.killParticipation, '%', 0),
    ].join('');

    // Radar (Bklit): shape of the profile vs the rank average at a glance.
    // Each metric is normalised to its own max(you, rank avg) so the axes are
    // comparable; the exact numbers stay in the four cards below.
    var radarHtml = '';
    if (q.matches.length && ra) {
      var radarMetrics = [
        { key: 'cs', label: 'CS/min', you: sa.csPerMin, avg: ra.csPerMin },
        { key: 'gold', label: '\\u00a0\\u00a0Gold/min', you: sa.goldPerMin, avg: ra.goldPerMin },
        { key: 'dmg', label: 'Dmg/min', you: sa.dmgPerMin, avg: ra.dmgPerMin },
        { key: 'kp', label: 'KP', you: sa.killParticipation, avg: ra.killParticipation }
      ];
      if (rx && q.vision && currentQueue !== 'aram') radarMetrics.push({ key: 'vision', label: 'Vision/min', you: q.vision.scorePerMin, avg: rx.visionPerMin });
      var youVals = {}, avgVals = {};
      radarMetrics.forEach(function (m) {
        var top = Math.max(m.you, m.avg) || 1;
        youVals[m.key] = Math.round((m.you / top) * 100);
        avgVals[m.key] = Math.round((m.avg / top) * 100);
      });
      radarHtml = '<div class="stats-radar" data-bm-chart="' + bmAttr({
        type: 'radar', size: 320,
        metrics: radarMetrics.map(function (m) { return { key: m.key, label: m.label }; }),
        radar: [{ label: I.youLabel, color: 'var(--magenta)', values: youVals }, { label: I.rankAvgLabel, color: 'var(--cream)', values: avgVals }]
      }) + '"></div>';
    }

    var maxWeekday = Math.max.apply(null, q.weekdayStats.map(function (d) { return d.games; })) || 1;
    var weekdayHtml = q.weekdayStats.map(function (d) {
      var pct = Math.round((d.games / maxWeekday) * 100);
      var labelClass = d.idx === 5 ? ' sam' : d.idx === 6 ? ' dim' : '';
      // d.label vient du worker, toujours en français (WEEKDAY_LABELS y est
      // codé en dur) -- recalculé ici depuis l'index numérique plutôt que
      // d'ajouter un paramètre de langue à l'API pour un simple libellé.
      return '<div class="weekday-bar-col"><div class="weekday-bar-value mono">' + d.games + '</div>'
        + '<div class="weekday-bar-track"><div class="weekday-bar-fill ' + (d.games === 0 ? '' : (d.wr >= 50 ? 'good' : 'warn')) + '" style="height:' + pct + '%"></div></div>'
        + '<div class="weekday-bar-label' + labelClass + '">' + esc(I.weekdayLabels[d.idx]) + '</div></div>';
    }).join('');
    var weekdayPayload = {
      type: 'bar', aspectRatio: '2.6 / 1',
      series: [{ key: 'good', label: 'WR >= 50%', color: 'var(--good)' }, { key: 'warn', label: 'WR < 50%', color: 'var(--warn)' }],
      data: q.weekdayStats.map(function (d) {
        return { name: I.weekdayLabels[d.idx], good: d.wr >= 50 ? d.games : 0, warn: d.wr >= 50 ? 0 : d.games, tip: d.games + ' ' + I.gamesUnit + ' - ' + d.wr + '%' };
      })
    };
    var hourlyHtml = q.hourlyStats.filter(function (h) { return h.games > 0; }).map(function (h) {
      return '<div class="hourly-row"><span class="hourly-time mono">' + (h.hour < 10 ? '0' : '') + h.hour + ':00</span>'
        + '<span class="hourly-badge ' + (h.wr >= 50 ? 'good' : 'warn') + '">' + h.games + ' ' + esc(I.gamesUnit) + '</span>'
        + '<span class="hourly-wr mono">' + h.wr + '%</span></div>';
    }).join('') || '<div class="matchup-empty">' + esc(I.notEnoughHourly) + '</div>';

    wrap.innerHTML =
      '<div class="stats-section"><div class="stats-block-title">' + esc(I.seasonBestTitle) + ' <span class="profile-section-note">' + esc(I.seasonBestSub) + '</span></div><div class="stats-top-champs">' + topChampsHtml + '</div></div>'
      + masterySectionHtml()
      + '<div class="stats-section"><div class="stats-block-title">' + esc(I.roleDistTitle) + ' <span class="profile-section-note">' + q.matches.length + ' ' + esc(I.partiesUnit) + '</span></div><div class="role-stats-list">' + roleHtml + '</div></div>'
      + '<div class="stats-section"><div class="stats-block-title">' + esc(I.youVsRankTitle) + '</div>' + rankNoteHtml() + radarHtml + '<div class="stats-compare-grid">' + compareHtml + '</div></div>'
      + combatSectionHtml(q) + visionSectionHtml(q) + recordsSectionHtml(q)
      + '<div class="stats-section"><div class="stats-block-title-row"><div class="stats-block-title" style="margin-bottom:0">' + esc(I.activityTitle) + '</div></div>'
      + '<div class="activity-subtitle">' + esc(I.weekdaysLabel) + '</div><div class="weekday-chart" data-bm-chart="' + bmAttr(weekdayPayload) + '">' + weekdayHtml + '</div>'
      + '<div class="activity-subtitle" style="margin-top:18px">' + esc(I.hourlyLabel) + '</div><div class="hourly-list">' + hourlyHtml + '</div></div>'
      + devSectionsHtml();
    bindIconFallback(wrap);
  }

  function renderSidebarQueueBits(q) {
    var most = q.champions.slice(0, 4);
    document.getElementById('mostPlayedGrid').innerHTML = most.length ? most.map(function (c) {
      return '<div class="most-played-row"><span class="champ-portrait">' + champPortraitInner(c.champ) + '</span>'
        + '<span class="most-played-name">' + esc(c.champ) + '</span>'
        + '<span class="most-played-kda mono">' + c.kda.toFixed(1) + ' KDA</span>'
        + '<span class="most-played-wr ' + (c.wr >= 50 ? 'good' : 'warn') + '">' + c.wr + '%</span></div>';
    }).join('') : '<div class="matchup-empty">' + esc(I.noRecentGame) + '</div>';
    bindIconFallback(document.getElementById('mostPlayedGrid'));

    var hasPlayedWith = q.playedWith.length > 0;
    document.getElementById('duoPartnerDivider').hidden = !hasPlayedWith;
    document.getElementById('duoPartnerTitle').hidden = !hasPlayedWith;
    document.getElementById('duoPartnerList').innerHTML = q.playedWith.map(function (p) {
      return '<div class="duo-partner-row"><div class="duo-partner-info"><div class="duo-partner-name">' + esc(p.riotId) + '</div>'
        + '<div class="duo-partner-meta">' + p.games + ' ' + esc(I.gamesTogether) + '</div></div>'
        + '<div class="duo-partner-stats"><div class="duo-partner-wr ' + (p.wr >= 50 ? 'good' : 'warn') + '">' + p.wr + '%</div>'
        + '<div class="duo-partner-record">' + p.wins + I.winAbbr + ' ' + (p.games - p.wins) + I.lossAbbr + '</div></div></div>';
    }).join('');
  }

  function setProfileTab(tab) {
    currentTab = tab;
    document.getElementById('tabHistory').setAttribute('data-active', tab === 'history' ? 'true' : 'false');
    document.getElementById('tabChampions').setAttribute('data-active', tab === 'champions' ? 'true' : 'false');
    document.getElementById('tabStats').setAttribute('data-active', tab === 'stats' ? 'true' : 'false');
    document.getElementById('matchHistoryList').hidden = tab !== 'history';
    document.getElementById('championsTableWrap').hidden = tab !== 'champions';
    document.getElementById('statsTabWrap').hidden = tab !== 'stats';
    renderActiveTab();
  }

  function renderActiveTab() {
    var q = currentData.queues[currentQueue];
    if (currentTab === 'history') renderMatchList(q.matches);
    else if (currentTab === 'champions') renderChampionsTable(q.champions);
    else renderStatsTab(q, currentData.rankAverages);
  }

  function renderQueue(queueKey) {
    currentQueue = queueKey;
    document.querySelectorAll('.queue-filter-btn').forEach(function (btn) {
      btn.setAttribute('data-active', btn.dataset.queue === queueKey ? 'true' : 'false');
    });
    renderSidebarQueueBits(currentData.queues[queueKey]);
    renderActiveTab();
  }

  function renderProfile(data) {
    currentData = data;
    currentQueue = data.ranks.solo || !data.ranks.flex ? 'solo' : 'flex';
    currentTab = 'history';

    var primary = data.ranks.solo || data.ranks.flex;
    var secondary = data.ranks.solo ? data.ranks.flex : null;
    var wr = primary ? Math.round((primary.wins / Math.max(1, primary.wins + primary.losses)) * 100) : 0;

    var avatarHtml = data.profileIconId
      ? '<img class="league-icon-fallback" src="https://raw.communitydragon.org/latest/plugins/rcp-be-lol-game-data/global/default/v1/profile-icons/' + data.profileIconId + '.jpg" alt="">'
      : esc(initials(data.riotId));

    var sidebarHtml =
      '<div class="profile-id">' + esc(data.riotId.split('#')[0]) + ' <span class="tag">#' + esc(data.riotId.split('#')[1] || '') + '</span></div>'
      + (primary ? '<div class="rank-emblem-wrap"><img class="rank-emblem league-icon-fallback" src="' + primary.emblemUrl + '" alt=""></div>'
        + '<div class="rank-tier-name">' + tierLabel(primary.tier) + ' ' + primary.rank + '</div>'
        + '<div class="rank-lp mono">' + primary.leaguePoints + ' LP</div>'
        + '<div class="rank-ring-wrap" data-bm-chart="' + bmAttr({ type: 'gauge', value: wr, suffix: '%', label: primary.wins + I.winAbbr, color: wr >= 50 ? 'var(--good)' : 'var(--warn)', size: 112 }) + '">' + rankRingSvg(wr, wr >= 50) + '<div class="rank-ring-label"><div class="rank-ring-pct">' + wr + '%</div><div class="rank-ring-sub">' + primary.wins + I.winAbbr + '</div></div></div>'
        + '<div class="rank-record">' + primary.wins + I.winAbbr + ' ' + primary.losses + I.lossAbbr + '</div>'
        : '<div class="rank-tier-name" style="color:var(--text-faint)">' + esc(I.unranked) + '</div>')
      + '<div class="sidebar-divider"></div>'
      + (secondary
        ? '<div class="flex-rank-row"><span class="sidebar-subtitle" style="margin-bottom:0">' + esc(I.queueFlex) + '</span><span class="flex-rank-value">' + tierLabel(secondary.tier) + ' ' + secondary.rank + ' <span class="mono">' + secondary.leaguePoints + ' LP</span></span></div>'
        : '<div class="flex-rank-row"><span class="sidebar-subtitle" style="margin-bottom:0">' + esc(I.queueFlex) + '</span><span class="flex-rank-value" style="color:var(--text-faint)">' + esc(I.unranked) + '</span></div>')
      + '<div class="sidebar-divider"></div>'
      + '<div class="sidebar-subtitle">' + esc(I.mostPlayed) + ' <span class="profile-section-note">' + QUEUE_LABEL[currentQueue] + '</span></div>'
      + '<div class="most-played-list" id="mostPlayedGrid"></div>'
      + '<button type="button" class="see-all-champs-btn" id="seeAllChampsBtn">' + esc(I.seeAllChamps) + '</button>'
      + '<div class="sidebar-divider" id="duoPartnerDivider" hidden></div>'
      + '<div class="sidebar-subtitle" id="duoPartnerTitle" hidden>' + esc(I.playedWith) + ' <span class="profile-section-note">' + esc(I.recentMatches) + '</span></div>'
      + '<div class="duo-partner-list" id="duoPartnerList"></div>';

    var card = el('div', 'profile-card', '');
    card.style.setProperty('--tc', 'var(--gold)');
    card.innerHTML =
      '<span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span>'
      + '<div class="profile-sidebar">' + sidebarHtml + '</div>'
      + '<div class="profile-main">'
      + '<div class="profile-main-tabs">'
      + '<button type="button" class="profile-main-tab" id="tabHistory" data-active="true">' + esc(I.tabHistory) + '</button>'
      + '<button type="button" class="profile-main-tab" id="tabChampions">' + esc(I.tabChampions) + '</button>'
      + '<button type="button" class="profile-main-tab" id="tabStats">' + esc(I.tabStats) + '</button>'
      + '</div>'
      + '<div id="queueFilterBar" class="queue-filter-bar">'
      + '<button type="button" class="queue-filter-btn" data-queue="solo" data-active="' + (currentQueue === 'solo' ? 'true' : 'false') + '">' + esc(I.queueSolo) + '</button>'
      + '<button type="button" class="queue-filter-btn" data-queue="flex" data-active="' + (currentQueue === 'flex' ? 'true' : 'false') + '">' + esc(I.queueFlex) + '</button>'
      + '<button type="button" class="queue-filter-btn" data-queue="aram" data-active="' + (currentQueue === 'aram' ? 'true' : 'false') + '">' + esc(I.queueAram) + '</button>'
      + '</div>'
      + '<div class="match-history-list" id="matchHistoryList"></div>'
      + '<div id="championsTableWrap" hidden></div>'
      + '<div id="statsTabWrap" hidden></div>'
      + '</div>';

    var isFav = isLolFavorite(data.riotId, data.region);
    var header = el('div', 'player-header',
      '<div class="player-avatar">' + avatarHtml + '</div>'
      + '<div><div class="player-name-row"><span class="player-name">' + esc(data.riotId) + '</span>'
      + '<button type="button" class="fav-btn inline" id="lolFavBtn" aria-pressed="' + (isFav ? 'true' : 'false') + '" '
      + 'title="' + esc(isFav ? I.favRemove : I.favAdd) + '" aria-label="' + esc(isFav ? I.favRemove : I.favAdd) + '">' + STAR_SVG + '</button></div>'
      + '<div class="lol-fav-hint" id="lolFavHint"' + (isFav ? ' hidden' : '') + '>' + esc(I.favHint) + '</div>'
      + '<div class="player-meta">' + esc(data.region) + (data.summonerLevel ? ' &middot; ' + esc(I.level) + ' ' + data.summonerLevel : '') + '</div></div>');

    results.innerHTML = '';
    results.appendChild(header);
    bindIconFallback(header);
    var lolFavBtn = document.getElementById('lolFavBtn');
    if (lolFavBtn) {
      lolFavBtn.addEventListener('click', function () {
        var nowSaved = toggleLolFavorite(data.riotId, data.region);
        lolFavBtn.setAttribute('aria-pressed', nowSaved ? 'true' : 'false');
        var label = nowSaved ? I.favRemove : I.favAdd;
        lolFavBtn.title = label;
        lolFavBtn.setAttribute('aria-label', label);
        var hint = document.getElementById('lolFavHint');
        if (hint) hint.hidden = nowSaved;
      });
    }
    if (data.liveGame) {
      var liveEl = el('div', 'live-game-banner', buildLiveGameHtml(data.liveGame));
      results.appendChild(liveEl);
      bindIconFallback(liveEl);
    }
    results.appendChild(card);
    bindIconFallback(card);

    document.getElementById('tabHistory').addEventListener('click', function () { setProfileTab('history'); });
    document.getElementById('tabChampions').addEventListener('click', function () { setProfileTab('champions'); });
    document.getElementById('tabStats').addEventListener('click', function () { setProfileTab('stats'); });
    document.getElementById('seeAllChampsBtn').addEventListener('click', function () { setProfileTab('champions'); });
    document.querySelectorAll('.queue-filter-btn').forEach(function (btn) {
      btn.addEventListener('click', function () { renderQueue(btn.dataset.queue); });
    });

    renderSidebarQueueBits(data.queues[currentQueue]);
    renderActiveTab();
    window.scrollTo(0, 0);
  }

  // The Riot dev key allows 100 requests / 2 min for ALL visitors combined
  // (one profile costs ~36), so the worker caches profiles for 2 min and this
  // cooldown only stops double-clicks (short) or backs off after a rate-limit
  // answer (long). Kept in localStorage so a page refresh doesn't skip it.
  var submitBtn = form.querySelector('button[type="submit"]');
  var submitLabel = submitBtn ? submitBtn.textContent : '';
  var COOLDOWN_KEY = 'bmLolCooldownUntil';
  var cooldownTimer = null;
  function cooldownLeft() {
    var until = 0;
    try { until = Number(localStorage.getItem(COOLDOWN_KEY)) || 0; } catch (e) {}
    return Math.ceil((until - Date.now()) / 1000);
  }
  function tickCooldown() {
    clearTimeout(cooldownTimer);
    if (!submitBtn) return;
    var left = cooldownLeft();
    if (left > 0) {
      submitBtn.disabled = true;
      submitBtn.textContent = I.cooldownLabel.replace('{s}', left);
      cooldownTimer = setTimeout(tickCooldown, 1000);
    } else {
      submitBtn.disabled = false;
      submitBtn.textContent = submitLabel;
    }
  }
  function startCooldown(seconds) {
    try { localStorage.setItem(COOLDOWN_KEY, String(Date.now() + seconds * 1000)); } catch (e) {}
    tickCooldown();
  }
  tickCooldown();

  // Skeleton shaped like the profile card, shown while the worker answers
  // (2-10 s, longer when Riot is rate-limited).
  function skeletonProfileHtml() {
    var rows = '';
    for (var i = 0; i < 6; i++) {
      rows += '<div class="skel-row"><span class="skel" style="width:58px;height:14px"></span><span class="skel skel-circle" style="width:38px;height:38px"></span>'
        + '<span class="skel" style="flex:1;height:12px"></span><span class="skel" style="width:64px;height:12px"></span></div>';
    }
    return '<div class="profile-card skel-card" aria-hidden="true">'
      + '<div class="profile-sidebar"><span class="skel" style="width:120px;height:16px;align-self:flex-start;margin-bottom:14px"></span>'
      + '<span class="skel skel-circle" style="width:88px;height:88px;margin-bottom:12px"></span>'
      + '<span class="skel" style="width:110px;height:14px;margin-bottom:8px"></span><span class="skel" style="width:70px;height:12px;margin-bottom:16px"></span>'
      + '<span class="skel skel-circle" style="width:80px;height:80px"></span></div>'
      + '<div class="profile-main"><div class="skel-tabs"><span class="skel" style="width:90px;height:28px"></span><span class="skel" style="width:90px;height:28px"></span><span class="skel" style="width:90px;height:28px"></span></div>' + rows + '</div></div>';
  }

  async function runProfile(riotId, region) {
    setStatus(I.loading, false);
    results.innerHTML = skeletonProfileHtml();
    try {
      await ddragonReady;
      var data = await fetchJson(API + '/profile?riotId=' + encodeURIComponent(riotId) + '&region=' + encodeURIComponent(region));
      setStatus(null);
      results.innerHTML = '';
      setUrl({ riotId: riotId, region: region });
      renderProfile(data);
      recordLolRecentSearch(data.riotId, data.region);
      var ageMin = data.generatedAt ? Math.round((Date.now() - data.generatedAt) / 60000) : 0;
      if (ageMin >= 3) setStatus(I.staleNote.replace('{min}', ageMin), false);
      startCooldown(8);
      if (window.gtag) gtag('event', 'league_lookup', { region: region, success: true });
    } catch (e) {
      results.innerHTML = '';
      setStatus(e.message || String(e), true);
      if (e && e.rateLimited) startCooldown(e.retryAfter || 75);
      if (window.gtag) gtag('event', 'league_lookup', { region: region, success: false });
    }
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    if (cooldownLeft() > 0) return;
    var riotId = riotIdInput.value.trim();
    if (riotId) runProfile(riotId, regionSelect.value);
  });

  window.addEventListener('popstate', function () {
    var p = new URLSearchParams(location.search);
    var riotId = p.get('riotId');
    if (!riotId) { results.innerHTML = ''; setStatus(null); return; }
    riotIdInput.value = riotId;
    regionSelect.value = p.get('region') || 'EUW';
    runProfile(riotId, regionSelect.value);
  });

  var initial = new URLSearchParams(location.search);
  var initialRiotId = initial.get('riotId');
  if (initialRiotId) {
    riotIdInput.value = initialRiotId;
    regionSelect.value = initial.get('region') || 'EUW';
    runProfile(initialRiotId, regionSelect.value);
  }
})();
"""

# /league/comparer/: fetch two real profiles from the same lol-worker
# /profile endpoint as league.js and render their real stats side by side
# -- rank, solo-queue win rate, and the same real per-minute averages
# league.js already computes server-side (statsAvg), just "Player A vs
# Player B" instead of "You vs rank average". No new worker route, no
# fabricated numbers -- two ordinary profile lookups, rendered together.
LOL_COMPARE_JS = """
(function () {
  var API = window.BM_LEAGUE_API;
  var I = window.BM_I18N_LEAGUE || {};
  var form = document.getElementById('lolCompareForm');
  var statusEl = document.getElementById('lolCompareStatus');
  var results = document.getElementById('lolCompareResults');
  if (!form || !API) return;

  function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }
  function tierLabel(tier) { return tier ? tier.charAt(0) + tier.slice(1).toLowerCase() : ''; }
  function setStatus(text, isError) {
    if (!text) { statusEl.hidden = true; statusEl.textContent = ''; return; }
    statusEl.hidden = false;
    statusEl.textContent = text;
    statusEl.dataset.error = isError ? 'true' : 'false';
  }
  async function fetchProfile(riotId, region) {
    var res = await fetch(API + '/profile?riotId=' + encodeURIComponent(riotId) + '&region=' + encodeURIComponent(region));
    var data = await res.json().catch(function () { return {}; });
    if (!res.ok) {
      var err = new Error((data && data.error) || ('HTTP ' + res.status));
      err.rateLimited = !!(data && data.rateLimited) || res.status === 429;
      err.retryAfter = data && data.retryAfter;
      throw err;
    }
    return data;
  }

  // Same shared back-off as the profile page (one localStorage key): a
  // comparison costs TWO profile lookups against the shared Riot dev-key
  // quota, so a short debounce after success and a long one after a 429.
  var submitBtn = form.querySelector('button[type="submit"]');
  var submitLabel = submitBtn ? submitBtn.textContent : '';
  var COOLDOWN_KEY = 'bmLolCooldownUntil';
  var cooldownTimer = null;
  function cooldownLeft() {
    var until = 0;
    try { until = Number(localStorage.getItem(COOLDOWN_KEY)) || 0; } catch (e) {}
    return Math.ceil((until - Date.now()) / 1000);
  }
  function tickCooldown() {
    clearTimeout(cooldownTimer);
    if (!submitBtn) return;
    var left = cooldownLeft();
    if (left > 0) {
      submitBtn.disabled = true;
      submitBtn.textContent = (I.cooldownLabel || 'Retry in {s}s').replace('{s}', left);
      cooldownTimer = setTimeout(tickCooldown, 1000);
    } else {
      submitBtn.disabled = false;
      submitBtn.textContent = submitLabel;
    }
  }
  function startCooldown(seconds) {
    try { localStorage.setItem(COOLDOWN_KEY, String(Date.now() + seconds * 1000)); } catch (e) {}
    tickCooldown();
  }
  tickCooldown();

  // Bklit charts (assets/js/bm-charts.js) load on demand, like on the profile page.
  var bmChartsState = 0;
  function bmAttr(payload) { return JSON.stringify(payload).replace(/&/g, '&amp;').replace(/"/g, '&quot;'); }
  function hydrateBmCharts() {
    if (!document.querySelector('[data-bm-chart]:not([data-bm-mounted])')) return;
    if (window.bmCharts && window.bmCharts.mountAll) { window.bmCharts.mountAll(); return; }
    if (bmChartsState) return;
    bmChartsState = 1;
    var sc = document.createElement('script');
    sc.src = (window.BM_ROOT || '/') + 'assets/js/bm-charts.js?v=__BM_CHARTS_V__';
    sc.async = true;
    document.head.appendChild(sc);
  }
  new MutationObserver(hydrateBmCharts).observe(document.body, { childList: true, subtree: true });

  function playerHeaderHtml(data) {
    var primary = data.ranks.solo || data.ranks.flex;
    var avatarHtml = data.profileIconId
      ? '<img class="league-icon-fallback" src="https://raw.communitydragon.org/latest/plugins/rcp-be-lol-game-data/global/default/v1/profile-icons/' + data.profileIconId + '.jpg" alt="">'
      : '';
    return '<div class="lol-compare-player-header">'
      + '<div class="player-avatar">' + avatarHtml + '</div>'
      + '<div><div class="player-name">' + esc(data.riotId) + '</div>'
      + '<div class="player-meta">' + esc(data.region) + '</div>'
      + (primary
        ? '<div class="rank-tier-name">' + tierLabel(primary.tier) + ' ' + primary.rank + ' <span class="mono">' + primary.leaguePoints + ' LP</span></div>'
        : '<div class="rank-tier-name" style="color:var(--text-faint)">' + esc(I.unranked) + '</div>') + '</div></div>';
  }

  function compareCard(label, a, b, unit, decimals, aName, bName) {
    var scale = Math.max(a, b) * 1.15 || 1;
    return '<div class="stats-compare-card"><div class="stats-compare-label">' + esc(label) + '</div>'
      + '<div class="stats-compare-row"><span class="stats-compare-name">' + esc(aName) + '</span><div class="stats-compare-track"><div class="stats-compare-fill you" style="width:' + Math.round((a / scale) * 100) + '%"></div></div><span class="stats-compare-value mono">' + a.toFixed(decimals) + unit + '</span></div>'
      + '<div class="stats-compare-row"><span class="stats-compare-name">' + esc(bName) + '</span><div class="stats-compare-track"><div class="stats-compare-fill rank" style="width:' + Math.round((b / scale) * 100) + '%"></div></div><span class="stats-compare-value mono">' + b.toFixed(decimals) + unit + '</span></div>'
      + '</div>';
  }

  // Left value | label | right value, the better side highlighted.
  function duelRow(label, aVal, bVal, aText, bText, lowerIsBetter) {
    var win = aVal === bVal ? 0 : ((lowerIsBetter ? aVal < bVal : aVal > bVal) ? 1 : 2);
    return '<div class="lol-compare-most-played">'
      + '<div class="' + (win === 1 ? 'lol-duel-win' : '') + '">' + aText + '</div>'
      + '<div class="stats-compare-label">' + esc(label) + '</div>'
      + '<div class="' + (win === 2 ? 'lol-duel-win' : '') + '">' + bText + '</div></div>';
  }
  function section(title, inner) {
    return '<div class="stats-section"><div class="stats-block-title">' + esc(title) + '</div>' + inner + '</div>';
  }

  function soloOrFlex(data) {
    return data.ranks.solo ? data.queues.solo : (data.ranks.flex ? data.queues.flex : data.queues.solo);
  }

  function renderCompare(dataA, dataB) {
    var nameA = dataA.riotId.split('#')[0], nameB = dataB.riotId.split('#')[0];
    var qa = soloOrFlex(dataA), qb = soloOrFlex(dataB);
    var wrA = qa.matches.length ? Math.round(qa.matches.filter(function (m) { return m.win; }).length / qa.matches.length * 100) : 0;
    var wrB = qb.matches.length ? Math.round(qb.matches.filter(function (m) { return m.win; }).length / qb.matches.length * 100) : 0;
    var topA = qa.champions[0], topB = qb.champions[0];

    var cardsHtml = (qa.matches.length && qb.matches.length) ? [
      compareCard(I.thWinrate, wrA, wrB, '%', 0, nameA, nameB),
      compareCard(I.csPerMin, qa.statsAvg.csPerMin, qb.statsAvg.csPerMin, '', 1, nameA, nameB),
      compareCard(I.goldPerMin, qa.statsAvg.goldPerMin, qb.statsAvg.goldPerMin, '', 0, nameA, nameB),
      compareCard(I.dmgPerMin, qa.statsAvg.dmgPerMin, qb.statsAvg.dmgPerMin, '', 0, nameA, nameB),
      compareCard(I.killParticipation, qa.statsAvg.killParticipation, qb.statsAvg.killParticipation, '%', 0, nameA, nameB),
    ].join('') : '<div class="matchup-empty">' + esc(I.notEnoughToCompare) + '</div>';

    var both = qa.matches.length && qb.matches.length;
    var sections = '';
    if (both) {
      // Radar: each axis normalised to the larger of the two players.
      var axes = [
        { key: 'cs', label: 'CS/min', a: qa.statsAvg.csPerMin, b: qb.statsAvg.csPerMin },
        { key: 'gold', label: '\\u00a0\\u00a0Gold/min', a: qa.statsAvg.goldPerMin, b: qb.statsAvg.goldPerMin },
        { key: 'dpm', label: 'DPM', a: qa.statsAvg.dmgPerMin, b: qb.statsAvg.dmgPerMin },
        { key: 'kp', label: 'KP', a: qa.statsAvg.killParticipation, b: qb.statsAvg.killParticipation }
      ];
      if (qa.vision && qb.vision) axes.push({ key: 'vision', label: 'Vision/min', a: qa.vision.scorePerMin, b: qb.vision.scorePerMin });
      var va = {}, vb = {};
      axes.forEach(function (ax) { var top = Math.max(ax.a, ax.b) || 1; va[ax.key] = Math.round((ax.a / top) * 100); vb[ax.key] = Math.round((ax.b / top) * 100); });
      sections += '<div class="stats-radar" data-bm-chart="' + bmAttr({
        type: 'radar', size: 320,
        metrics: axes.map(function (ax) { return { key: ax.key, label: ax.label }; }),
        radar: [{ label: nameA, color: 'var(--magenta)', values: va }, { label: nameB, color: 'var(--cream)', values: vb }]
      }) + '"></div>'
        + '<div class="lol-compare-legend"><span style="color:var(--magenta)">&#9632; ' + esc(nameA) + '</span><span style="color:var(--cream)">&#9632; ' + esc(nameB) + '</span></div>';

      if (qa.combat && qb.combat) {
        sections += section(I.combatTitle, '<div class="stats-compare-grid">'
          + compareCard(I.kpiDmgTaken, qa.combat.damageTakenPerMin, qb.combat.damageTakenPerMin, '', 0, nameA, nameB)
          + compareCard(I.kpiDead, qa.combat.deadPct, qb.combat.deadPct, '%', 1, nameA, nameB)
          + compareCard(I.kpiCc, qa.combat.ccTime, qb.combat.ccTime, ' s', 0, nameA, nameB) + '</div>');
      }
      if (qa.vision && qb.vision && qa.objectives && qb.objectives) {
        sections += section(I.visionTitle, '<div class="stats-compare-grid">'
          + compareCard(I.kpiVisionMin, qa.vision.scorePerMin, qb.vision.scorePerMin, '', 1, nameA, nameB)
          + compareCard(I.kpiControlWards, qa.vision.controlWards, qb.vision.controlWards, '', 1, nameA, nameB)
          + compareCard(I.kpiTurrets, qa.objectives.turrets, qb.objectives.turrets, '', 1, nameA, nameB)
          + compareCard(I.kpiDragons, qa.objectives.dragons, qb.objectives.dragons, '', 1, nameA, nameB) + '</div>');
      }
      if (qa.records && qb.records) {
        var ra = qa.records, rb = qb.records;
        var rows = '';
        if (ra.bestKda && rb.bestKda) rows += duelRow(I.kpiBestKda, ra.bestKda.kda, rb.bestKda.kda, ra.bestKda.kills + '/' + ra.bestKda.deaths + '/' + ra.bestKda.assists + ' <span class="mono">' + ra.bestKda.kda.toFixed(1) + '</span>', rb.bestKda.kills + '/' + rb.bestKda.deaths + '/' + rb.bestKda.assists + ' <span class="mono">' + rb.bestKda.kda.toFixed(1) + '</span>');
        if (ra.bestDpm && rb.bestDpm) rows += duelRow(I.kpiBestDpm, ra.bestDpm.dpm, rb.bestDpm.dpm, '<span class="mono">' + ra.bestDpm.dpm + '</span>', '<span class="mono">' + rb.bestDpm.dpm + '</span>');
        rows += duelRow(I.kpiSpree, ra.longestSpree, rb.longestSpree, '<span class="mono">' + ra.longestSpree + '</span>', '<span class="mono">' + rb.longestSpree + '</span>');
        rows += duelRow(I.kpiPentas, ra.pentas, rb.pentas, '<span class="mono">' + ra.pentas + '</span>', '<span class="mono">' + rb.pentas + '</span>');
        rows += duelRow(I.kpiSoloKills, ra.soloKills, rb.soloKills, '<span class="mono">' + ra.soloKills + '</span>', '<span class="mono">' + rb.soloKills + '</span>');
        if (qa.pings && qb.pings) rows += duelRow(I.pingsPerGame, qa.pings.perGame, qb.pings.perGame, '<span class="mono">' + qa.pings.perGame.toFixed(1) + '</span>', '<span class="mono">' + qb.pings.perGame.toFixed(1) + '</span>');
        sections += section(I.recordsTitle, '<div class="lol-duel-list">' + rows + '</div>');
      }
    }

    var mostPlayedHtml = '<div class="lol-compare-most-played">'
      + '<div>' + (topA ? esc(topA.champ) + ' <span class="mono">' + topA.kda.toFixed(1) + ' KDA</span>' : '') + '</div>'
      + '<div class="stats-compare-label">' + esc(I.mostPlayed) + '</div>'
      + '<div>' + (topB ? esc(topB.champ) + ' <span class="mono">' + topB.kda.toFixed(1) + ' KDA</span>' : '') + '</div>'
      + '</div>';

    results.innerHTML =
      '<div class="lol-compare-headers">' + playerHeaderHtml(dataA) + '<div class="lol-compare-form-vs">' + esc(I.compareVs || 'VS') + '</div>' + playerHeaderHtml(dataB) + '</div>'
      + mostPlayedHtml
      + '<div class="stats-compare-grid">' + cardsHtml + '</div>'
      + sections;
    results.querySelectorAll('.league-icon-fallback').forEach(function (img) {
      img.addEventListener('error', function () { img.style.visibility = 'hidden'; });
    });
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    if (cooldownLeft() > 0) return;
    var riotIdA = document.getElementById('lolCompareRiotIdA').value.trim();
    var riotIdB = document.getElementById('lolCompareRiotIdB').value.trim();
    var regionA = document.getElementById('lolCompareRegionA').value;
    var regionB = document.getElementById('lolCompareRegionB').value;
    if (!riotIdA || !riotIdB) return;
    setStatus(I.loading, false);
    var skelCards = '';
    for (var i = 0; i < 4; i++) skelCards += '<span class="skel" style="height:96px"></span>';
    results.innerHTML = '<div class="skel-stack" aria-hidden="true"><div class="skel-duo"><span class="skel" style="height:64px"></span><span class="skel" style="height:64px"></span></div>'
      + '<span class="skel skel-circle" style="width:200px;height:200px;margin:8px auto"></span><div class="stats-compare-grid">' + skelCards + '</div></div>';
    Promise.all([fetchProfile(riotIdA, regionA), fetchProfile(riotIdB, regionB)]).then(function (r) {
      setStatus(null);
      renderCompare(r[0], r[1]);
      startCooldown(20);
    }).catch(function (err) {
      results.innerHTML = '';
      setStatus(err.message || String(err), true);
      if (err && err.rateLimited) startCooldown(err.retryAfter || 75);
    });
  });
})();
"""

# Real Challenger/Grandmaster/Master ladder -- see lol-worker's
# handleLeaderboard for how it's computed/cached. This client script only
# renders whatever the worker returns (no fabricated rows): a null riotId
# (privacy-restricted account -- Riot allows opting out of the account-v1
# name lookup) shows I.anonymous instead of a name, never a guessed one.
LOL_LEADERBOARD_JS = """
(function () {
  var API = window.BM_LEAGUE_API;
  var I = window.BM_I18N_LOL_LB || {};
  var bar = document.getElementById('lolLbRegionBar');
  var statusEl = document.getElementById('lolLbStatus');
  var tableWrap = document.getElementById('lolLbTableWrap');
  var tbody = document.getElementById('lolLbTableBody');
  if (!bar || !API) return;
  var currentRegion = 'EUW';
  var cache = {};

  function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }

  function setStatus(text, isError) {
    if (!text) { statusEl.hidden = true; statusEl.textContent = ''; return; }
    statusEl.hidden = false;
    statusEl.textContent = text;
    statusEl.dataset.error = isError ? 'true' : 'false';
  }

  function rowHtml(e) {
    var name = e.riotId ? esc(e.riotId) : '<i>' + esc(I.anonymous) + '</i>';
    var href = e.riotId ? I.root + 'league/?riotId=' + encodeURIComponent(e.riotId) + '&region=' + currentRegion : null;
    var total = e.wins + e.losses;
    var wr = total ? Math.round((e.wins / total) * 100) : 0;
    return '<tr' + (href ? " onclick=\\"location.href='" + href + "'\\" style=\\"cursor:pointer\\"" : '') + '>'
      + '<td class="num"><span class="lb-rank" data-top="' + (e.rank <= 3) + '">#' + e.rank + '</span></td>'
      + '<td><span class="lb-player-cell"><span class="lb-riotid">' + name + '</span>'
      + (e.hotStreak ? '<span class="lb-hot" title="' + esc(I.hotStreakTitle) + '">\\ud83d\\udd25</span>' : '') + '</span></td>'
      + '<td><span class="lb-tier-tag" data-tier="' + e.tier + '">' + e.tier + '</span></td>'
      + '<td class="num mono">' + e.leaguePoints + ' LP</td>'
      + '<td class="num mono">' + e.wins + I.wins + ' ' + e.losses + I.losses + ' <span class="' + (wr >= 50 ? 'good' : 'warn') + '">(' + wr + '%)</span></td>'
      + '</tr>';
  }

  function render(entries) {
    tbody.innerHTML = entries.map(rowHtml).join('');
    tableWrap.hidden = false;
  }

  function skeletonRows() {
    var out = '';
    for (var i = 0; i < 12; i++) {
      out += '<tr class="skel-tr" aria-hidden="true"><td class="num"><span class="skel" style="width:26px;height:12px;margin-left:auto"></span></td>'
        + '<td><span class="skel" style="width:' + (110 + (i * 37) % 70) + 'px;height:12px"></span></td>'
        + '<td><span class="skel" style="width:44px;height:16px"></span></td>'
        + '<td class="num"><span class="skel" style="width:54px;height:12px;margin-left:auto"></span></td>'
        + '<td class="num"><span class="skel" style="width:80px;height:12px;margin-left:auto"></span></td></tr>';
    }
    return out;
  }

  function load(region) {
    currentRegion = region;
    setStatus(I.loading, false);
    tableWrap.hidden = true;
    if (cache[region]) { setStatus(null); render(cache[region]); return; }
    tbody.innerHTML = skeletonRows();
    tableWrap.hidden = false;
    fetch(API + '/leaderboard?region=' + region)
      .then(function (r) { return r.json().then(function (d) { return { ok: r.ok, data: d }; }); })
      .then(function (res) {
        if (!res.ok || res.data.error) throw new Error(res.data.error || 'error');
        cache[region] = res.data.entries;
        if (region !== currentRegion) return; // a newer region was picked while this one loaded
        setStatus(null);
        render(res.data.entries);
      })
      .catch(function () { if (region !== currentRegion) return; tbody.innerHTML = ''; tableWrap.hidden = true; setStatus(I.error, true); });
  }

  bar.addEventListener('click', function (e) {
    var btn = e.target.closest('[data-region]');
    if (!btn) return;
    [].forEach.call(bar.querySelectorAll('[data-region]'), function (b) { b.dataset.active = String(b === btn); });
    load(btn.dataset.region);
  });

  load(currentRegion);
})();
"""


TEAM_BUILDER_JS = """
(function () {
  var ROOT = window.BM_ROOT || '';
  var I = window.BM_BUILDER_I18N || {};
  var ROWS = 4, COLS = 7;

  var picker = document.getElementById('champPicker');
  var boardEl = document.getElementById('hexBoard');
  var traitPanel = document.getElementById('traitPanel');
  var searchInput = document.getElementById('builderSearch');
  var costFilters = document.getElementById('builderCostFilters');
  var emptyHint = document.getElementById('builderEmptyHint');
  var resetBtn = document.getElementById('builderReset');
  var shareBtn = document.getElementById('builderShare');
  var copyGameBtn = document.getElementById('builderCopyGame');
  var shareStatus = document.getElementById('builderShareStatus');
  var itemPicker = document.getElementById('itemPicker');
  var itemSearchInput = document.getElementById('builderItemSearch');
  if (!picker || !boardEl) return;

  var MAX_ITEMS_PER_UNIT = 3;
  var champions = [];
  var champBySlug = {};
  var traitDefs = [];
  var items = [];
  var itemBySlug = {};
  var plannerHeader = '02';
  var setMutator = '';
  // Each board cell is null (empty) or {slug, items: [itemSlug, ...]} (up
  // to MAX_ITEMS_PER_UNIT) -- items travel with a champion when it's moved
  // or swapped, same object reference, never resynthesized.
  var board = new Array(ROWS * COLS).fill(null);
  var activeCostFilter = 'ALL';
  var armedItemSlug = null, armedItemEl = null;

  function champImg(slug) {
    return ROOT + 'assets/champions/' + slug + '.png';
  }
  function traitImg(slug) {
    return ROOT + 'assets/traits/' + slug + '.png';
  }
  function itemImg(slug) {
    return ROOT + 'assets/items/' + slug + '.png';
  }
  function itemLabel(it) {
    return (I.lang === 'fr' && it.name_fr) ? it.name_fr : it.name;
  }

  // ---- Placement: two ways in, on purpose --------------------------------
  // 1) Drag and drop (mouse + touch via Pointer Events): pick up a champion
  //    from the picker, or an already-placed one straight off the board,
  //    and drop it on any hex cell. Dropping outside the board removes it.
  //    (No bench -- deliberate: it doesn't count toward traits in the real
  //    game either, so it added a UI section without adding anything a
  //    comp-building tool needs.)
  // 2) Tap-to-arm: a plain click/tap (no real movement) on a picker
  //    champion "arms" it instead -- a persistent border/glow, not a
  //    fleeting mid-drag one -- and the next tap on any cell places it
  //    there. Needed because a real drag's "currently held" highlight
  //    collapses to a few milliseconds for a plain click, invisible in
  //    practice; this is what actually answers "show me what I picked".
  var dragGhost = null, dragSlug = null, dragItems = [], dragOrigin = null, dragOverEl = null;
  var dragSourcePickerEl = null, dragStartX = 0, dragStartY = 0, dragMoved = false;
  var armedSlug = null, armedPickerEl = null;
  var TAP_THRESHOLD = 6; // px of movement below which a press counts as a tap, not a drag

  function setArmed(slug, pickerEl) {
    if (armedPickerEl) armedPickerEl.dataset.armed = 'false';
    armedSlug = slug;
    armedPickerEl = pickerEl || null;
    if (armedPickerEl) armedPickerEl.dataset.armed = 'true';
    if (slug) setArmedItem(null, null); // mutually exclusive with an armed item
  }
  function setArmedItem(slug, el) {
    if (armedItemEl) armedItemEl.dataset.armed = 'false';
    armedItemSlug = slug;
    armedItemEl = el || null;
    if (armedItemEl) armedItemEl.dataset.armed = 'true';
    if (slug) setArmed(null, null); // mutually exclusive with an armed champion
  }
  function clearDragSourceHighlight() {
    if (dragSourcePickerEl) { dragSourcePickerEl.dataset.dragging = 'false'; dragSourcePickerEl = null; }
  }

  function beginDrag(slug, origin, x, y, pickerEl, sourceItems) {
    dragSlug = slug;
    dragItems = sourceItems || [];
    dragOrigin = origin; // null if fresh from the picker, else the board index it came from
    dragStartX = x; dragStartY = y; dragMoved = false;
    dragSourcePickerEl = pickerEl || null;
    if (dragSourcePickerEl) dragSourcePickerEl.dataset.dragging = 'true';
    dragGhost = document.createElement('img');
    dragGhost.src = champImg(slug);
    dragGhost.className = 'builder-drag-ghost';
    document.body.appendChild(dragGhost);
    document.body.classList.add('builder-dragging');
    positionGhost(x, y);
  }
  function positionGhost(x, y) {
    if (dragGhost) { dragGhost.style.left = x + 'px'; dragGhost.style.top = y + 'px'; }
  }
  function cellUnder(x, y) {
    var el = document.elementFromPoint(x, y);
    if (!el) return null;
    var hex = el.closest('.hex-slot');
    if (hex) return { idx: parseInt(hex.dataset.idx, 10), el: hex };
    return null;
  }
  function placeArmedOn(idx) {
    board[idx] = { slug: armedSlug, items: [] };
    setArmed(null, null);
    renderCells();
    renderTraitPanel();
    syncUrl();
  }
  function attachArmedItemOn(idx) {
    var cellData = board[idx];
    if (!cellData) return; // items only attach to an already-placed champion, leave it armed
    if (cellData.items.length >= MAX_ITEMS_PER_UNIT) {
      showStatus(I.itemSlotsFull, true);
      return;
    }
    cellData.items.push(armedItemSlug);
    setArmedItem(null, null);
    renderCells();
    syncUrl();
  }
  function removeItemFrom(idx, itemSlug) {
    var cellData = board[idx];
    if (!cellData) return;
    var pos = cellData.items.indexOf(itemSlug);
    if (pos === -1) return;
    cellData.items.splice(pos, 1);
    renderCells();
    syncUrl();
  }
  document.addEventListener('pointermove', function (e) {
    if (!dragGhost) return;
    positionGhost(e.clientX, e.clientY);
    if (Math.abs(e.clientX - dragStartX) + Math.abs(e.clientY - dragStartY) > TAP_THRESHOLD) dragMoved = true;
    var hit = cellUnder(e.clientX, e.clientY);
    var el = hit ? hit.el : null;
    if (el !== dragOverEl) {
      if (dragOverEl) dragOverEl.dataset.dragover = 'false';
      if (el) el.dataset.dragover = 'true';
      dragOverEl = el;
    }
  });
  document.addEventListener('pointerup', function (e) {
    if (!dragGhost) return;
    document.body.removeChild(dragGhost);
    dragGhost = null;
    document.body.classList.remove('builder-dragging');
    if (dragOverEl) { dragOverEl.dataset.dragover = 'false'; dragOverEl = null; }

    if (!dragMoved && dragOrigin === null) {
      // A tap (not a drag) on a picker champion: arm it instead of
      // cancelling. Re-tapping the already-armed one toggles it off.
      // (Grab the source element BEFORE clearing it -- clearDragSourceHighlight()
      // nulls out dragSourcePickerEl as a side effect.)
      var tappedEl = dragSourcePickerEl;
      var wasThisOneArmed = armedPickerEl === tappedEl;
      clearDragSourceHighlight();
      setArmed(wasThisOneArmed ? null : dragSlug, wasThisOneArmed ? null : tappedEl);
      dragSlug = null; dragOrigin = null;
      return;
    }
    clearDragSourceHighlight();

    var hit = cellUnder(e.clientX, e.clientY);
    if (hit) {
      var displaced = board[hit.idx];
      board[hit.idx] = { slug: dragSlug, items: dragItems };
      if (dragOrigin !== null && displaced) {
        // swap instead of losing the champion that was already there
        board[dragOrigin] = displaced;
      }
    }
    // hit === null (dropped outside the board): already removed from its
    // origin below on pickup, so this is how a unit (and its items) gets discarded.
    renderCells();
    renderTraitPanel();
    syncUrl();
    dragSlug = null; dragItems = []; dragOrigin = null;
  });
  document.addEventListener('pointercancel', function () {
    if (!dragGhost) return;
    document.body.removeChild(dragGhost);
    dragGhost = null;
    document.body.classList.remove('builder-dragging');
    if (dragOverEl) { dragOverEl.dataset.dragover = 'false'; dragOverEl = null; }
    clearDragSourceHighlight();
    // Interrupted mid-drag (e.g. OS gesture) -- put it back where it came from.
    if (dragOrigin !== null) {
      board[dragOrigin] = { slug: dragSlug, items: dragItems };
      renderCells();
    }
    dragSlug = null; dragItems = []; dragOrigin = null;
  });

  // ---- Board DOM (built once; only its filled state changes) ----
  function wireCellDrag(cell) {
    cell.addEventListener('pointerdown', function (e) {
      var idx = parseInt(cell.dataset.idx, 10);
      // Tapping directly on an already-equipped item icon, with nothing
      // armed, removes just that item -- checked first so it never falls
      // through to "pick up the whole champion to move it".
      var iconHit = e.target.closest('.hex-item-icon');
      if (iconHit && !armedSlug && !armedItemSlug) {
        e.preventDefault();
        e.stopPropagation();
        removeItemFrom(idx, iconHit.dataset.itemSlug);
        return;
      }
      if (armedSlug) {
        e.preventDefault();
        placeArmedOn(idx);
        return;
      }
      if (armedItemSlug) {
        e.preventDefault();
        attachArmedItemOn(idx);
        return;
      }
      var cellData = board[idx];
      if (!cellData) return;
      e.preventDefault();
      board[idx] = null;
      renderCells();
      renderTraitPanel();
      beginDrag(cellData.slug, idx, e.clientX, e.clientY, null, cellData.items);
    });
  }
  function buildBoard() {
    boardEl.innerHTML = '';
    for (var r = 0; r < ROWS; r++) {
      var rowEl = document.createElement('div');
      rowEl.className = 'hex-row';
      if (r % 2 === 1) rowEl.dataset.offset = 'true';
      for (var c = 0; c < COLS; c++) {
        var idx = r * COLS + c;
        var cell = document.createElement('div');
        cell.className = 'hex-slot';
        cell.dataset.idx = String(idx);
        wireCellDrag(cell);
        rowEl.appendChild(cell);
      }
      boardEl.appendChild(rowEl);
    }
  }

  function renderCells() {
    var boardCells = boardEl.querySelectorAll('.hex-slot');
    board.forEach(function (cellData, i) { paintCell(boardCells[i], cellData); });
    if (emptyHint) emptyHint.hidden = board.some(Boolean);
  }
  function paintCell(el, cellData) {
    if (!el) return;
    var slug = cellData && cellData.slug;
    if (slug && champBySlug[slug]) {
      el.dataset.filled = 'true';
      var itemsHtml = (cellData.items || []).map(function (itSlug) {
        var it = itemBySlug[itSlug];
        var label = it ? itemLabel(it) : '';
        return '<img class="hex-item-icon" data-item-slug="' + itSlug + '" src="' + itemImg(itSlug) + '" alt="' + label + '" title="' + label + '" loading="lazy">';
      }).join('');
      el.innerHTML = '<div class="hex-cell"><img class="hex-champ-icon" src="' + champImg(slug) + '" alt="' + champBySlug[slug].name + '" loading="lazy"></div>' +
        (itemsHtml ? '<div class="hex-item-row">' + itemsHtml + '</div>' : '');
    } else {
      el.dataset.filled = 'false';
      el.innerHTML = '<div class="hex-cell"></div>';
    }
  }

  // ---- Champion picker ----
  function buildPicker() {
    picker.innerHTML = '';
    if (!champions.length) {
      picker.innerHTML = '<div class="champ-picker-empty"></div>';
      return;
    }
    champions.forEach(function (c) {
      var item = document.createElement('div');
      item.className = 'champ-picker-item';
      item.dataset.slug = c.slug;
      item.dataset.cost = String(c.cost || 1);
      item.dataset.name = c.name.toLowerCase();
      item.style.setProperty('--picker-cost-color', 'var(--cost-' + (c.cost || 1) + ')');
      item.title = c.name;
      item.innerHTML = '<img src="' + champImg(c.slug) + '" alt="' + c.name + '" loading="lazy">';
      item.addEventListener('pointerdown', function (e) {
        e.preventDefault();
        if (armedPickerEl && armedPickerEl !== item) setArmed(null, null);
        beginDrag(c.slug, null, e.clientX, e.clientY, item);
      });
      picker.appendChild(item);
    });
  }
  function applyPickerFilters() {
    var q = (searchInput && searchInput.value.trim().toLowerCase()) || '';
    picker.querySelectorAll('.champ-picker-item').forEach(function (el) {
      var costOk = activeCostFilter === 'ALL' || el.dataset.cost === activeCostFilter;
      var searchOk = !q || el.dataset.name.indexOf(q) !== -1;
      el.dataset.hidden = (costOk && searchOk) ? 'false' : 'true';
    });
  }
  if (searchInput) searchInput.addEventListener('input', applyPickerFilters);
  if (costFilters) {
    costFilters.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-cost-filter]');
      if (!btn) return;
      costFilters.querySelectorAll('[data-cost-filter]').forEach(function (b) { b.dataset.active = String(b === btn); });
      activeCostFilter = btn.dataset.costFilter;
      applyPickerFilters();
    });
  }

  // ---- Item picker: tap an item to arm it (same persistent-highlight
  // convention as an armed champion, see setArmed), then tap an
  // already-placed champion's hex to equip it there. Deliberately no
  // drag-and-drop for items -- they attach to an existing unit, not to a
  // hex coordinate, so "tap the target" reads clearer than dragging a small
  // icon onto an even smaller part of the board. ----
  function buildItemPicker() {
    if (!itemPicker) return;
    itemPicker.innerHTML = '';
    items.forEach(function (it) {
      var el = document.createElement('div');
      el.className = 'item-picker-item';
      el.dataset.slug = it.slug;
      el.dataset.name = it.name.toLowerCase();
      var label = itemLabel(it);
      el.title = label;
      el.innerHTML = '<img src="' + itemImg(it.slug) + '" alt="' + label + '" loading="lazy">';
      el.addEventListener('click', function () {
        var wasArmed = armedItemSlug === it.slug;
        setArmedItem(wasArmed ? null : it.slug, wasArmed ? null : el);
      });
      itemPicker.appendChild(el);
    });
  }
  if (itemSearchInput) {
    itemSearchInput.addEventListener('input', function () {
      var q = itemSearchInput.value.trim().toLowerCase();
      itemPicker.querySelectorAll('.item-picker-item').forEach(function (el) {
        el.dataset.hidden = (!q || el.dataset.name.indexOf(q) !== -1) ? 'false' : 'true';
      });
    });
  }

  // ---- Trait synergy panel (board only, matches real TFT rules) ----
  function renderTraitPanel() {
    if (!traitPanel) return;
    var counts = {};
    board.forEach(function (cellData) {
      var c = cellData && champBySlug[cellData.slug];
      if (!c) return;
      (c.traits || []).forEach(function (t) { counts[t] = (counts[t] || 0) + 1; });
    });
    var rows = [];
    traitDefs.forEach(function (t) {
      var count = counts[t.name] || 0;
      if (!count) return;
      var effects = t.effects; // ascending by min_units
      var activeIdx = -1;
      for (var i = 0; i < effects.length; i++) {
        if (count >= effects[i].min_units) activeIdx = i;
      }
      var next = effects[activeIdx + 1];
      rows.push({ t: t, count: count, activeIdx: activeIdx, nextMin: next ? next.min_units : null });
    });
    rows.sort(function (a, b) {
      if ((a.activeIdx >= 0) !== (b.activeIdx >= 0)) return (a.activeIdx >= 0) ? -1 : 1;
      return b.count - a.count;
    });
    if (!rows.length) {
      traitPanel.innerHTML = '<div class="champ-picker-empty">' + (I.noTraits || '') + '</div>';
      return;
    }
    traitPanel.innerHTML = rows.map(function (r) {
      var label = r.nextMin ? (r.count + '/' + r.nextMin) : String(r.count);
      var traitName = I.lang === 'fr' && r.t.name_fr ? r.t.name_fr : r.t.name;
      return '<div class="trait-row" data-active="' + (r.activeIdx >= 0) + '"' +
        (r.activeIdx >= 0 ? ' data-tier="' + r.activeIdx + '"' : '') + '>' +
        '<img src="' + traitImg(r.t.slug) + '" alt="' + traitName + '" loading="lazy">' +
        '<span class="trait-row-name">' + traitName + '</span>' +
        '<span class="trait-row-count">' + label + '</span></div>';
    }).join('');
  }

  // ---- Shareable URL state ----
  function syncUrl() {
    var b = [];
    board.forEach(function (cellData, i) {
      if (!cellData) return;
      // "." can't appear inside a slug (kebab-case: letters/digits/hyphens
      // only), so it's a safe separator for the item list appended after
      // the champion slug -- old share links with no items still parse
      // fine (rest.slice(1) is just empty).
      var entry = i + ':' + cellData.slug;
      if (cellData.items && cellData.items.length) entry += '.' + cellData.items.join('.');
      b.push(entry);
    });
    var qs = b.length ? ('b=' + b.join(',')) : '';
    history.replaceState(null, '', location.pathname + (qs ? '?' + qs : ''));
  }
  function loadFromUrl() {
    var params = new URLSearchParams(location.search);
    (params.get('b') || '').split(',').forEach(function (pair) {
      if (!pair) return;
      var m = pair.split(':');
      var idx = parseInt(m[0], 10);
      var rest = (m[1] || '').split('.');
      var slug = rest[0];
      var itemSlugs = rest.slice(1).filter(function (s) { return itemBySlug[s]; });
      if (slug && champBySlug[slug] && idx >= 0 && idx < board.length) {
        board[idx] = { slug: slug, items: itemSlugs.slice(0, MAX_ITEMS_PER_UNIT) };
      }
    });
  }

  async function copyToClipboard(text) {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return;
    }
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
  }
  function showStatus(text, isError) {
    if (!shareStatus) return;
    shareStatus.hidden = false;
    shareStatus.textContent = text || '';
    shareStatus.dataset.error = isError ? 'true' : 'false';
    setTimeout(function () { shareStatus.hidden = true; }, 2200);
  }

  if (resetBtn) {
    resetBtn.addEventListener('click', function () {
      board = new Array(ROWS * COLS).fill(null);
      setArmed(null, null);
      setArmedItem(null, null);
      renderCells();
      renderTraitPanel();
      history.replaceState(null, '', location.pathname);
    });
  }
  if (shareBtn) {
    shareBtn.addEventListener('click', function () {
      copyToClipboard(location.href).then(function () { showStatus(I.shareCopied, false); });
    });
  }
  if (copyGameBtn) {
    // Same encoding the real /compo/ pages' copy button uses (see
    // team_planner_code() in build_site.py): header + 10 slots of
    // 3-hex-digit per-champion codes (blank = "000") + the set mutator.
    // Board order (top-left to bottom-right by hex index) is as good an
    // order as any -- the game's planner doesn't care about slot order,
    // only which champions are in it.
    copyGameBtn.addEventListener('click', function () {
      var placed = board.filter(Boolean);
      if (!placed.length) { showStatus(I.copyGameEmpty, true); return; }
      // Items aren't part of this format at all -- the real in-game Team
      // Planner paste is champions only, confirmed against a live test
      // (see team_planner_code()'s docstring in build_site.py).
      var slots = placed.slice(0, 10).map(function (cellData) {
        var c = champBySlug[cellData.slug];
        return (c && c.planner_code) || '000';
      });
      while (slots.length < 10) slots.push('000');
      var code = plannerHeader + slots.join('') + setMutator;
      copyToClipboard(code).then(function () {
        showStatus(I.copyGameCopied, false);
        if (window.gtag) gtag('event', 'team_builder_copy', {champion_count: placed.length});
      });
    });
  }

  fetch(ROOT + 'assets/data/builder.json').then(function (r) { return r.json(); }).then(function (data) {
    champions = data.champions || [];
    traitDefs = data.traits || [];
    items = data.items || [];
    plannerHeader = data.plannerHeader || plannerHeader;
    setMutator = data.setMutator || '';
    champions.forEach(function (c) { champBySlug[c.slug] = c; });
    items.forEach(function (it) { itemBySlug[it.slug] = it; });
    buildPicker();
    buildItemPicker();
    buildBoard();
    loadFromUrl();
    renderCells();
    renderTraitPanel();
  }).catch(function () {});
})();
"""


def slugify(name: str) -> str:
    s = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
    return s or "x"


def initials(riot_id: str) -> str:
    """Same convention as the Artifact's initials() -- first two characters
    of the name part (before the #tag), uppercased. A no-op on CJK names,
    same as the Artifact's JS .toUpperCase() on those, so behavior matches."""
    name = (riot_id or "").split("#")[0].strip()
    return (name[:2] or "?").upper()


def player_url_slug(rank: int, riot_id: str) -> str:
    """Rank prefix guarantees uniqueness within a region even when the name
    slugifies to nothing (CJK names collapse to 'x' -- verified on real
    leaderboard data, e.g. dozens of Korean riotIds all slugify to 'x')."""
    name = (riot_id or "").split("#")[0].strip()
    return f"{rank}-{slugify(name)}"


def load(name: str) -> dict:
    return json.loads((OUT / name).read_text(encoding="utf-8"))


def pct(x: float) -> str:
    return f"{round((x or 0) * 100)}%"


def is_complete_item(name: str) -> bool:
    return not name.startswith("Component_")


def is_emblem(name: str) -> bool:
    return "Emblem" in name


def filter_quality(raw_comps: list[dict]) -> list[dict]:
    """Same quality bar the Artifact's export applies to every slice
    (combined, per-region, per-rank) -- keeps only comps with a real tier
    and enough of a real sample to trust."""
    return [
        c for c in raw_comps
        if c.get("tier") != "?"
        and c.get("play_count", 0) >= MIN_PLAY_COUNT
        and c.get("avg_placement", 99) <= MAX_AVG_PLACEMENT
        and len(c.get("core_units") or []) >= MIN_CORE_BOARD_SIZE
        and not all(u.get("cost") == 5 for u in (c.get("core_units") or []))
    ]


def load_comp_archive() -> dict:
    if not COMP_ARCHIVE_PATH.exists():
        return {}
    return json.loads(COMP_ARCHIVE_PATH.read_text(encoding="utf-8"))


def save_comp_archive(archive: dict) -> None:
    COMP_ARCHIVE_PATH.write_text(json.dumps(archive, ensure_ascii=False, indent=1, sort_keys=True), encoding="utf-8")


def build_hors_meta_comps(comps_filtered: list[dict]) -> tuple[list[dict], dict]:
    """"Hors Meta" archive: a comp that qualified for a real /compo/ page in
    a past refresh but doesn't clear filter_quality() this time isn't
    necessarily dead -- a Riot dev API key's 24h TTL means every refresh
    re-samples a bounded slice of matches (never the full history in one
    go), so a real, previously-strong comp can legitimately miss
    MIN_PLAY_COUNT purely on sample luck, not because it stopped working.
    Silently dropping its page would 404 an already-published, possibly
    Google-indexed URL over nothing but that variance.

    data/comp_archive.json (git-tracked, unlike data/output/*.json which is
    gitignored and fully overwritten every refresh) is the persistent memory
    across refreshes: every comp that qualifies gets its full record
    refreshed here every time, so the archive always holds each comp's own
    latest-known-good snapshot. Anything in the archive for the CURRENT set
    that doesn't qualify this run becomes a "Hors Meta" comp -- same full
    record, tier overwritten to "HM", carrying its last real tier/date
    alongside so comp.html can be honest about it being archived instead of
    live. Gated on SET_LABEL so a set rotation doesn't resurrect Set 17
    comps forever; TFT sets share no champions/traits/items, so an old
    comp's board wouldn't even render sensibly under a new set's assets.

    Returns (hors_meta_comps, updated_archive) -- the caller renders the
    comps then writes the archive back with save_comp_archive() once the
    build actually succeeds, not before."""
    archive = load_comp_archive()
    today = datetime.now(timezone.utc).date().isoformat()
    live_keys = {c["key"] for c in comps_filtered}

    for c in comps_filtered:
        archive[c["key"]] = {**c, "_set": SET_LABEL, "_last_seen": today}

    hors_meta = []
    for key, entry in archive.items():
        if key in live_keys or entry.get("_set") != SET_LABEL:
            continue
        hm = {**entry, "tier": "HM", "last_known_tier": entry.get("tier"), "is_hors_meta": True}
        hors_meta.append(hm)
    return hors_meta, archive


RANK_WORD = {
    "fr": {"IRON": "Fer", "BRONZE": "Bronze", "SILVER": "Argent", "GOLD": "Or", "PLATINUM": "Platine",
           "EMERALD": "Émeraude", "DIAMOND": "Diamant", "MASTER": "Maître", "GRANDMASTER": "Grand Maître",
           "CHALLENGER": "Challenger"},
    "en": {"IRON": "Iron", "BRONZE": "Bronze", "SILVER": "Silver", "GOLD": "Gold", "PLATINUM": "Platinum",
           "EMERALD": "Emerald", "DIAMOND": "Diamond", "MASTER": "Master", "GRANDMASTER": "Grandmaster",
           "CHALLENGER": "Challenger"},
}


def rank_bracket_label(key: str, lang: str = "fr") -> str:
    """Turns a rank-bracket key (whatever config.RANK_BRACKETS currently
    produces -- broad merged buckets like "IRON_SILVER" today, or individual
    tiers like "PLATINUM" if the pipeline is re-run with the newer 8-bucket
    config) into a readable label, without hardcoding which shape is
    current."""
    if key == "MASTER_PLUS":
        return "Maître+" if lang == "fr" else "Master+"
    words = [RANK_WORD[lang].get(p, p.title()) for p in key.split("_")]
    return "-".join(words)


REGION_SHORT = {"EUW": "EUW", "NA": "NA", "BR": "BR", "KR": "KR"}


REGION_COLOR_VAR = {"EUW": "var(--magenta)", "NA": "var(--cyan)", "BR": "var(--gold)", "KR": "var(--teal)"}
MONTHS = {
    "fr": ["janv.", "févr.", "mars", "avr.", "mai", "juin", "juil.", "août", "sept.", "oct.", "nov.", "déc."],
    "en": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
}


def short_date(iso: str, lang: str = "fr") -> str:
    y, m, d = iso.split("-")
    return f"{d} {MONTHS[lang][int(m) - 1]}" if lang == "fr" else f"{MONTHS[lang][int(m) - 1]} {d}"


def build_elo_chart_svg(snapshots: list[dict], regions: list[str], lang: str = "fr") -> str:
    """Ports the Artifact's eloChartSVG()/renderEloChart(): a real avg-LP-
    over-time line per region, from leaderboard_history.json snapshots --
    grows one point every time the leaderboard gets refreshed, never
    interpolated or faked."""
    W, H, padL, padR, padT, padB = 760, 300, 46, 18, 18, 34
    plot_w, plot_h = W - padL - padR, H - padT - padB
    n = len(snapshots)
    if not snapshots or not regions:
        return f'<div class="empty-state">{translate(lang, "no_leaderboard_chart")}</div>'

    all_values = [s["avgLp"][r] for s in snapshots for r in regions if s.get("avgLp", {}).get(r) is not None]
    if not all_values:
        return f'<div class="empty-state">{translate(lang, "no_lp_data")}</div>'
    y_min, y_max = min(all_values), max(all_values)
    if y_min == y_max:
        y_min -= 10
        y_max += 10
    y_pad = (y_max - y_min) * 0.12
    y_min, y_max = max(0, y_min - y_pad), y_max + y_pad

    def x_for(i: int) -> float:
        return padL + plot_w / 2 if n == 1 else padL + (plot_w * i) / (n - 1)

    def y_for(v: float) -> float:
        return padT + plot_h - ((v - y_min) / (y_max - y_min)) * plot_h

    grid = []
    GRID_STEPS = 4
    for g in range(GRID_STEPS + 1):
        v = y_min + (y_max - y_min) * g / GRID_STEPS
        y = y_for(v)
        grid.append(f'<line x1="{padL}" y1="{y:.1f}" x2="{W - padR}" y2="{y:.1f}" stroke="var(--border)" stroke-width="1" />')
        grid.append(f'<text x="{padL - 8}" y="{y + 3:.1f}" text-anchor="end" font-size="10">{round(v)}</text>')

    x_labels = []
    step = -(-n // 6)  # ceil(n/6)
    for i, s in enumerate(snapshots):
        if n > 1 and i % step != 0 and i != n - 1:
            continue
        x_labels.append(f'<text x="{x_for(i):.1f}" y="{H - padB + 18}" text-anchor="middle" font-size="10">{short_date(s["date"], lang)}</text>')

    defs = []
    lines = []
    for r_idx, region in enumerate(regions):
        pts = [(i, s["avgLp"][region]) for i, s in enumerate(snapshots) if s.get("avgLp", {}).get(region) is not None]
        if not pts:
            continue
        color = REGION_COLOR_VAR[region]
        if len(pts) == 1:
            i, v = pts[0]
            lines.append(f'<circle class="ws-pulse" cx="{x_for(i):.1f}" cy="{y_for(v):.1f}" r="5" fill="none" stroke="{color}" stroke-width="1.5" style="--d:{r_idx * 0.15:.2f}s" />')
            lines.append(f'<circle class="ws-dot" cx="{x_for(i):.1f}" cy="{y_for(v):.1f}" r="5" fill="{color}" stroke="var(--bg)" stroke-width="2" style="--d:{r_idx * 0.15:.2f}s"><title>{region} · {round(v)} LP · {short_date(snapshots[i]["date"], lang)}</title></circle>')
        else:
            d = " ".join(f'{"M" if idx == 0 else "L"}{x_for(i):.1f},{y_for(v):.1f}' for idx, (i, v) in enumerate(pts))
            base_y = padT + plot_h
            area_d = f'{d} L{x_for(pts[-1][0]):.1f},{base_y:.1f} L{x_for(pts[0][0]):.1f},{base_y:.1f} Z'
            defs.append(f'<linearGradient id="wsg-{region}" x1="0" y1="0" x2="0" y2="1">'
                        f'<stop offset="0" stop-color="{color}" stop-opacity="0.30" /><stop offset="1" stop-color="{color}" stop-opacity="0" /></linearGradient>')
            delay = f'--d:{r_idx * 0.15:.2f}s'
            lines.append(f'<path class="ws-area" d="{area_d}" fill="url(#wsg-{region})" style="{delay}" />')
            lines.append(f'<path class="ws-line" pathLength="1" d="{d}" fill="none" stroke="{color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="{delay}" />')
            for i, v in pts:
                lines.append(f'<circle class="ws-dot" cx="{x_for(i):.1f}" cy="{y_for(v):.1f}" r="3.5" fill="{color}" style="{delay}"><title>{region} · {round(v)} LP · {short_date(snapshots[i]["date"], lang)}</title></circle>')

    return (f'<svg class="ws-chart-svg" viewBox="0 0 {W} {H}" xmlns="http://www.w3.org/2000/svg" role="img">'
            f'<defs>{"".join(defs)}</defs>'
            + "".join(grid) + "".join(x_labels) + "".join(lines) + "</svg>")


def build_area_chart_payload(snapshots: list[dict], regions: list[str]) -> dict | None:
    """Data for the Bklit AreaChart island (charts-ui/, mounted by
    assets/js/bm-charts.js) -- same avg-LP snapshots as build_elo_chart_svg,
    which stays in the page as the no-JS / single-point fallback. Only
    snapshots where every plotted region has a value are kept, so a series
    never has to be interpolated. None below 2 usable points."""
    rows = []
    for s in snapshots:
        avg = s.get("avgLp", {})
        if regions and all(avg.get(r) is not None for r in regions):
            rows.append({"date": s["date"], **{r: avg[r] for r in regions}})
    if len(rows) < 2:
        return None
    return {"series": [{"key": r, "label": REGION_SHORT.get(r, r), "color": REGION_COLOR_VAR[r]} for r in regions],
            "data": rows}


def build_comp_sparkline(history: list[dict]) -> dict | None:
    """A tiny inline trend chart for a comp's own /compo/<slug>/ page: avg
    placement across the same comp_history.json snapshots that already back
    /tendances/ and each row's up/down trend badge (see trend_for() above).
    A 2-point history reduces to exactly what the badge's single delta
    already shows, so this only adds anything from 3 points on. Returns
    None below that -- the caller skips rendering rather than showing a
    flat two-dot line that looks like a chart but isn't one.

    Lower avgPlacement is better, and SVG y grows downward, so mapping the
    value straight to y (no inversion) already draws "improving" as an
    upward-sloping line -- the intuitive reading for a stat where down is
    actually good needs no special-casing here."""
    if len(history) < 3:
        return None
    values = [h["avgPlacement"] for h in history]
    W, H, pad = 200, 48, 4
    y_min, y_max = min(values), max(values)
    if y_min == y_max:
        y_min, y_max = y_min - 0.5, y_max + 0.5
    y_pad = (y_max - y_min) * 0.15
    y_min, y_max = y_min - y_pad, y_max + y_pad
    n = len(values)

    def x_for(i: int) -> float:
        return pad + (W - 2 * pad) * i / (n - 1)

    def y_for(v: float) -> float:
        return pad + (H - 2 * pad) * (v - y_min) / (y_max - y_min)

    pts = [(x_for(i), y_for(v)) for i, v in enumerate(values)]
    line_d = " ".join(f'{"M" if i == 0 else "L"}{x:.1f},{y:.1f}' for i, (x, y) in enumerate(pts))
    area_d = f'{line_d} L{pts[-1][0]:.1f},{H - pad} L{pts[0][0]:.1f},{H - pad} Z'
    last_x, last_y = pts[-1]

    delta = values[0] - values[-1]  # positive = placement improved (dropped) over the window
    direction = "stable" if abs(delta) < 0.3 else ("up" if delta > 0 else "down")

    svg = (f'<svg class="sparkline-svg" viewBox="0 0 {W} {H}" xmlns="http://www.w3.org/2000/svg">'
           f'<path class="sparkline-area" d="{area_d}" />'
           f'<path class="sparkline-line" pathLength="1" d="{line_d}" />'
           f'<circle class="sparkline-dot" cx="{last_x:.1f}" cy="{last_y:.1f}" r="3.5" />'
           f'</svg>')
    return {"svg": svg, "direction": direction}


