def translate(lang: str, key: str, *args):
    entry = I18N.get(lang, I18N["fr"]).get(key, key)
    return entry(*args) if callable(entry) else entry


def playstyle_cat(tag: str | None) -> str:
    return (tag or "").split(" ")[0]


def units_worth_itemizing(units: list[dict], carry: str | None) -> set[str]:
    """Mirrors the Artifact's unitsWorthItemizing(): the carry always, plus
    the 2 non-carry units holding the most complete items."""
    with_items = [
        (u["champion"], [i for i in (u.get("items") or []) if is_complete_item(i)])
        for u in units if u["champion"] != carry
    ]
    with_items = [(c, i) for c, i in with_items if i]
    with_items.sort(key=lambda x: -len(x[1]))
    top_n = 2 if carry else 3
    top = {c for c, _ in with_items[:top_n]}
    if carry and any(u["champion"] == carry for u in units):
        top.add(carry)
    return top


class ImageCache:
    """Downloads champion/item images to real files once, dedup by slug."""

    def __init__(self, dist: Path):
        self.champ_dir = dist / "assets" / "champions"
        self.item_dir = dist / "assets" / "items"
        self.trait_dir = dist / "assets" / "traits"
        self.augment_dir = dist / "assets" / "augments"
        self.champ_dir.mkdir(parents=True, exist_ok=True)
        self.item_dir.mkdir(parents=True, exist_ok=True)
        self.trait_dir.mkdir(parents=True, exist_ok=True)
        self.augment_dir.mkdir(parents=True, exist_ok=True)
        self._done: set[str] = set()

    def _fetch(self, url: str, dest: Path) -> None:
        key = str(dest)
        if key in self._done or dest.exists():
            self._done.add(key)
            return
        resp = requests.get(url, timeout=30)
        resp.raise_for_status()
        dest.write_bytes(resp.content)
        self._done.add(key)

    def champion(self, slug: str, url: str) -> None:
        self._fetch(url, self.champ_dir / f"{slug}.png")

    def item(self, slug: str, url: str) -> None:
        self._fetch(url, self.item_dir / f"{slug}.png")

    def trait(self, slug: str, url: str) -> None:
        self._fetch(url, self.trait_dir / f"{slug}.png")

    def augment(self, slug: str, url: str) -> None:
        self._fetch(url, self.augment_dir / f"{slug}.png")


# ---------- League of Legends glossary (objets + champions) --------------
# Unlike the TFT glossary above (built from this project's own run.py
# collection, data/output/*.json), League has no equivalent large-scale
# match-collection pipeline yet -- lol-worker only ever sees the matches of
# whoever looks their own profile up (see league_profile.html). So this
# glossary is Riot's own reference data (Data Dragon), not an analytics
# product: real items (cost/stats/recipe) and real champions (lore, class,
# base stats), but no aggregate pick rate / win rate by role -- that would
# need a TFT-style collection built for League too, which doesn't exist
# yet (see lol_champ_roles_pending in I18N). Nothing here is invented to
# fill that gap.
#
# Images are hotlinked straight to Data Dragon's CDN (same as
# league_profile's live JS) rather than downloaded into assets/ like the
# TFT ImageCache above -- keeps this consistent with how the rest of the
# League side already sources its art, and avoids doubling the already
# sizeable dist/ with ~450 more images that Riot already serves reliably.
LOL_CLASS_LABEL = {
    "fr": {"Fighter": "Combattant", "Mage": "Mage", "Assassin": "Assassin", "Tank": "Tank", "Support": "Support", "Marksman": "Tireur"},
    "en": {"Fighter": "Fighter", "Mage": "Mage", "Assassin": "Assassin", "Tank": "Tank", "Support": "Support", "Marksman": "Marksman"},
}


def fetch_ddragon_version() -> str:
    resp = requests.get("https://ddragon.leagueoflegends.com/api/versions.json", timeout=30)
    resp.raise_for_status()
    return resp.json()[0]


def fetch_lol_champion_full(ddragon_version: str, champ_id: str, locale: str) -> dict:
    url = f"https://ddragon.leagueoflegends.com/cdn/{ddragon_version}/data/{locale}/champion/{champ_id}.json"
    resp = requests.get(url, timeout=30)
    resp.raise_for_status()
    return resp.json()["data"][champ_id]


def fetch_lol_glossary_data(ddragon_version: str) -> tuple[list[dict], dict[str, dict], list[dict], list[dict], list[dict]]:
    """Returns (items, items_lookup, champions, rune_trees, summoner_spells)
    -- see module comment above. items_lookup covers EVERY item Data Dragon
    knows (including ones filtered out of the public `items` list below) so
    a component/upgrade reference in a recipe can always show a real
    name+icon, linking to its own page only when that item passed the
    filter."""

    def fetch(locale: str, kind: str) -> dict:
        url = f"https://ddragon.leagueoflegends.com/cdn/{ddragon_version}/data/{locale}/{kind}.json"
        resp = requests.get(url, timeout=30)
        resp.raise_for_status()
        return resp.json()["data"]

    items_fr, items_en = fetch("fr_FR", "item"), fetch("en_US", "item")
    champs_fr, champs_en = fetch("fr_FR", "champion"), fetch("en_US", "champion")

    # Full per-champion files (lore, passive, 4 spells) -- the summary
    # champion.json above only has the short "blurb", not the actual
    # abilities. ~350 small CDN requests (173 champions x 2 locales);
    # parallelized since Data Dragon is a plain CDN, not a rate-limited
    # Riot API like the live worker -- no throttling concern here.
    champ_ids = list(champs_en.keys())
    print(f"  Fetching full champion data (lore + abilities) for {len(champ_ids)} champions x 2 locales...")
    with ThreadPoolExecutor(max_workers=16) as pool:
        full_fr = dict(zip(champ_ids, pool.map(lambda cid: fetch_lol_champion_full(ddragon_version, cid, "fr_FR"), champ_ids)))
        full_en = dict(zip(champ_ids, pool.map(lambda cid: fetch_lol_champion_full(ddragon_version, cid, "en_US"), champ_ids)))

    def fetch_list(locale: str, kind: str) -> list:
        # runesReforged.json is a bare top-level array, unlike item/champion/
        # summoner.json which wrap their entries in a top-level "data" object.
        url = f"https://ddragon.leagueoflegends.com/cdn/{ddragon_version}/data/{locale}/{kind}.json"
        resp = requests.get(url, timeout=30)
        resp.raise_for_status()
        return resp.json()

    runes_fr, runes_en = fetch_list("fr_FR", "runesReforged"), fetch_list("en_US", "runesReforged")
    summ_fr, summ_en = fetch("fr_FR", "summoner"), fetch("en_US", "summoner")

    items_lookup: dict[str, dict] = {}
    for item_id, en in items_en.items():
        fr = items_fr.get(item_id, {})
        items_lookup[item_id] = {
            "id": item_id, "slug": item_id, "icon_file": en["image"]["full"],
            "name_fr": fr.get("name") or en.get("name"), "name_en": en.get("name"),
        }

    items = []
    for item_id, en in items_en.items():
        gold = en.get("gold") or {}
        maps = en.get("maps") or {}
        # Only real Summoner's Rift, purchasable items -- Data Dragon's
        # item.json also carries ARAM/Arena-only, tutorial and deprecated
        # entries that would just clutter a Faille de l'invocateur glossary.
        if not gold.get("purchasable") or not maps.get("11"):
            continue
        fr = items_fr.get(item_id, {})
        items.append({
            "id": item_id, "slug": item_id, "icon_file": en["image"]["full"],
            "name_fr": fr.get("name") or en.get("name"), "name_en": en.get("name"),
            "plaintext_fr": fr.get("plaintext") or "", "plaintext_en": en.get("plaintext") or "",
            "desc_fr": fr.get("description") or "", "desc_en": en.get("description") or "",
            "gold": gold, "stats": en.get("stats") or {},
            "from_ids": en.get("from") or [], "into_ids": en.get("into") or [],
        })
        items_lookup[item_id]["has_page"] = True
    for entry in items_lookup.values():
        entry.setdefault("has_page", False)
    items.sort(key=lambda it: (-(it["gold"].get("total") or 0), it["name_en"]))

    def ability_view(spell: dict, resource_name: str) -> dict:
        # costType is a literal, un-substituted "{{ abilityresourcename }}"
        # template placeholder for most champions (Data Dragon leaves it to
        # the client to fill in) -- swap it for the champion's own real
        # resource name (partype) we already have, e.g. "Mana"/"Energie"/
        # "Fureur", so the page never shows raw template syntax.
        cost_type = (spell.get("costType") or "").strip()
        if "{{" in cost_type:
            cost_type = resource_name
        return {
            "name": spell.get("name") or "", "desc": spell.get("description") or "",
            "icon_file": spell["image"]["full"], "cooldown": spell.get("cooldownBurn") or "",
            "cost": spell.get("costBurn") or "", "cost_type": cost_type,
            "range": spell.get("rangeBurn") or "",
        }

    champions = []
    for champ_id, en in champs_en.items():
        fr = champs_fr.get(champ_id, {})
        full_fr_c, full_en_c = full_fr[champ_id], full_en[champ_id]
        champions.append({
            "id": champ_id, "slug": champ_id.lower(), "icon_file": en["image"]["full"],
            "name_fr": fr.get("name") or en.get("name"), "name_en": en.get("name"),
            "title_fr": fr.get("title") or "", "title_en": en.get("title") or "",
            "blurb_fr": fr.get("blurb") or "", "blurb_en": en.get("blurb") or "",
            "lore_fr": full_fr_c.get("lore") or fr.get("blurb") or "", "lore_en": full_en_c.get("lore") or en.get("blurb") or "",
            "partype_fr": fr.get("partype") or "", "partype_en": en.get("partype") or "",
            "tags": en.get("tags") or [], "info": en.get("info") or {}, "stats": en.get("stats") or {},
            "passive_fr": {"name": full_fr_c["passive"]["name"], "desc": full_fr_c["passive"]["description"], "icon_file": full_fr_c["passive"]["image"]["full"]},
            "passive_en": {"name": full_en_c["passive"]["name"], "desc": full_en_c["passive"]["description"], "icon_file": full_en_c["passive"]["image"]["full"]},
            "spells_fr": [ability_view(s, fr.get("partype") or "") for s in full_fr_c["spells"]],
            "spells_en": [ability_view(s, en.get("partype") or "") for s in full_en_c["spells"]],
        })
    champions.sort(key=lambda c: c["name_en"])

    def rune_tree_view(trees: list) -> list:
        return [{
            "id": t["id"], "name": t["name"], "icon_file": t["icon"],
            "slots": [[{"id": r["id"], "name": r["name"], "icon_file": r["icon"], "short_desc": r["shortDesc"]}
                       for r in slot["runes"]] for slot in t["slots"]],
        } for t in trees]

    rune_trees = []
    for tree_fr, tree_en in zip(rune_tree_view(runes_fr), rune_tree_view(runes_en)):
        rune_trees.append({
            "id": tree_en["id"], "icon_file": tree_en["icon_file"],
            "name_fr": tree_fr["name"], "name_en": tree_en["name"],
            "slots": [
                [{"id": r_en["id"], "icon_file": r_en["icon_file"],
                  "name_fr": r_fr["name"], "name_en": r_en["name"],
                  "short_desc_fr": r_fr["short_desc"], "short_desc_en": r_en["short_desc"]}
                 for r_fr, r_en in zip(slot_fr, slot_en)]
                for slot_fr, slot_en in zip(tree_fr["slots"], tree_en["slots"])
            ],
        })

    summoner_spells = []
    for sid, en in summ_en.items():
        if "CLASSIC" not in (en.get("modes") or []):
            continue  # Summoner's Rift only -- skip ARAM/URF/Arena-exclusive spells
        fr = summ_fr.get(sid, {})
        summoner_spells.append({
            "id": sid, "icon_file": en["image"]["full"],
            "name_fr": fr.get("name") or en.get("name"), "name_en": en.get("name"),
            "desc_fr": fr.get("description") or "", "desc_en": en.get("description") or "",
            "cooldown_fr": fr.get("cooldownBurn") or "", "cooldown_en": en.get("cooldownBurn") or "",
        })
    summoner_spells.sort(key=lambda s: s["name_en"])

    return items, items_lookup, champions, rune_trees, summoner_spells


def localize_lol_item(it: dict, lang: str) -> dict:
    return {
        "id": it["id"], "slug": it["slug"], "icon_file": it["icon_file"],
        "name": it["name_fr"] if lang == "fr" else it["name_en"],
        "plaintext": it["plaintext_fr"] if lang == "fr" else it["plaintext_en"],
        "gold": it["gold"],
    }


def lol_item_detail_view(it: dict, lang: str, lookup: dict[str, dict]) -> dict:
    def resolve(ids: list[str]) -> list[dict]:
        out = []
        for cid in ids:
            ref = lookup.get(cid)
            if not ref:
                continue
            out.append({"id": cid, "slug": ref["slug"], "icon_file": ref["icon_file"], "has_page": ref["has_page"],
                        "name": ref["name_fr"] if lang == "fr" else ref["name_en"]})
        return out

    base = localize_lol_item(it, lang)
    base.update({
        "desc": it["desc_fr"] if lang == "fr" else it["desc_en"],
        "stats": it["stats"],
        "from": resolve(it["from_ids"]),
        "into": resolve(it["into_ids"]),
    })
    return base


def localize_lol_champion(c: dict, lang: str) -> dict:
    class_labels = LOL_CLASS_LABEL["fr" if lang == "fr" else "en"]
    return {"id": c["id"], "slug": c["slug"], "icon_file": c["icon_file"],
            "name": c["name_fr"] if lang == "fr" else c["name_en"],
            "classes": [class_labels.get(tag, tag) for tag in c["tags"]], "raw_classes": c["tags"]}


def lol_champion_detail_view(c: dict, lang: str, role_stats_by_champion: dict,
                              items_by_champion: dict, items_lookup: dict[str, dict],
                              matchups_by_role: dict, champ_by_id: dict[str, dict],
                              runes_by_champion: dict, rune_by_id: dict[int, dict], tree_by_id: dict[int, dict]) -> dict:
    base = localize_lol_champion(c, lang)
    class_labels = LOL_CLASS_LABEL["fr" if lang == "fr" else "en"]
    # Real pick rate / win rate by role -- see lol_run.py. Keyed by the
    # same ddragon champion id used everywhere else (c["id"], e.g. "Ahri",
    # "MonkeyKing"), sorted by games desc so the champion's real primary
    # role (by how often it's actually played, not a guess) leads. Empty
    # until that pipeline has been run at least once, or for a champion/
    # role combo that hasn't cleared MIN_SAMPLE_PER_ROLE yet -- the
    # template falls back to the honest "en développement" badge either way.
    role_label = {"top": "Top", "jungle": "Jungle", "mid": "Mid", "adc": "ADC", "support": "Support"}
    champ_roles = (role_stats_by_champion.get(c["id"]) or {}).get("roles", {})
    role_stats = sorted(
        [{"role": role, "role_label": role_label.get(role, role), **data} for role, data in champ_roles.items()],
        key=lambda r: -r["games"],
    )

    # Real most-built items -- see lol_run.py --items-out (same collection
    # run as role_stats above). item_id is an int in the pipeline output but
    # items_lookup is keyed by Data Dragon's string ids.
    best_items = []
    for row in (items_by_champion.get(c["id"]) or []):
        ref = items_lookup.get(str(row["item_id"]))
        if not ref:
            continue
        best_items.append({
            "icon_file": ref["icon_file"], "slug": ref["slug"], "has_page": ref["has_page"],
            "name": ref["name_fr"] if lang == "fr" else ref["name_en"],
            "games": row["games"], "win_rate": row["win_rate"], "pick_rate": row["pick_rate"],
        })

    # Real lane matchups -- see lol_run.py --matchups-out. A matchup is
    # inherently role-specific (top Darius vs Garen isn't a jungle pairing),
    # so this only ever draws from the roles already surfaced in role_stats.
    matchups = []
    for r in role_stats:
        enemies = []
        for row in (matchups_by_role.get(r["role"], {}).get(c["id"]) or []):
            enemy = champ_by_id.get(row["enemy"])
            if not enemy:
                continue
            enemies.append({
                "slug": enemy["slug"], "icon_file": enemy["icon_file"],
                "name": enemy["name_fr"] if lang == "fr" else enemy["name_en"],
                "games": row["games"], "win_rate": row["win_rate"],
            })
        if enemies:
            matchups.append({"role": r["role"], "role_label": r["role_label"], "enemies": enemies})

    # A short teaser for the main champion page (avoids duplicating the same
    # full per-role breakdown as the dedicated /contres/ page below -- see
    # that page's own module comment): the single toughest and single
    # easiest real matchup, flattened across every role, sorted by games so
    # a fluke low-sample pairing can't be picked over a well-observed one.
    all_enemies = [
        {**e, "role_label": m["role_label"]}
        for m in matchups for e in m["enemies"]
    ]
    toughest_counter = min(all_enemies, key=lambda e: e["win_rate"]) if all_enemies else None
    easiest_matchup = max(all_enemies, key=lambda e: e["win_rate"]) if all_enemies else None
    matchups_preview = sorted(all_enemies, key=lambda e: -e["games"])[:3]

    # Real rune pages -- see lol_run.py --runes-out. A page's identity is
    # its keystone + secondary tree combo (e.g. "Cadence Fatale + Sorcellerie"),
    # not the keystone alone.
    rune_pages = []
    for row in (runes_by_champion.get(c["id"]) or []):
        keystone = rune_by_id.get(row["keystone_id"])
        tree = tree_by_id.get(row["secondary_tree_id"])
        if not keystone or not tree:
            continue
        rune_pages.append({
            "keystone_icon": keystone["icon_file"], "keystone_name": keystone["name_fr"] if lang == "fr" else keystone["name_en"],
            "tree_icon": tree["icon_file"], "tree_name": tree["name_fr"] if lang == "fr" else tree["name_en"],
            "games": row["games"], "win_rate": row["win_rate"], "pick_rate": row["pick_rate"],
        })

    base.update({
        "title": c["title_fr"] if lang == "fr" else c["title_en"],
        "blurb": c["blurb_fr"] if lang == "fr" else c["blurb_en"],
        "lore": c["lore_fr"] if lang == "fr" else c["lore_en"],
        "partype": c["partype_fr"] if lang == "fr" else c["partype_en"],
        # partype is localized ("None" -> "Aucune" in fr_FR), so the
        # no-resource check needs the stable English value, not the
        # display string (Warwick/Garen/... have no mana bar at all).
        "has_resource": c["partype_en"] != "None",
        "classes": [class_labels.get(tag, tag) for tag in c["tags"]],
        "passive": c["passive_fr"] if lang == "fr" else c["passive_en"],
        "spells": c["spells_fr"] if lang == "fr" else c["spells_en"],
        "info": c["info"], "stats": c["stats"],
        "role_stats": role_stats,
        "best_items": best_items,
        "matchups": matchups, "matchups_preview": matchups_preview,
        "toughest_counter": toughest_counter, "easiest_matchup": easiest_matchup,
        "rune_pages": rune_pages,
    })
    return base


def breadcrumb_schema(crumbs: list[tuple[str, str]]) -> dict:
    """crumbs: [(name, url), ...] from the homepage to the current page, in
    order -- schema.org BreadcrumbList for rich results (SEO audit,
    2026-09-16). Real hierarchy only: every url here is a real, already-
    canonicalized page on the site (canonical_for()'s own output), never a
    fabricated path."""
    return {
        "@context": "https://schema.org", "@type": "BreadcrumbList",
        "itemListElement": [
            {"@type": "ListItem", "position": i + 1, "name": name, "item": url}
            for i, (name, url) in enumerate(crumbs)
        ],
    }


def build_article_schema(headline: str, url: str, description: str, image: str | None = None) -> dict:
    """schema.org Article for a real content page (champion/item sheet) --
    same shape comp.html's own article_schema dict already uses, factored
    out so champion/item detail pages (both games) can get the same rich-
    result treatment without repeating the boilerplate (SEO audit,
    2026-09-16). No dates: unlike a comp page (tied to one real data
    refresh), these pages update on every Data Dragon/patch refresh with no
    single meaningful "published" moment, so datePublished/dateModified
    are left out rather than guessed."""
    schema = {
        "@context": "https://schema.org", "@type": "Article", "headline": headline,
        "description": description,
        "mainEntityOfPage": {"@type": "WebPage", "@id": url},
        "author": {"@type": "Organization", "name": "BrokenMeta.gg"},
        "publisher": {"@type": "Organization", "name": "BrokenMeta.gg"},
    }
    if image:
        schema["image"] = image
    return schema


def build_lol_patch_icon_lookup(lol_champions: list[dict], lol_items_lookup: dict[str, dict], rune_trees: list[dict]) -> dict[str, dict]:
    """name_en.lower() -> {kind, icon_file, slug} for every champion, every
    item (including ones without their own glossary page -- a patch can
    touch a component, not just finished items), and every rune -- used to
    find a real icon for each PATCHES_LOL change entry by its name_en."""
    lookup: dict[str, dict] = {}
    for c in lol_champions:
        lookup[c["name_en"].lower()] = {"kind": "champion", "icon_file": c["icon_file"], "slug": c["slug"]}
    for it in lol_items_lookup.values():
        lookup[it["name_en"].lower()] = {"kind": "item", "icon_file": it["icon_file"], "slug": it["slug"] if it["has_page"] else None}
    for tree in rune_trees:
        for slot in tree["slots"]:
            for r in slot:
                lookup[r["name_en"].lower()] = {"kind": "rune", "icon_file": r["icon_file"], "slug": None}
    return lookup


def lol_patch_change_view(change: dict, lookup: dict[str, dict]) -> dict:
    match = lookup.get(change["name_en"].lower())
    return {
        "status": change["status"], "lines": change["lines"],
        "name": change["name_en"], "icon_kind": match["kind"] if match else None,
        "icon_file": match["icon_file"] if match else None, "slug": match["slug"] if match else None,
    }


LOL_TIER_BUCKETS = [("S", 0.10), ("A", 0.30), ("B", 0.65), ("C", 1.0)]

# Same role glyphs as league.js's ROLE_ICON (client-side, profile page role
